window.PTA_LOCAL_BANK = {"schemaVersion":1,"name":"CCF PTA 教学能力 T1 历年真题题库","source":"local","generatedAt":"2026-09-22","count":300,"questions":[{"id":"L1-S01","source":"local","sourceLabel":"（本地：第1卷第1题）","vol":1,"no":1,"section":"单选","sectionNo":1,"type":"single","score":3,"stem":"新中国建立初期，我国师范院校教育学课程普遍采用的教材是（  ）","options":["夸美纽斯的《大教学论》","赫尔巴特的《普通教育学》","凯洛夫的《教育学》","马卡连柯的《论共产主义教育》"],"answer":["C"],"analysis":"新中国成立初期我国教育全面学习苏联经验，师范院校普遍采用凯洛夫主编的《教育学》作为教材。夸美纽斯《大教学论》标志教育学开始独立，赫尔巴特《普通教育学》标志规范教育学建立，马卡连柯以集体教育思想著称，均非当时通用教材。","hint":"抓住时间限定“新中国建立初期”，联想当时全面学苏联的历史背景。","tags":["教育史","教育学教材","凯洛夫"],"category":"教育学原理"},{"id":"L1-S02","source":"local","sourceLabel":"（本地：第1卷第2题）","vol":1,"no":2,"section":"单选","sectionNo":2,"type":"single","score":3,"stem":"学校教育具有促进个体发展和社会发展的功能，其中个体发展主要体现为（  ）","options":["个性化与道德化","社会化与个性化","社会化与标准化","个性化与趋同化"],"answer":["B"],"analysis":"教育的个体发展功能集中表现为个体社会化与个体个性化：社会化使人适应社会规范，个性化使人形成独特自我。A的“道德化”不是规范表述；C的“标准化”、D的“趋同化”都与个性化相悖。","hint":"个体发展=适应社会+形成独特自我，两个关键词缺一不可。","tags":["教育功能","个体发展","社会化与个性化"],"category":"教育学原理"},{"id":"L1-S03","source":"local","sourceLabel":"（本地：第1卷第3题）","vol":1,"no":3,"section":"单选","sectionNo":3,"type":"single","score":3,"stem":"马克思主义认为，实现人的全面发展的唯一途径是（  ）","options":["学校教育与社会教育相结合","脑力劳动与体力劳动相结合","教育与生产劳动相结合","知识分子与工人农民相结合"],"answer":["C"],"analysis":"马克思主义认为，教育与生产劳动相结合是培养全面发展的人的唯一途径。A、B、D提到的结合方式都是片面的具体形式，并非经典论断中的“唯一途径”。","hint":"记马克思关于人的全面发展的经典论断关键词：生产劳动。","tags":["教育目的","全面发展","马克思主义教育思想"],"category":"教育学原理"},{"id":"L1-S04","source":"local","sourceLabel":"（本地：第1卷第4题）","vol":1,"no":4,"section":"单选","sectionNo":4,"type":"single","score":3,"stem":"学校教育制度一般是指一个国家的（  ）","options":["各级各类学校内部的各种制度","级各类学校的领导管理体制","各级各类学校的办学体制","各级各类学校的总体系"],"answer":["D"],"analysis":"学校教育制度（学制）是一个国家各级各类学校的总体系，规定学校性质、任务、入学条件、修业年限及相互衔接。A、B、C只描述学校内部某一方面的制度，范围过窄。","hint":"学制是国家层面“学校系统的总框架”，选范围最大的那个。","tags":["教育制度","学制"],"category":"教育学原理"},{"id":"L1-S05","source":"local","sourceLabel":"（本地：第1卷第5题）","vol":1,"no":5,"section":"单选","sectionNo":5,"type":"single","score":3,"stem":"美国实用主义教育家杜威所倡导的课程理论是（  ）","options":["学科课程论","活动课程论","要素主义课程论","永恒主义课程论"],"answer":["B"],"analysis":"杜威是实用主义教育代表人物，主张“从做中学”，倡导以儿童经验为中心的活动课程。学科课程论以赫尔巴特为代表，要素主义、永恒主义属新传统教育派，均非杜威主张。","hint":"杜威=实用主义=儿童中心=从做中学。","tags":["课程理论","杜威","活动课程"],"category":"教育学原理"},{"id":"L1-S06","source":"local","sourceLabel":"（本地：第1卷第6题）","vol":1,"no":6,"section":"单选","sectionNo":6,"type":"single","score":3,"stem":"王老师在讲授“磷及其化合物的性质”时，以磷化氢的“自燃”现象，说明民间俗称“火”现象产生的原因，对学生进行了“无神论”教育。王老师在教学中主要贯彻的是（  ）","options":["循序渐进原则","直观性原则","科学性和思想性相结合","启发性原则"],"answer":["C"],"analysis":"用科学知识解释自燃现象的同时进行无神论教育，体现科学性与思想性（教育性）相统一原则。循序渐进强调顺序性，直观性强调感官感知，启发性强调调动思维，均不合题意。","hint":"既教知识又教思想，抓“科学知识+思想教育”双线。","tags":["教学原则","科学性与思想性统一"],"category":"教育学原理"},{"id":"L1-S07","source":"local","sourceLabel":"（本地：第1卷第7题）","vol":1,"no":7,"section":"单选","sectionNo":7,"type":"single","score":3,"stem":"晓东期中考试成绩不理想，其父母承诺如果期末考试成绩优异，就奖励他一部手机，于是他学习更加努力。晓东的这种学习动机属于（  ）","options":["近景、外部动机","近景、内部动机","远景、外部动机","远景、内部动机"],"answer":["A"],"analysis":"期末考试是近期目标，属近景动机；奖励手机是外部诱因带来的动力，属外部动机。内部动机来自对学习本身的兴趣，远景动机指向长远目标与理想。","hint":"从“时间远近”和“动力来源内外”两个维度分别判断。","tags":["学习动机","动机分类"],"category":"教育心理"},{"id":"L1-S08","source":"local","sourceLabel":"（本地：第1卷第8题）","vol":1,"no":8,"section":"单选","sectionNo":8,"type":"single","score":3,"stem":"世界上最早专门论述教育的文献是（  ）","options":["《学记》","《论语》","《论演说家的教育》","《理想国》"],"answer":["A"],"analysis":"《学记》成书于战国后期，是世界上最早专门论述教育问题的著作，比昆体良的《论演说家的教育》早约三百年。《论语》是语录体，《理想国》是哲学著作，均非专门教育论著。","hint":"世界最早且专门论述教育的著作=中国战国后期的《学记》。","tags":["教育史","《学记》"],"category":"教育学原理"},{"id":"L1-S09","source":"local","sourceLabel":"（本地：第1卷第9题）","vol":1,"no":9,"section":"单选","sectionNo":9,"type":"single","score":3,"stem":"梦佳理解了“物质决定意识，意识反作用于物质”的涵义。按照皮亚杰的认知发展阶段理论，梦佳的思维发展水平处于（  ）","options":["感知运动阶段","前运算阶段","具体运算段","形式运算阶段"],"answer":["D"],"analysis":"理解“物质决定意识、意识反作用于物质”这类抽象哲理命题，需要假设演绎与抽象逻辑思维，属形式运算阶段。感知运动靠感觉动作，前运算自我中心，具体运算需具体事物支持，均达不到。","hint":"能进行抽象哲理思辨，就找皮亚杰四阶段里最高级的那个。","tags":["皮亚杰","认知发展阶段","形式运算"],"category":"教育心理"},{"id":"L1-S10","source":"local","sourceLabel":"（本地：第1卷第10题）","vol":1,"no":10,"section":"单选","sectionNo":10,"type":"single","score":3,"stem":"晓军上中学后，自尊心越来越强，自我评价越来越客观、全面，自我控制能力明显提高。这反映的是晓军自我意识哪一方面的发展？（  ）","options":["生理自我","心理自我","社会自我","物质自我"],"answer":["B"],"analysis":"自尊心、自我评价、自我控制属于个体对自身心理特征的认识与调控，即心理自我的发展。生理自我是对身体外貌的意识，社会自我是对人际角色与社会地位的认识。","hint":"自尊、自我评价、自控——都属于“心理层面”的自我。","tags":["自我意识","心理自我"],"category":"教育心理"},{"id":"L1-S11","source":"local","sourceLabel":"（本地：第1卷第11题）","vol":1,"no":11,"section":"单选","sectionNo":11,"type":"single","score":3,"stem":"高三学生志强认为做事应达到尽善尽美，因此他对自己要求很高，常常因偶尔的考试成绩不理想而情绪低落，心理辅导教师通过纠正其不合理信念来调整他的情绪。该教师采用的心理辅导方法是（  ）","options":["理性情绪疗法","系统脱敏法","阳性强化法","来访者中心疗法"],"answer":["A"],"analysis":"理性情绪疗法（ABC理论）由艾利斯提出，认为不良情绪源于不合理信念，通过纠正不合理信念调节情绪。系统脱敏用于消除焦虑，阳性强化侧重塑造行为，来访者中心强调无条件积极关注。","hint":"题干出现“纠正不合理信念”，直接对应理性情绪疗法。","tags":["心理辅导","理性情绪疗法"],"category":"教育心理"},{"id":"L1-S12","source":"local","sourceLabel":"（本地：第1卷第12题）","vol":1,"no":12,"section":"单选","sectionNo":12,"type":"single","score":3,"stem":"晓旭认为服从、听话的孩子就是好孩子，于是她对老师和家长绝对遵从，期望得到他们的赞许。根据科尔伯格的道德发展理论，她的道德发展处于（  ）","options":["社会契约取向阶段","相对功利取向阶段","寻求认可取向阶段","遵守法规取向阶段"],"answer":["C"],"analysis":"科尔伯格习俗水平中的“好孩子”取向即寻求认可取向，表现为服从权威期待、希望获得他人赞许。相对功利属前习俗水平，遵守法规属习俗的维护权威阶段，社会契约属后习俗水平。","hint":"“好孩子”“希望得到赞许”=寻求认可取向。","tags":["科尔伯格","道德发展阶段"],"category":"教育心理"},{"id":"L1-S13","source":"local","sourceLabel":"（本地：第1卷第13题）","vol":1,"no":13,"section":"单选","sectionNo":13,"type":"single","score":3,"stem":"刚进入高一，赵峰就总想“我考不上大学该怎么办？”。他明知离高考还远着呢，这么早想这个事根本没必要，但就是控制不住，以至于影响了正常学习。他的主要心理问题是（  ）","options":["强迫观念","强迫行为","恐惧观念","恐惧行为"],"answer":["A"],"analysis":"明知没必要却无法摆脱的反复想法属强迫观念；强迫行为指反复动作。恐惧症表现为对特定对象的强烈惧怕，题干无惧怕对象，且“观念/行为”指向强迫而非恐惧。","hint":"想摆脱却摆脱不了的“想法”是强迫观念；若是“动作”才是强迫行为。","tags":["心理健康","强迫症"],"category":"教育心理"},{"id":"L1-S14","source":"local","sourceLabel":"（本地：第1卷第14题）","vol":1,"no":14,"section":"单选","sectionNo":14,"type":"single","score":3,"stem":"王建在课堂上玩手机，老师没有直接提出批评，而是表扬了认真听讲的冯军。王建看了看冯军，也开始认真听讲了。该老师使用的课堂管理方法是（  ）","options":["直接干预","替代强化","团体警觉","处理转换"],"answer":["B"],"analysis":"班杜拉的替代强化指观察者因看到榜样行为被强化而自身行为受影响。老师表扬旁人使王建模仿，属替代强化。直接干预是明示纠正，团体警觉面向全体提醒，处理转换指活动过渡管理。","hint":"不批评本人、表扬旁人来影响本人，就是榜样替代。","tags":["课堂管理","班杜拉","替代强化"],"category":"教学技能与实践"},{"id":"L1-S15","source":"local","sourceLabel":"（本地：第1卷第15题）","vol":1,"no":15,"section":"单选","sectionNo":15,"type":"single","score":3,"stem":"学生课前预习，带着不懂的问题去上课，以便更有针对性地注意听讲。这种注意方式属于（  ）","options":["有意注意","无意注意","无意后注意","有意后注意"],"answer":["A"],"analysis":"带着问题、有目的且需意志努力的注意是有意注意。无意注意无目的不需意志努力；有意后注意是有目的但已不需意志努力的熟练状态。","hint":"有目的+需要意志努力=有意注意。","tags":["注意","有意注意"],"category":"教育心理"},{"id":"L1-S16","source":"local","sourceLabel":"（本地：第1卷第16题）","vol":1,"no":16,"section":"单选","sectionNo":16,"type":"single","score":3,"stem":"“学习过程就是尝试错误的过程”，这一观点属于哪种学习理论？（  ）","options":["行为主义","认知主义","人本主义","建构主义"],"answer":["A"],"analysis":"桑代克认为学习是“尝试—错误”的过程（试误说），属行为主义联结理论。认知主义强调内部认知结构，人本主义强调自我实现，建构主义强调主动建构意义。","hint":"“尝试错误”是桑代克的试误说，归行为主义。","tags":["学习理论","行为主义","桑代克"],"category":"教育心理"},{"id":"L1-S17","source":"local","sourceLabel":"（本地：第1卷第17题）","vol":1,"no":17,"section":"单选","sectionNo":17,"type":"single","score":3,"stem":"刘老师在教学过程中善于引导学生掌握知识、积极思考、运用多种策略解决问题这说明他的哪种教学能力比较突出？（  ）","options":["教学认知能力","教学反思能力","教学监控能力","教学操作能力"],"answer":["D"],"analysis":"引导学生掌握知识、积极思考、运用策略解决问题，是在课堂中实际组织实施教学的能力，即教学操作能力。教学认知是对教学的认识，教学反思是回溯思考，教学监控是对过程的调节控制。","hint":"课堂上“做”出来的能力=教学操作能力。","tags":["教师能力","教学操作能力"],"category":"教学技能与实践"},{"id":"L1-S18","source":"local","sourceLabel":"（本地：第1卷第18题）","vol":1,"no":18,"section":"单选","sectionNo":18,"type":"single","score":3,"stem":"教学过程是一种特殊的认识过程，其区别于人类一般认识的特点是（  ）","options":["主动性、间接性和引导性","探索性、间接性和引导性","间接性、引导性和简捷性","间接性、引导性和复杂性"],"answer":["C"],"analysis":"教学认识的特殊性表现为间接性（以书本间接经验为主）、引导性（在教师引导下认识）、简捷性（走人类认识的捷径）。主动性、探索性、复杂性都不是其规范概括。","hint":"三性口诀：间接、引导、简捷。","tags":["教学过程","教学认识特殊性"],"category":"教育学原理"},{"id":"L1-S19","source":"local","sourceLabel":"（本地：第1卷第19题）","vol":1,"no":19,"section":"单选","sectionNo":19,"type":"single","score":3,"stem":"阳慧在解决问题的过程中，常以老师、同学的建议作为参照做出决策。她的这种认知风格属于（  ）","options":["场依存型","场独立型","继时型","同时型"],"answer":["A"],"analysis":"场依存型认知风格者依赖外部参照，易受他人暗示与环境线索影响。场独立型依靠内部参照；继时型与同时型按信息加工方式划分，与外部参照无关。","hint":"决策依赖他人建议=外部参照=场依存型。","tags":["认知风格","场依存"],"category":"教育心理"},{"id":"L1-S20","source":"local","sourceLabel":"（本地：第1卷第20题）","vol":1,"no":20,"section":"单选","sectionNo":20,"type":"single","score":3,"stem":"李利今天新学习了20个英文单词，放学后，他就一遍一遍地背诵，直至背会全部单词，这种学习策略属于（  ）","options":["监控策略","组织策略","计划策略","复述策略"],"answer":["D"],"analysis":"一遍遍诵读直至背会属于复述策略（通过重复保持信息）。组织策略是归类、列提纲，计划策略属元认知中的事前规划，监控策略是对学习过程的监视调节。","hint":"重复诵读以记住=复述策略。","tags":["学习策略","复述策略"],"category":"教育心理"},{"id":"L1-M01","source":"local","sourceLabel":"（本地：第1卷第21题）","vol":1,"no":21,"section":"多选","sectionNo":1,"type":"multi","score":4,"stem":"讲授法是教师通过口头语言系统连贯的向学生传授知识的方法，主要有以下哪几种方式（  ）","options":["讲述","描述","讲解","讲演"],"answer":["A","C","D"],"analysis":"讲授法的具体方式包括讲述、讲解、讲读、讲演，A、C、D属于其中；B“描述”是文学表达方式，不是讲授法的规范类型，故排除。","hint":"讲授四方式：讲述、讲解、讲读、讲演——排除不在其中的。","tags":["教学方法","讲授法"],"category":"教育学原理"},{"id":"L1-M02","source":"local","sourceLabel":"（本地：第1卷第22题）","vol":1,"no":22,"section":"多选","sectionNo":2,"type":"multi","score":4,"stem":"讲授技能的应用原则包括（  ）","options":["科学性原则","启发性原则","阶段性原则","精通性原则"],"answer":["A","B","C","D"],"analysis":"讲授技能的应用原则包括科学性（内容正确）、启发性（引导思维）、阶段性（循序渐进）、精通性（教师吃透内容），四项都是讲授应遵循的要求。","hint":"讲授既要内容科学，又要能启发、有层次、讲得透。","tags":["教学技能","讲授法"],"category":"教学技能与实践"},{"id":"L1-M03","source":"local","sourceLabel":"（本地：第1卷第23题）","vol":1,"no":23,"section":"多选","sectionNo":3,"type":"multi","score":4,"stem":"讲授法的主要缺点在于（  ）","options":["过分强调教师的主导作用，忽视学生的主体地位","不利于启发学生的思维和想象","面向全体学生，无法照顾学生的个别差异","不利于学生解决问题能力的提升"],"answer":["A","B","C","D"],"analysis":"讲授法的公认局限：教师主导过度忽视学生主体地位、不利于启发思维与想象、面向全体难以照顾个别差异、不利于解决问题能力培养，四项均成立。","hint":"讲授法的缺点集中在“学生被动”和“难因材施教”两条线上。","tags":["教学方法","讲授法"],"category":"教育学原理"},{"id":"L1-M04","source":"local","sourceLabel":"（本地：第1卷第24题）","vol":1,"no":24,"section":"多选","sectionNo":4,"type":"multi","score":4,"stem":"板书的主要功能包括（  ）","options":["概括功能","美育功能","互动功能","示范功能"],"answer":["A","B","C","D"],"analysis":"板书具有概括功能（提炼要点）、美育功能（书写规范美观）、互动功能（随课堂生成交流）、示范功能（规范示范），四项均为板书功能。","hint":"板书不只是“写字”，还有美育、示范、互动的作用。","tags":["教学技能","板书"],"category":"教学技能与实践"},{"id":"L1-M05","source":"local","sourceLabel":"（本地：第1卷第25题）","vol":1,"no":25,"section":"多选","sectionNo":5,"type":"multi","score":4,"stem":"课堂教学反馈的特点表现为（  ）","options":["多样性","思辨性","评议性","差异性"],"answer":["A","B","C","D"],"analysis":"课堂教学反馈具有多样性（方式多种）、思辨性（需分析判断）、评议性（含评价议论）、差异性（因人而异），四项均为其特征。","hint":"反馈特点四词：多样、思辨、评议、差异。","tags":["教学技能","课堂反馈"],"category":"教学技能与实践"},{"id":"L1-M06","source":"local","sourceLabel":"（本地：第1卷第26题）","vol":1,"no":26,"section":"多选","sectionNo":6,"type":"multi","score":4,"stem":"对课堂问题行为产生影响的教师方面的因素主要有（  ）","options":["教学不当","和蔼温柔","管理不当","丧失威信"],"answer":["A","C","D"],"analysis":"引发课堂问题行为的教师因素包括教学不当、管理不当、丧失威信等；B“和蔼温柔”是良好教师品质，不会诱发问题行为，故排除。","hint":"排除法：正面品质不会导致问题行为。","tags":["课堂管理","问题行为"],"category":"教学技能与实践"},{"id":"L1-M07","source":"local","sourceLabel":"（本地：第1卷第27题）","vol":1,"no":27,"section":"多选","sectionNo":7,"type":"multi","score":4,"stem":"教学组织管理的原则包括（  ）","options":["明确目的，教书育人","了解学生，尊重学生","重视集体，形成风气","灵活应变，因势利导"],"answer":["A","B","C","D"],"analysis":"教学组织管理原则包括明确目的教书育人、了解并尊重学生、重视集体形成风气、灵活应变因势利导，四项均属其原则。","hint":"组织管理原则围绕“目的、学生、集体、灵活”四个维度。","tags":["课堂管理","教学组织"],"category":"教学技能与实践"},{"id":"L1-M08","source":"local","sourceLabel":"（本地：第1卷第28题）","vol":1,"no":28,"section":"多选","sectionNo":8,"type":"multi","score":4,"stem":"对于探究性学习的组织与引导，以下说法恰当的是（  ）","options":["教师只帮助学生澄清问题，并不给出直接的答案","问题一般要由教师给出","鼓励学生通过试验或参考其它资料来检验其合理性","激发学生的问题意识是探究性学习的核心"],"answer":["A","C","D"],"analysis":"探究性学习强调学生自主发现问题：教师只帮助澄清问题不直接给答案、鼓励检验其合理性、激发问题意识是核心。B“问题一般由教师给出”违背学生自主探究，故排除。","hint":"探究学习的核心是“学生自己提问题”，教师不包办。","tags":["学习方式","探究性学习"],"category":"教学技能与实践"},{"id":"L1-M09","source":"local","sourceLabel":"（本地：第1卷第29题）","vol":1,"no":29,"section":"多选","sectionNo":9,"type":"multi","score":4,"stem":"教师在学生自主学习中的作用主要表现在（  ）","options":["鼓舞和激励","指引方向","提供反馈","释疑解疑"],"answer":["A","B","C","D"],"analysis":"自主学习不等于放任自流，教师应发挥鼓舞激励、指引方向、提供反馈、释疑解疑的作用，四项均属教师应扮演的角色。","hint":"自主学习里教师是“支持者”，不是“退出者”。","tags":["学习方式","自主学习"],"category":"教学技能与实践"},{"id":"L1-M10","source":"local","sourceLabel":"（本地：第1卷第30题）","vol":1,"no":30,"section":"多选","sectionNo":10,"type":"multi","score":4,"stem":"以下关于问题导入形式的说法，正确的是（  ）","options":["可以单刀直入，直接提出问题","可以从侧面提问设置悬疑","只能由教师提问","可以由“谜语”等形式来呈现"],"answer":["A","B","D"],"analysis":"问题导入形式灵活：可直接提出问题、可从侧面设悬疑、可借谜语等形式呈现。C“只能由教师提问”表述绝对化，学生也可质疑提问，故排除。","hint":"见到“只能”“必须”这类绝对表述，优先怀疑。","tags":["教学技能","课堂导入"],"category":"教学技能与实践"},{"id":"L2-S01","source":"local","sourceLabel":"（本地：第2卷第1题）","vol":2,"no":1,"section":"单选","sectionNo":1,"type":"single","score":3,"stem":"我国古代思想家墨子认为，人的发展犹如白布放进染缸，“染于苍则苍，染于黄则黄。所入者变，其色亦变”。墨子的这种观点属于（  ）","options":["遗传决定论","环境决定论","教育主导论","主体能动论"],"answer":["B"],"analysis":"墨子以白布入染缸作比，强调后天环境对人的决定作用，属环境决定论（外铄论）。遗传决定论强调先天禀赋，教育主导论强调教育作用，主体能动论强调主观努力，均与“染于苍则苍”的比喻不符。","hint":"白布放进染缸——比喻外界环境的塑造作用。","tags":["影响人发展的因素","环境决定论"],"category":"教育学原理"},{"id":"L2-S02","source":"local","sourceLabel":"（本地：第2卷第2题）","vol":2,"no":2,"section":"单选","sectionNo":2,"type":"single","score":3,"stem":"赵敏课堂上不敢主动发言，有疑难问题也没有勇气向老师请教。为了改变她的这一缺点，老师给她更多的鼓励和机会，当她主动提问时，就及时给予表扬。这种促进行为改变的方法属于（  ）","options":["行为强化法","精神分析法","榜样示范法","系统脱敏法"],"answer":["A"],"analysis":"教师用表扬（正强化）增加学生主动提问的行为，属行为强化法。精神分析法重潜意识冲突，榜样示范法重模仿他人，系统脱敏法用于逐步消除焦虑，均不合题意。","hint":"用表扬去增加某个好行为=正强化。","tags":["心理辅导","行为强化"],"category":"教育心理"},{"id":"L2-S03","source":"local","sourceLabel":"（本地：第2卷第3题）","vol":2,"no":3,"section":"单选","sectionNo":3,"type":"single","score":3,"stem":"同学们正在教室里聚精会神地听老师讲课，突然从教室外飞进来一只小鸟，于是大家不约而同地把视线朝向小鸟。这种现象属于（  ）","options":["随意前注意","随意后注意","无意注意","有意注意"],"answer":["C"],"analysis":"小鸟突然飞入引起无预定目的、不需意志努力的注意，属无意注意。有意注意有目的且需意志努力；随意后注意是有目的但已不需意志努力；A“随意前注意”不是规范分类。","hint":"突如其来的刺激自动吸引注意=无意注意。","tags":["注意","无意注意"],"category":"教育心理"},{"id":"L2-S04","source":"local","sourceLabel":"（本地：第2卷第4题）","vol":2,"no":4,"section":"单选","sectionNo":4,"type":"single","score":3,"stem":"李伟同学在上课前会对本节课的内容进行判断，如果认为自己能听懂老师讲述的知识，他就会认真听课。根据班杜拉的理论，这种现象是（  ）","options":["结果期待","过程期待","社会期待","效能期待"],"answer":["D"],"analysis":"班杜拉区分结果期待（对行为会带来何种结果的估计）与效能期待（对自己能否完成该行为的判断）。“认为自己能听懂”是对自身能力的判断，属效能期待（自我效能感）。","hint":"判断“我能不能做到”是效能期待；判断“做了会怎样”是结果期待。","tags":["班杜拉","自我效能感"],"category":"教育心理"},{"id":"L2-S05","source":"local","sourceLabel":"（本地：第2卷第5题）","vol":2,"no":5,"section":"单选","sectionNo":5,"type":"single","score":3,"stem":"晓东期中考试成绩不理想，其父母承诺如果期末考试成绩优异，就奖励他一部手机，于是他学习更加努力。晓东的这种学习动机属于（  ）","options":["近景、外部动机","近景、内部动机","远景、外部动机","远景、内部动机"],"answer":["A"],"analysis":"期末考试是近期目标，属近景动机；手机奖励是外部诱因，属外部动机。内部动机来自对学习本身的兴趣，远景动机指向长远理想。","hint":"按“时间远近”和“动力内外”两个维度分别判断。","tags":["学习动机","动机分类"],"category":"教育心理"},{"id":"L2-S06","source":"local","sourceLabel":"（本地：第2卷第6题）","vol":2,"no":6,"section":"单选","sectionNo":6,"type":"single","score":3,"stem":"人类历史上最早专门论述教育问题的著作是（  ）","options":["《学记》","《孟子》","《论语》","《中庸》"],"answer":["A"],"analysis":"《学记》成书于战国后期，是世界上最早专门论述教育问题的著作。《论语》《孟子》《中庸》均为儒家经典，但不是专门的教育理论著作。","hint":"世界最早且专门论述教育=《学记》。","tags":["教育史","《学记》"],"category":"教育学原理"},{"id":"L2-S07","source":"local","sourceLabel":"（本地：第2卷第7题）","vol":2,"no":7,"section":"单选","sectionNo":7,"type":"single","score":3,"stem":"新课程改革以来，不少中学把“档案袋评价”作为评价学生的方式之一。这种评价属于（  ）","options":["诊断性评价","形成性评价","终结性评价","标准性评价"],"answer":["B"],"analysis":"档案袋评价收集学生学习过程中的作品与记录，用于改进学与教，属形成性评价。诊断性评价在教学前摸底，终结性评价在教学结束后作总结判断。","hint":"记录“过程”的评价=形成性评价。","tags":["教学评价","形成性评价"],"category":"教学技能与实践"},{"id":"L2-S08","source":"local","sourceLabel":"（本地：第2卷第8题）","vol":2,"no":8,"section":"单选","sectionNo":8,"type":"single","score":3,"stem":"晓旭认为服从、听话的孩子就是好孩子，于是她对老师和家长绝对遵从，期望得到他们的赞许。根据科尔伯格的道德发展理论，她的道德发展处于（  ）","options":["社会契约取向阶段","相对功利取向阶段","寻求认可取向阶段","遵守法规取向阶段"],"answer":["C"],"analysis":"“好孩子”取向即寻求认可取向，表现为服从权威期待、希望获得赞许。相对功利取向属前习俗水平，遵守法规取向强调维护社会秩序，社会契约取向属后习俗水平。","hint":"“希望得到赞许”=寻求认可（好孩子）取向。","tags":["科尔伯格","道德发展阶段"],"category":"教育心理"},{"id":"L2-S09","source":"local","sourceLabel":"（本地：第2卷第9题）","vol":2,"no":9,"section":"单选","sectionNo":9,"type":"single","score":3,"stem":"有人认为，教育投资是有效的生产性投资。这种观点主要反映了教育的哪种功能？（  ）","options":["政治功能","经济功能","文化功能","生态功能"],"answer":["B"],"analysis":"把教育视为能带来回报的生产性投资，体现教育的经济功能。政治功能指向政权与民主，文化功能指向文化传承与创新，生态功能指向人与自然。","hint":"“投资—回报”是典型的经济视角。","tags":["教育功能","经济功能"],"category":"教育学原理"},{"id":"L2-S10","source":"local","sourceLabel":"（本地：第2卷第10题）","vol":2,"no":10,"section":"单选","sectionNo":10,"type":"single","score":3,"stem":"王老师在教学工作中善于采用各种教学策略，取得了很好的教学效果。这反映了王老师的哪一方面能力突出？（  ）","options":["教学操作","教学归因","教学迁移","教学反思"],"answer":["A"],"analysis":"善于采用各种教学策略并取得良好效果，是课堂组织实施层面的能力，即教学操作能力。教学归因是对成败原因的解释，教学迁移是经验迁移，教学反思是事后回溯改进。","hint":"课堂上实际“做”出来的能力=教学操作能力。","tags":["教师能力","教学操作能力"],"category":"教学技能与实践"},{"id":"L2-S11","source":"local","sourceLabel":"（本地：第2卷第11题）","vol":2,"no":11,"section":"单选","sectionNo":11,"type":"single","score":3,"stem":"近年来我国对农村中小学的布局结构进行了调整。这主要反映了下列哪一因素对教育的影响？（  ）","options":["政治制度","经济制度","人口变化","文化传统"],"answer":["C"],"analysis":"农村中小学布局调整的直接原因是学龄人口减少与人口流动，属人口因素对教育的影响。政治制度、经济制度、文化传统都属于影响因素，但不是布局调整的主因。","hint":"学校“布局调整”主要由学生数量与分布变化引起。","tags":["教育与社会","人口"],"category":"教育学原理"},{"id":"L2-S12","source":"local","sourceLabel":"（本地：第2卷第12题）","vol":2,"no":12,"section":"单选","sectionNo":12,"type":"single","score":3,"stem":"2015年修正的《中华人民共和国教育法》中明确规定，我国教育的性质和方向是（  ）","options":["教育必须为社会主义现代化建设服务，为社会生活服务","教育必须为社会主义现代化建设服务，为人民服务","教育必须为社会主义物质文明建设服务，为精神文明建设服务","教育必须为社会主义建设服务，为人的发展服务"],"answer":["B"],"analysis":"2015年修正的《教育法》规定：教育必须为社会主义现代化建设服务、为人民服务，必须与生产劳动和社会实践相结合。A、C、D的表述均不是现行法条的准确表述。","hint":"记住“两个服务”：为现代化建设服务、为人民服务。","tags":["教育法律法规","教育法"],"category":"教育法律法规"},{"id":"L2-S13","source":"local","sourceLabel":"（本地：第2卷第13题）","vol":2,"no":13,"section":"单选","sectionNo":13,"type":"single","score":3,"stem":"我国唐代中央官学设有“六学二馆”，其人学条件中明文规定不同级别官员的子孙进入不同的学校。这主要体现了我国封建社会教育制度的哪一特征？（  ）","options":["继承性","等级性","历史性","民族性"],"answer":["B"],"analysis":"按官员品级决定子孙进入不同学校，体现封建社会教育的等级性。继承性指教育的历史延续，历史性指不同时代教育的差异，民族性指民族间的差异。","hint":"按身份级别区别对待=等级性。","tags":["教育制度","古代教育特征"],"category":"教育学原理"},{"id":"L2-S14","source":"local","sourceLabel":"（本地：第2卷第14题）","vol":2,"no":14,"section":"单选","sectionNo":14,"type":"single","score":3,"stem":"当前我国中学开设的数学、语文、英语等课程属于（  ）","options":["学科课程","活动课程","经验课程","社会课程"],"answer":["A"],"analysis":"数学、语文、英语按学科知识体系设置，属学科课程（分科课程）。活动课程与经验课程以儿童直接经验为中心，社会课程以社会问题为中心组织内容。","hint":"按学科门类设置的课程=学科课程。","tags":["课程类型","学科课程"],"category":"教育学原理"},{"id":"L2-S15","source":"local","sourceLabel":"（本地：第2卷第15题）","vol":2,"no":15,"section":"单选","sectionNo":15,"type":"single","score":3,"stem":"我国《基础教育课程改革纲要(试行)》规定，在课程设置上，高中阶段属于（  ）","options":["以综合课程为主","以分科课程为主","以实践活动课程为主","设置分科与综合相结合的课程"],"answer":["B"],"analysis":"《基础教育课程改革纲要（试行）》规定：小学以综合课程为主，初中设置分科与综合相结合的课程，高中以分科课程为主。","hint":"课改课程结构口诀：小学综合、初中结合、高中分科。","tags":["新课改","课程结构"],"category":"教育学原理"},{"id":"L2-S16","source":"local","sourceLabel":"（本地：第2卷第16题）","vol":2,"no":16,"section":"单选","sectionNo":16,"type":"single","score":3,"stem":"皮格马利翁效应的主要启示是，教师对学生应该（  ）","options":["鼓励合作学习","给予积极期望","提出纪律要求","引导发现学习"],"answer":["B"],"analysis":"皮格马利翁效应即教师期望效应：教师的积极期望会潜移默化地提高学生表现，启示教师对学生给予积极期望。鼓励合作学习、提出纪律要求、引导发现学习都不是该效应的核心启示。","hint":"皮格马利翁效应又称“期望效应”。","tags":["教师心理","期望效应"],"category":"教育学原理"},{"id":"L2-S17","source":"local","sourceLabel":"（本地：第2卷第17题）","vol":2,"no":17,"section":"单选","sectionNo":17,"type":"single","score":3,"stem":"李老师对自己的教学能力十分自信，认为自己能教好学生。这主要反映了他的哪种心理特征？（  ）","options":["教学责任感","教学幸福感","教学理智感","教学效能感"],"answer":["D"],"analysis":"相信自己能教好学生，是对自身教学能力的信念，属教学效能感。教学责任感强调职责担当，教学幸福感强调情感体验，教学理智感强调理性判断。","hint":"对自身教学能力的自信=教学效能感。","tags":["教师心理","教学效能感"],"category":"教育学原理"},{"id":"L2-S18","source":"local","sourceLabel":"（本地：第2卷第18题）","vol":2,"no":18,"section":"单选","sectionNo":18,"type":"single","score":3,"stem":"苏联教育家赞可夫倡导的是（  ）","options":["发现学习理论","教学过程最优化理论","教学与发展理论","范例教学理论"],"answer":["C"],"analysis":"赞可夫提出发展性教学理论（教学与发展）。发现学习理论由布鲁纳提出，教学过程最优化理论由巴班斯基提出，范例教学理论由瓦·根舍因提出。","hint":"教育家与理论要对应记：赞可夫=发展性教学。","tags":["教育家","赞可夫"],"category":"教育学原理"},{"id":"L2-S19","source":"local","sourceLabel":"（本地：第2卷第19题）","vol":2,"no":19,"section":"单选","sectionNo":19,"type":"single","score":3,"stem":"韩波进入中学后，经常独自思考“我是谁？”“未来从事何种职业？”“在社会上处于什么样的地位？”等问题。根据埃里克森的人格发展阶段理论，韩波的人格发展处于（  ）","options":["主动对内疚阶段","同一性对角色混乱阶段","自我整合对绝望阶段","自主对羞耻和疑虑阶段"],"answer":["B"],"analysis":"中学生思考“我是谁”“未来从事何种职业”，是青少年期自我同一性对角色混乱的典型表现。主动对内疚属学前期，自主对羞怯属幼儿期，自我整合对绝望属老年期。","hint":"中学生追问“我是谁”=自我同一性危机。","tags":["埃里克森","人格发展"],"category":"教育心理"},{"id":"L2-S20","source":"local","sourceLabel":"（本地：第2卷第20题）","vol":2,"no":20,"section":"单选","sectionNo":20,"type":"single","score":3,"stem":"李哲爱好广泛，恰逢本周六晚上既有足球赛，又有演唱会，他都想去看。由于二者时间冲突，他很矛盾。他面临的冲突是（  ）","options":["双趋式冲突","双避式冲突","趋避式冲突","多重趋避式冲突"],"answer":["A"],"analysis":"两个都想要但只能取其一，属双趋式冲突。双避式是两个都不想要，趋避式是同一对象既想又怕，多重趋避式是多个对象各有得失。","hint":"两个都想要=双趋冲突。","tags":["意志","动机冲突"],"category":"教育心理"},{"id":"L2-M01","source":"local","sourceLabel":"（本地：第2卷第21题）","vol":2,"no":21,"section":"多选","sectionNo":1,"type":"multi","score":4,"stem":"教学组织管理的原则包括（  ）","options":["明确目的，教书育人","了解学生，尊重学生","重视集体，形成风气","灵活应变，因势利导"],"answer":["A","B","C","D"],"analysis":"教学组织管理原则包括明确目的教书育人、了解尊重学生、重视集体形成风气、灵活应变因势利导，四项均为其原则。","hint":"组织管理原则围绕“目的、学生、集体、灵活”四个维度。","tags":["课堂管理","教学组织"],"category":"教学技能与实践"},{"id":"L2-M02","source":"local","sourceLabel":"（本地：第2卷第22题）","vol":2,"no":22,"section":"多选","sectionNo":2,"type":"multi","score":4,"stem":"对于探究性学习的组织与引导，以下说法恰当的是（  ）","options":["教师只帮助学生澄清问题，并不给出直接的答案","问题一般要由教师给出","鼓励学生通过试验或参考其它资料来检验其合理性","激发学生的问题意识是探究性学习的核心"],"answer":["A","C","D"],"analysis":"探究性学习强调学生自主发现与提出问题，教师只帮助澄清问题不直接给答案，鼓励学生自行检验合理性，激发问题意识是核心。B“问题一般由教师给出”削弱自主探究，故排除。","hint":"探究学习的核心是学生自主，教师不包办问题来源。","tags":["学习方式","探究性学习"],"category":"教学技能与实践"},{"id":"L2-M03","source":"local","sourceLabel":"（本地：第2卷第23题）","vol":2,"no":23,"section":"多选","sectionNo":3,"type":"multi","score":4,"stem":"教师在学生自主学习中的作用主要表现在（  ）","options":["鼓舞和激励","指引方向","提供反馈","释疑解疑"],"answer":["A","B","C","D"],"analysis":"自主学习不等于教师退出，教师应起到鼓舞激励、指引方向、提供反馈、释疑解疑的作用，四项均属教师职责。","hint":"自主学习里教师是“支持者”而非“旁观者”。","tags":["学习方式","自主学习"],"category":"教学技能与实践"},{"id":"L2-M04","source":"local","sourceLabel":"（本地：第2卷第24题）","vol":2,"no":24,"section":"多选","sectionNo":4,"type":"multi","score":4,"stem":"以下关于问题导入的形式的说法，正确的是（  ）","options":["可以单刀直入，直接提出问题","可以从侧面提问设置","只能由教师提问","可以由“谜语”等形式来呈现"],"answer":["A","B","D"],"analysis":"问题导入可直接提出、可从侧面设悬疑、可用谜语等形式，形式灵活。C“只能由教师提问”过于绝对，学生也可提出疑问，故排除。","hint":"见到“只能”这类绝对化表述，优先排除。","tags":["教学技能","课堂导入"],"category":"教学技能与实践"},{"id":"L2-M05","source":"local","sourceLabel":"（本地：第2卷第25题）","vol":2,"no":25,"section":"多选","sectionNo":5,"type":"multi","score":4,"stem":"以下关于课堂导入的说法，恰当的是（  ）","options":["课堂导入没有固定的格式和方法","要以学生为中心","要紧扣教学目标","课堂导入是课堂教学中的重要的一环"],"answer":["A","B","C","D"],"analysis":"课堂导入没有固定模式，应灵活处理；要以学生为中心；要紧扣教学目标；导入是课堂教学的重要环节，四项说法均恰当。","hint":"导入原则：形式灵活、学生中心、紧扣目标。","tags":["教学技能","课堂导入"],"category":"教学技能与实践"},{"id":"L2-M06","source":"local","sourceLabel":"（本地：第2卷第26题）","vol":2,"no":26,"section":"多选","sectionNo":6,"type":"multi","score":4,"stem":"教师在设计课堂导入时的“三宜”是指（  ）","options":["宜灵活多变","宜简洁明快","宜细致详尽","宜回归本真"],"answer":["A","B","D"],"analysis":"课堂导入的“三宜”为宜灵活多变、宜简洁明快、宜回归本真。C“宜细致详尽”与导入应简短明确的要求相悖，故排除。","hint":"导入讲究简洁明快，排除“细致详尽”。","tags":["教学技能","课堂导入"],"category":"教学技能与实践"},{"id":"L2-M07","source":"local","sourceLabel":"（本地：第2卷第27题）","vol":2,"no":27,"section":"多选","sectionNo":7,"type":"multi","score":4,"stem":"大量的课堂问题行为是由学生自身的因素引起的。这些因素主要是（  ）","options":["挫折","寻求关注","性别特征","人格因素"],"answer":["A","B","C","D"],"analysis":"学生自身引发课堂问题行为的因素包括遭受挫折、寻求关注、性别特征、人格因素等，四项均属学生方面的诱因。","hint":"学生自身诱因包括心理需求受挫与人格特点。","tags":["课堂管理","问题行为"],"category":"教学技能与实践"},{"id":"L2-M08","source":"local","sourceLabel":"（本地：第2卷第28题）","vol":2,"no":28,"section":"多选","sectionNo":8,"type":"multi","score":4,"stem":"对于合作学习的组织与引导，以下说法恰当的是（  ）","options":["教师要科学合理地设计合作学习的目标和任务","教师要明确提出合作要求","强调学习环境的布置和安排","强调围绕有价值的问题展开讨论互动和合作"],"answer":["A","B","C","D"],"analysis":"合作学习组织要点：科学设计目标与任务、明确提出合作要求、重视学习环境布置、围绕有价值的问题展开互动，四项说法均恰当。","hint":"合作学习四要素：任务、要求、环境、真问题。","tags":["学习方式","合作学习"],"category":"教学技能与实践"},{"id":"L2-M09","source":"local","sourceLabel":"（本地：第2卷第29题）","vol":2,"no":29,"section":"多选","sectionNo":9,"type":"multi","score":4,"stem":"终身教育是贯穿于人的一生的教育，终身教育的特点包括什么?（  ）","options":["终身性","全民性","广泛性","灵活性和实用性"],"answer":["A","B","C","D"],"analysis":"终身教育的特点包括终身性（贯穿一生）、全民性（面向所有人）、广泛性（内容形式多样）、灵活性和实用性，四项均正确。","hint":"终身教育四特点：终身、全民、广泛、灵活实用。","tags":["教育思潮","终身教育"],"category":"教育学原理"},{"id":"L2-M10","source":"local","sourceLabel":"（本地：第2卷第30题）","vol":2,"no":30,"section":"多选","sectionNo":10,"type":"multi","score":4,"stem":"探究性学习的优势主要表现在（  ）","options":["可以增强学生与他人一起解决现实生活中问题的意愿","可以使学生更为深入地理解所获得的知识和技能，增强思维能力、操作能力","可以学以致用","能够拓展学生的学科视野，便于学生掌握完全的知识"],"answer":["A","B","C","D"],"analysis":"探究性学习的优势：增强学生协作解决现实问题的意愿、深化对知识技能的理解并提升思维操作能力、促进学以致用、拓展学科视野，四项均属其优势。","hint":"探究的优势在于“深入理解+学以致用+协作”。","tags":["学习方式","探究性学习"],"category":"教学技能与实践"},{"id":"L3-S01","source":"local","sourceLabel":"（本地：第3卷第1题）","vol":3,"no":1,"section":"单选","sectionNo":1,"type":"single","score":3,"stem":"下列关于素质教育的表述中，不正确的是（  ）。","options":["素质教育更要重视德育","素质教育主要适用于基础教育","素质教育应遵循教育规律","素质教育不要求学生平均发展"],"answer":["B"],"analysis":"素质教育是贯穿各级各类教育的指导思想，并非只适用于基础教育，故B表述不正确。素质教育要重视德育、要遵循教育规律、不要求学生平均发展（而是全面发展与个性发展相统一），A、C、D均正确。","hint":"题干问“不正确”，把素质教育限定在某一学段的说法即为错。","tags":["素质教育"],"category":"教育学原理"},{"id":"L3-S02","source":"local","sourceLabel":"（本地：第3卷第2题）","vol":3,"no":2,"section":"单选","sectionNo":2,"type":"single","score":3,"stem":"为满足学生的个性化学习需求，一所中学开发了一组研学旅行项目，安排本校地理老师作为研学导师全程指导学生完成相关的研学任务。该做法体现的教育观是（  ）。","options":["关注学生的差异性","发挥学生的能动性","重视学生的操作性","关注育人的实践性"],"answer":["D"],"analysis":"研学旅行让学生在实践中完成真实任务，体现育人的实践性（素质教育强调知行合一）。差异性强调因人而异，能动性强调主动参与，操作性强调动手技能，都不是最贴切的概括。","hint":"研学旅行的核心是“在实践中育人”。","tags":["素质教育","教育观"],"category":"教育学原理"},{"id":"L3-S03","source":"local","sourceLabel":"（本地：第3卷第3题）","vol":3,"no":3,"section":"单选","sectionNo":3,"type":"single","score":3,"stem":"为了发散学生们的思维，王老师一改传统教学方式，将一节信息课改成探究课，通过设置开放题的形式引导学生自己总结规律。同事郝老师却说:“你这样不仅浪费时间，而且会降低教学效率。”对此，下列说法正确的是（  ）。","options":["郝老师的说法合理，有利于提高学生学习成绩","郝老师的说法欠妥，不利于维持课堂教学秩序","王老师的做法得当，有利于培养学生创新意识","王老师的做法欠妥，不利于保证正常教学进度"],"answer":["C"],"analysis":"新课改倡导探究学习、培养创新精神，王老师以开放题引导学生自主总结规律的做法得当。郝老师以“效率”否定探究，属应试取向，A、D错误；B的“课堂秩序”与题意无关。","hint":"课改鼓励探究与自主创新，反对唯效率论。","tags":["新课改","教学观","素质教育"],"category":"教育学原理"},{"id":"L3-S04","source":"local","sourceLabel":"（本地：第3卷第4题）","vol":3,"no":4,"section":"单选","sectionNo":4,"type":"single","score":3,"stem":"小方热情活泼，善于组织，热爱表演，于是张老师在每年学校情景剧大赛中总让小方担任主角。张老师的做法违背的素质教育内涵是（  ）。","options":["促进学生全面发展","面向全体学生","促进学生个性发展","培养创新精神"],"answer":["B"],"analysis":"素质教育要求面向全体学生，张老师年年只让小方当主角，把机会集中在少数学生身上，违背了面向全体的要求。全面发展、个性发展、创新精神都不是该做法主要违背的内涵。","hint":"机会只给少数人=违背“面向全体学生”。","tags":["素质教育","面向全体"],"category":"教育学原理"},{"id":"L3-S05","source":"local","sourceLabel":"（本地：第3卷第5题）","vol":3,"no":5,"section":"单选","sectionNo":5,"type":"single","score":3,"stem":"刘老师在课余时间经常去学生家里进行家访，让家长更好地了解学生的在校学习情况，并且也会向家长询问学生的性格和兴趣爱好，以根据学生的性格和兴趣爱好因材施教。这体现了刘老师注重学生个体身心发展的（  ）。","options":["顺序性","阶段性","不平衡性","个体差异性"],"answer":["D"],"analysis":"家访了解性格与兴趣爱好并据此因材施教，体现对学生个体差异性的关注。顺序性强调发展先后次序，阶段性强调年龄特征，不平衡性强调发展速度不均。","hint":"因人而异、因材施教=个体差异性。","tags":["身心发展规律","个别差异性"],"category":"教育学原理"},{"id":"L3-S06","source":"local","sourceLabel":"（本地：第3卷第6题）","vol":3,"no":6,"section":"单选","sectionNo":6,"type":"single","score":3,"stem":"“人非圣贤，孰能无过”，这句话可以应用到教学中，教师在教学中应该用长远的眼光来看待学生，不应仅仅看到学生眼前的过错。这体现的是教师要看到学生是（  ）。","options":["完整的人","发展的人","具有自身的独特性","具有独立意义的人"],"answer":["B"],"analysis":"用长远眼光看待学生、不只盯眼前过错，体现“学生是发展的人”这一学生观。完整的人强调身心多方面，独特性强调差异，独立意义强调不以教师意志为转移。","hint":"“长远眼光”对应学生是发展中的人。","tags":["学生观","发展的学生观"],"category":"教育学原理"},{"id":"L3-S07","source":"local","sourceLabel":"（本地：第3卷第7题）","vol":3,"no":7,"section":"单选","sectionNo":7,"type":"single","score":3,"stem":"安徽省某中学音乐老师在教授《天上掉下个林妹妹》这一课时，不仅向同学们介绍了越剧的相关知识，还根据省份特点引入黄梅戏的知识让学生了解和学习。这表明该音乐老师具有（  ）。","options":["课堂秩序管理能力","教育教学研究能力","课程资源开发能力","教学组织实施能力"],"answer":["C"],"analysis":"结合地方特色引入黄梅戏等资源，属于教师开发与利用课程资源的能力。课堂秩序管理、教学组织实施强调过程控制，教育教学研究强调课题与反思，均不贴切。","hint":"把地方文化资源引入课堂=课程资源开发。","tags":["教师能力","课程资源开发"],"category":"教学技能与实践"},{"id":"L3-S08","source":"local","sourceLabel":"（本地：第3卷第8题）","vol":3,"no":8,"section":"单选","sectionNo":8,"type":"single","score":3,"stem":"下列选项中不违背教师职业道德规范的做法是（  ）。","options":["教师节接受学生自绘贺卡","出于关心对学生严厉责骂","规定家长买大量辅导资料","家有喜事时接受家长贺礼"],"answer":["A"],"analysis":"教师节接受学生亲手绘制的贺卡属情感表达，不违背师德；严厉责骂违背关爱学生，规定家长买资料、接受家长贺礼均违背为人师表与廉洁从教要求。","hint":"廉价、情感性的自制小礼物可接受；收受财物礼金不可。","tags":["教师职业道德","为人师表"],"category":"教师职业道德"},{"id":"L3-S09","source":"local","sourceLabel":"（本地：第3卷第9题）","vol":3,"no":9,"section":"单选","sectionNo":9,"type":"single","score":3,"stem":"疫情期间，某民办学校王老师没有报备批准就自行前往疫情严重的国家旅游，造成严重后果。学校决定解除王老师的聘任合同。依据《中小学教师违反职业道德行为处理办法》，下列说法不正确的是（  ）。","options":["学校在处理决定前应当听取王老师的申辩","学校在处理决定前应当听取家长委员会的意见","学校在处理决定前应当报请主管教育部门批准","学校在处理决定前应当准许王老师举行听证的请求"],"answer":["C"],"analysis":"依《中小学教师违反职业道德行为处理办法》，处理前应听取申辩、可听取家长委员会意见、符合听证条件的应准许听证；解除聘任合同无需事先报请主管部门批准，故C不正确。","hint":"处理办法强调程序公正（申辩、听证），不要求事前审批。","tags":["教育法律法规","教师违反职业道德处理办法"],"category":"教育法律法规"},{"id":"L3-S10","source":"local","sourceLabel":"（本地：第3卷第10题）","vol":3,"no":10,"section":"单选","sectionNo":10,"type":"single","score":3,"stem":"英语老师孙老师刚从某师范学校毕业，工作上兢兢业业。但她非常追求时尚，经常穿一些比较另类的衣服，佩戴一些夸张的首饰。这主要违背了教师职业道德规范中的（  ）的要求。","options":["爱岗敬业","为人师表","关爱学生","教书育人"],"answer":["B"],"analysis":"教师衣着打扮、言行举止要得体，属为人师表的要求。爱岗敬业强调履职尽责，关爱学生强调尊重爱护，教书育人强调育人方式，均与着装不当无直接对应。","hint":"衣着举止得体属于“为人师表”。","tags":["教师职业道德","为人师表"],"category":"教师职业道德"},{"id":"L3-S11","source":"local","sourceLabel":"（本地：第3卷第11题）","vol":3,"no":11,"section":"单选","sectionNo":11,"type":"single","score":3,"stem":"古希腊斯巴达教育的目的是培养（  ）。","options":["演说家","智者","军人和武士","全面和谐发展的人"],"answer":["C"],"analysis":"斯巴达教育以军事体育为主，培养军人和武士；雅典教育追求身心和谐发展，培养多方面发展的人；演说家是古罗马教育的目标。","hint":"斯巴达=军事；雅典=和谐发展。","tags":["教育史","古代教育"],"category":"教育学原理"},{"id":"L3-S12","source":"local","sourceLabel":"（本地：第3卷第12题）","vol":3,"no":12,"section":"单选","sectionNo":12,"type":"single","score":3,"stem":"美国学者孟禄根据原始社会没有学校、没有教师、没有教材的事实，断言教育起源于儿童对成人无意识的模仿。这种观点被称为（  ）。","options":["生物起源论","交往起源论","心理起源论","劳动起源论"],"answer":["C"],"analysis":"孟禄提出教育起源于儿童对成人无意识的模仿，即心理起源论。生物起源论以利托尔诺、沛西能为代表，劳动起源论是马克思主义的观点，交往起源论不是主流提法。","hint":"记人物：孟禄—心理起源（无意识模仿）。","tags":["教育起源","心理起源论"],"category":"教育学原理"},{"id":"L3-S13","source":"local","sourceLabel":"（本地：第3卷第13题）","vol":3,"no":13,"section":"单选","sectionNo":13,"type":"single","score":3,"stem":"我国第一位系统传播马克思主义教育理论，并出版《新教育大纲》的教育理论家是（  ）。","options":["杨贤江","陶行知","黄炎培","李大钊"],"answer":["A"],"analysis":"杨贤江的《新教育大纲》是我国第一部系统传播马克思主义教育理论的著作。陶行知倡导生活教育，黄炎培倡导职业教育，李大钊是马克思主义传播者但非教育理论专著作者。","hint":"杨贤江《新教育大纲》=中国马克思主义教育学第一书。","tags":["教育史","杨贤江"],"category":"教育学原理"},{"id":"L3-S14","source":"local","sourceLabel":"（本地：第3卷第14题）","vol":3,"no":14,"section":"单选","sectionNo":14,"type":"single","score":3,"stem":"中华人民共和国成立初期，我国师范院校教育学课程普遍采用的教材是（  ）。","options":["夸美纽斯的《大教学论》","赫尔巴特的《普通教育学》","凯洛夫的《教育学》","马卡连柯的《论共产主义教育》"],"answer":["C"],"analysis":"新中国成立初期教育全面学习苏联，师范院校普遍采用凯洛夫主编的《教育学》。夸美纽斯、赫尔巴特、马卡连柯的著作都不是当时的通用教材。","hint":"抓住“新中国成立初期”这一时间限定。","tags":["教育史","教育学教材","凯洛夫"],"category":"教育学原理"},{"id":"L3-S15","source":"local","sourceLabel":"（本地：第3卷第15题）","vol":3,"no":15,"section":"单选","sectionNo":15,"type":"single","score":3,"stem":"对儿童、青少年的成长发展起主导作用的因素是（  ）。","options":["遗传素质","环境","教育","个体的主观能动性"],"answer":["C"],"analysis":"在影响人发展的诸因素中，教育（尤其是学校教育）起主导作用；遗传是物质前提，环境提供多种可能，个体主观能动性是决定性因素与内在动力。","hint":"起主导作用的是教育；主观能动性是决定性因素。","tags":["影响人发展的因素","教育主导作用"],"category":"教育学原理"},{"id":"L3-S16","source":"local","sourceLabel":"（本地：第3卷第16题）","vol":3,"no":16,"section":"单选","sectionNo":16,"type":"single","score":3,"stem":"卢梭从自然教育观出发，提出培养自然人的教育目的，这种教育目的观属于（  ）。","options":["社会本位论","宗教本位论","自然本位论","个人本位论"],"answer":["D"],"analysis":"卢梭主张按儿童天性培养“自然人”，强调个体发展与天性，属个人本位论。社会本位论强调为社会培养公民，宗教本位论以宗教目的为中心，自然本位论不是规范提法。","hint":"培养“自然人”、顺应天性=个人本位论。","tags":["教育目的","个人本位论"],"category":"教育学原理"},{"id":"L3-S17","source":"local","sourceLabel":"（本地：第3卷第17题）","vol":3,"no":17,"section":"单选","sectionNo":17,"type":"single","score":3,"stem":"在课程和教学理论的发展过程中，曾出现形式教育论和实质教育论之争。这是对哪一关系的争论?（  ）","options":["直接经验与间接经验","知识与能力","分科与综合","知识与思想"],"answer":["B"],"analysis":"形式教育论主张训练能力（官能），实质教育论主张传授实用知识，二者之争的实质是知识与能力的关系。直接经验与间接经验、分科与综合、知识与思想都是另外几组关系。","hint":"形式=能力，实质=知识，二者之争即“知识与能力”。","tags":["教学理论","形式教育论"],"category":"教育学原理"},{"id":"L3-S18","source":"local","sourceLabel":"（本地：第3卷第18题）","vol":3,"no":18,"section":"单选","sectionNo":18,"type":"single","score":3,"stem":"“再生产科学所必要的劳动时间，同最初生产科学所需要的劳动时间是无法相比的，例如学生在一小时内就能学会二项式定理。”这表明教学活动具有（  ）。","options":["引导性","直接性","简捷性","实践性"],"answer":["C"],"analysis":"学生一小时就能学会二项式定理，说明教学能走人类认识的捷径、高效传递知识，体现简捷性。引导性强调教师引导，直接性与教学以间接经验为主相悖，实践性强调动手。","hint":"短时间内掌握长期积累的知识=简捷性。","tags":["教学过程","简捷性"],"category":"教育学原理"},{"id":"L3-S19","source":"local","sourceLabel":"（本地：第3卷第19题）","vol":3,"no":19,"section":"单选","sectionNo":19,"type":"single","score":3,"stem":"于老师在讲台上把一张纸揉成团，把另一张纸烧成灰，由此让学生来理解物质的物理变化与化学变化的区别。于老师采用的教学方法是（  ）。","options":["练习法","实验法","参观法","演示法"],"answer":["D"],"analysis":"教师在讲台上演示揉纸与烧纸，学生观察并理解物理变化与化学变化的区别，属演示法。练习法是学生反复操练，实验法是学生亲自动手，参观法是到实地观察。","hint":"老师做、学生看=演示法；学生自己做=实验法。","tags":["教学方法","演示法"],"category":"教育学原理"},{"id":"L3-S20","source":"local","sourceLabel":"（本地：第3卷第20题）","vol":3,"no":20,"section":"单选","sectionNo":20,"type":"single","score":3,"stem":"小明看见天上的浮云，脑中出现“骏马”“恐龙”等动物形象。这种现象属于（  ）。","options":["有意想象","无意想象","再造想象","创造想象"],"answer":["B"],"analysis":"看见浮云随机联想到动物形象，无预定目的、不受意志支配，属无意想象。有意想象有预定目的，再造想象依据语言描述，创造想象独立创造新形象。","hint":"由偶然刺激引发、无目的的想象=无意想象。","tags":["想象","无意想象"],"category":"教育心理"},{"id":"L3-M01","source":"local","sourceLabel":"（本地：第3卷第21题）","vol":3,"no":21,"section":"多选","sectionNo":1,"type":"multi","score":4,"stem":"记忆是在头脑中积累和保存个体经验的心理过程，根据记忆的内容和经验的对象，记忆可以分为（  ）。","options":["形象记忆","逻辑记忆","瞬时记忆","动作记忆"],"answer":["A","B","D"],"analysis":"按记忆内容和经验对象可分为形象记忆、逻辑记忆、情绪记忆、动作记忆。C瞬时记忆是按保持时间长短划分的类别，与题干分类标准不符，故排除。","hint":"题干限定“按内容和经验对象”，要排除按时间分类的选项。","tags":["记忆","记忆分类"],"category":"教育心理"},{"id":"L3-M02","source":"local","sourceLabel":"（本地：第3卷第22题）","vol":3,"no":22,"section":"多选","sectionNo":2,"type":"multi","score":4,"stem":"关于马斯洛的需要层次理论，以下说法正确的是（  ）。","options":["生理需要是人类维持自身生存需要的最基本的需求","最高层次的需要是自我实现的需要","在同一时期可能会有多种需要，但每个时期总有一种需要起决定作用","高层次的需求发展后，次低层次的需求会消失"],"answer":["A","B","C"],"analysis":"马斯洛认为生理需要是最基本需要，最高层次是自我实现需要，同一时期可能并存多种需要但有一种占优势。D错误：低层次需要不会消失，只是不再占主导地位。","hint":"低层次需要不会消失，只是退居次要地位。","tags":["马斯洛","需要层次理论"],"category":"教育心理"},{"id":"L3-M03","source":"local","sourceLabel":"（本地：第3卷第23题）","vol":3,"no":23,"section":"多选","sectionNo":3,"type":"multi","score":4,"stem":"消极的课堂气氛体现为哪些现象？（  ）","options":["学生无精打采","采取应付态度","很少主动发言","师生关系融洽"],"answer":["A","B","C"],"analysis":"消极课堂气氛表现为学生无精打采、应付了事、很少主动发言。D“师生关系融洽”是积极课堂气氛的表现，与题干“消极”不符，故排除。","hint":"排除正面描述，只留消极表现。","tags":["课堂管理","课堂气氛"],"category":"教学技能与实践"},{"id":"L3-M04","source":"local","sourceLabel":"（本地：第3卷第24题）","vol":3,"no":24,"section":"多选","sectionNo":4,"type":"multi","score":4,"stem":"福勒和布朗根据教师的需要和不同时期所关注的焦点问题，把教师的成长划分为哪几个阶段？（  ）","options":["关注生存阶段","关注结果的阶段","关注情境阶段","关注学生的阶段"],"answer":["A","C","D"],"analysis":"福勒和布朗把教师成长分为关注生存、关注情境、关注学生三个阶段。B“关注结果的阶段”不是该理论的阶段，故排除。","hint":"三阶段口诀：生存→情境→学生。","tags":["教师专业发展","福勒和布朗"],"category":"教学技能与实践"},{"id":"L3-M05","source":"local","sourceLabel":"（本地：第3卷第25题）","vol":3,"no":25,"section":"多选","sectionNo":5,"type":"multi","score":4,"stem":"影响问题解决的主要因素有哪些？（  ）","options":["对已有知识经验迁移的能力","酝酿效应","定势与功能固着","问题呈现的方式"],"answer":["A","B","C","D"],"analysis":"影响问题解决的因素包括已有知识经验的迁移能力、酝酿效应、定势与功能固着、问题呈现的方式等，四项均属主要因素。","hint":"问题解决受“知识迁移、心理定势、表征方式”共同影响。","tags":["问题解决"],"category":"教育心理"},{"id":"L3-M06","source":"local","sourceLabel":"（本地：第3卷第26题）","vol":3,"no":26,"section":"多选","sectionNo":6,"type":"multi","score":4,"stem":"关于学生学习的特点，以下哪些说法是正确的？（  ）","options":["学生的学习是以掌握直接知识经验为主的","学生的学习是在教师有目的、有计划、有组织地指导下进行的","学生学习的主要任务是掌握系统的科学知识、技能，形成世界观、道德品质","学生的学习具有一定程度的被动性"],"answer":["B","C","D"],"analysis":"学生学习以掌握间接经验为主，故A错误；学生学习是在教师有目的、有计划、有组织指导下进行的，主要任务是掌握系统知识技能并形成世界观与道德品质，也具有一定程度的被动性。","hint":"学生学习以间接经验为主，A说“直接”故错。","tags":["学习理论","学生学习特点"],"category":"教育心理"},{"id":"L3-M07","source":"local","sourceLabel":"（本地：第3卷第27题）","vol":3,"no":27,"section":"多选","sectionNo":7,"type":"multi","score":4,"stem":"根据“以人为本”的学生观，下列哪些说法是正确的？（  ）","options":["学生的身心发展是有规律的","每个学生都有自身的独特性","学生是以老师的意志为转移的客观存在","学生是处于发展过程中的人"],"answer":["A","B","D"],"analysis":"“以人为本”的学生观认为：学生身心发展有规律、每个学生都有独特性、学生是处于发展过程中的人。C把学生当作教师意志的被动接受者，违背学生观，故排除。","hint":"学生是独立意义的人，不是被动接受者。","tags":["学生观","以人为本"],"category":"教育学原理"},{"id":"L3-M08","source":"local","sourceLabel":"（本地：第3卷第28题）","vol":3,"no":28,"section":"多选","sectionNo":8,"type":"multi","score":4,"stem":"根据皮亚杰的认知发展理论，具体运算阶段具备哪些思维特点？（  ）","options":["“泛灵性”，认为外界的一切事物都是有生命的","拥有守恒的概念","思维能够前推也能后退，具备可逆性","能够进行简单的抽象思维，但需要具体事物的支持"],"answer":["B","C","D"],"analysis":"具体运算阶段的特点：获得守恒概念、思维可逆、能进行需具体事物支持的简单抽象思维。A“泛灵性”是前运算阶段的特点，故排除。","hint":"泛灵论属于前运算阶段，不在具体运算阶段。","tags":["皮亚杰","具体运算"],"category":"教育心理"},{"id":"L3-M09","source":"local","sourceLabel":"（本地：第3卷第29题）","vol":3,"no":29,"section":"多选","sectionNo":9,"type":"multi","score":4,"stem":"教师成长和发展的基本途径有哪些？（  ）","options":["开展微格教学","提高课后作业的数量","反思自己的教学经验","观摩和分析优秀教师的教学活动"],"answer":["A","C","D"],"analysis":"教师成长与发展的基本途径包括开展微格教学、反思教学经验、观摩和分析优秀教师的教学活动。B提高作业数量与教师成长无直接关系，故排除。","hint":"成长三途径：微格教学、反思、观摩优秀教师。","tags":["教师专业发展","成长途径"],"category":"教学技能与实践"},{"id":"L3-M10","source":"local","sourceLabel":"（本地：第3卷第30题）","vol":3,"no":30,"section":"多选","sectionNo":10,"type":"multi","score":4,"stem":"学习迁移指一种学习对另一种学习的影响，以下哪些教学行为可以促进学习迁移？（  ）","options":["精选教材","合理编排教学内容","教授学习策略，提高迁移意识性","合理安排教学程序"],"answer":["A","B","C","D"],"analysis":"促进学习迁移的教学策略包括精选教材、合理编排教学内容、教授学习策略并提高迁移意识、合理安排教学程序，四项均能有效促进迁移。","hint":"促进迁移四招：精选教材、合理编排、教授策略、安排程序。","tags":["学习迁移"],"category":"教育心理"},{"id":"L4-S01","source":"local","sourceLabel":"（本地：第4卷第1题）","vol":4,"no":1,"section":"单选","sectionNo":1,"type":"single","score":3,"stem":"1762年，法国启蒙思想家卢梭发表的系统阐述其自然主义教育思想的著作是（  ）。","options":["《理想国》","巨人传》","《太阳城》","《爱弥儿》"],"answer":["D"],"analysis":"1762年卢梭发表《爱弥儿》，系统阐述自然主义教育思想，主张顺应儿童天性进行教育。《理想国》是柏拉图的著作，《巨人传》是拉伯雷的小说，《太阳城》是康帕内拉的空想社会主义著作。","hint":"1762年+自然主义教育=卢梭的《爱弥儿》。","tags":["教育史","卢梭","《爱弥儿》"],"category":"教育学原理"},{"id":"L4-S02","source":"local","sourceLabel":"（本地：第4卷第2题）","vol":4,"no":2,"section":"单选","sectionNo":2,"type":"single","score":3,"stem":"“今天的教育就是明天的经济，教育已经成为经济发展的杠杆”。这说明教育具有（  ）。","options":["科学性","阶段性","生产性","独立性"],"answer":["C"],"analysis":"“今天的教育就是明天的经济”说明教育通过培养劳动力、提高生产率促进经济发展，具有生产性。科学性、阶段性、独立性都不是该表述强调的属性。","hint":"把教育与经济回报联系起来，找“生产性”。","tags":["教育功能","生产性"],"category":"教育学原理"},{"id":"L4-S03","source":"local","sourceLabel":"（本地：第4卷第3题）","vol":4,"no":3,"section":"单选","sectionNo":3,"type":"single","score":3,"stem":"于老师在讲台上把张一纸揉成团，把另一张纸烧成灰，由此让学生来理解物质的物理变化与化学变化的区别。于老师采用的教学方法是（  ）。","options":["练习法","演示法","实验法","参观法"],"answer":["B"],"analysis":"教师在讲台上做揉纸、烧纸的示范，学生观察后理解物理变化与化学变化的区别，属演示法。练习法是学生反复操练，实验法是学生自己动手操作，参观法是组织实地观察。","hint":"老师做给学生看=演示法；学生自己动手做=实验法。","tags":["教学方法","演示法"],"category":"教育学原理"},{"id":"L4-S04","source":"local","sourceLabel":"（本地：第4卷第4题）","vol":4,"no":4,"section":"单选","sectionNo":4,"type":"single","score":3,"stem":"教师:“面粉可以做什么？”学生甲:“可以做面包、蛋糕、馒头、花卷、油条、面条。”学生乙:“可以做馒头、调磁针水、捏面人。”上述对话说明学生乙比学生甲的思维更具有（  ）。","options":["精细性","流畅性","变通性","反思性"],"answer":["C"],"analysis":"变通性指思维能突破类别限制、灵活转换方向。学生乙的答案跨越食品、物理实验、手工造型等不同类别，体现变通性；甲的多个答案都属食品类，只体现流畅性。","hint":"跨类别、换方向=变通性；同类别数量多=流畅性。","tags":["思维品质","创造性思维","变通性"],"category":"教育心理"},{"id":"L4-S05","source":"local","sourceLabel":"（本地：第4卷第5题）","vol":4,"no":5,"section":"单选","sectionNo":5,"type":"single","score":3,"stem":"“学生过度兴奋、各行其是、随便插嘴、故意捣乱”等词语，描述的是哪类课堂氛围表现？（  ）","options":["积极型","消极型","对抗型","顺从型"],"answer":["C"],"analysis":"“过度兴奋、各行其是、随便插嘴、故意捣乱”是与教师对抗、失控的课堂表现，属对抗型课堂气氛。消极型表现为无精打采、被动应付，积极型是热烈而有序。","hint":"故意捣乱、与教师对立=对抗型课堂气氛。","tags":["课堂管理","课堂气氛"],"category":"教学技能与实践"},{"id":"L4-S06","source":"local","sourceLabel":"（本地：第4卷第6题）","vol":4,"no":6,"section":"单选","sectionNo":6,"type":"single","score":3,"stem":"孟子说:“天将降大任于斯人也，必先苦其心志，劳其筋骨，饿其体肤，空乏其身，行拂乱其所为。所以动心忍性，增益其所不能。”这段话体现的德育方法是（  ）。","options":["实际锻炼法","品德评价法","情感陶冶法","榜样示范法"],"answer":["A"],"analysis":"“苦其心志、劳其筋骨”强调在实际磨炼中经受锻炼、培养意志品质，属实际锻炼法。品德评价法依靠表扬批评等评价手段，情感陶冶法依靠潜移默化的感染，榜样示范法依靠榜样人物影响。","hint":"在艰苦实践中磨炼意志=实际锻炼法。","tags":["德育方法","实际锻炼法"],"category":"教育学原理"},{"id":"L4-S07","source":"local","sourceLabel":"（本地：第4卷第7题）","vol":4,"no":7,"section":"单选","sectionNo":7,"type":"single","score":3,"stem":"阳慧在解决问题的过程中，常以老师、同学的建议作为参照做出决策。她的这种认知风格属于（  ）。","options":["场依存型","场独立型","继时型","同时型"],"answer":["A"],"analysis":"场依存型认知风格者以外部线索为参照，易受他人意见与环境暗示影响。场独立型依靠内部参照独立判断；继时型与同时型按信息加工方式划分，与参照依据无关。","hint":"以老师同学的看法为参照=外部参照=场依存型。","tags":["认知风格","场依存"],"category":"教育心理"},{"id":"L4-S08","source":"local","sourceLabel":"（本地：第4卷第8题）","vol":4,"no":8,"section":"单选","sectionNo":8,"type":"single","score":3,"stem":"欣怡能用规则来约束自己的行为，认为规则是绝对的，不可变更的，并表现出对规则的服从。根据皮亚杰的道德认知发展理论，欣怡的道德发展水平处于（  ）。","options":["自我中心阶段","权威阶段","可逆阶段","公正阶段"],"answer":["B"],"analysis":"皮亚杰道德发展理论中，权威阶段（他律）儿童把规则看成绝对、不可变更的，并表现出对权威的服从。自我中心阶段还不理解规则，可逆阶段认为规则可协商，公正阶段考虑公道。","hint":"认为规则绝对不可变=他律=权威阶段。","tags":["皮亚杰","道德发展"],"category":"教育心理"},{"id":"L4-S09","source":"local","sourceLabel":"（本地：第4卷第9题）","vol":4,"no":9,"section":"单选","sectionNo":9,"type":"single","score":3,"stem":"建华在听课过程中会不由自主地玩手机或做小动作。这种现象属于（  ）。","options":["注意集中","注意分散","注意分配","注意转移"],"answer":["B"],"analysis":"上课时不由自主地玩手机、做小动作，是被无关刺激吸引而使注意离开当前任务，属注意分散（分心）。注意分配是同时指向多个对象，注意转移是主动地把注意转向新对象。","hint":"被无关事物吸引而走神=注意分散。","tags":["注意","注意分散"],"category":"教育心理"},{"id":"L4-S10","source":"local","sourceLabel":"（本地：第4卷第10题）","vol":4,"no":10,"section":"单选","sectionNo":10,"type":"single","score":3,"stem":"高三学生志强认为做事应该达到尽善尽美，因此他对自己要求很高，常常因偶尔的考试成绩不理想而情绪低落，心理辅导教师通过纠正其不合理信念来调整他的情绪。该教师采用的心理辅导方法是（  ）。","options":["理性情绪疗法","系统脱敏法","阳性强化法","来访者中心疗法"],"answer":["A"],"analysis":"心理辅导教师通过纠正“必须尽善尽美”等不合理信念来调节情绪，属艾利斯的理性情绪疗法。系统脱敏法用于消除焦虑反应，阳性强化法塑造良好行为，来访者中心疗法强调无条件积极关注。","hint":"看到“纠正不合理信念”就选理性情绪疗法。","tags":["心理辅导","理性情绪疗法"],"category":"教育心理"},{"id":"L4-S11","source":"local","sourceLabel":"（本地：第4卷第11题）","vol":4,"no":11,"section":"单选","sectionNo":11,"type":"single","score":3,"stem":"我国唐代中央官学设有“六学二馆”，其入学条件中明文规定不同级别官员的子孙进入不同的学校。这主要体现了我国封建社会教育制度的哪一特征？（  ）","options":["继承性","等级性","历史性","民族性"],"answer":["B"],"analysis":"按官员品级规定其子孙进入不同学校，体现封建社会教育的等级性。继承性指教育的历史延续，历史性指不同时代教育的差异，民族性指民族之间的差异。","hint":"按身份级别区别对待=等级性。","tags":["教育制度","古代教育特征"],"category":"教育学原理"},{"id":"L4-S12","source":"local","sourceLabel":"（本地：第4卷第12题）","vol":4,"no":12,"section":"单选","sectionNo":12,"type":"single","score":3,"stem":"林菁擅长记忆物理定律、数学公式和化学方程式。这表明他的哪种记忆好？（  ）","options":["形象记忆","情绪记忆","逻辑记忆","动作记忆"],"answer":["C"],"analysis":"记忆定律、公式、化学方程式属于以概念、判断、推理为内容的语词—逻辑记忆。形象记忆以表象为内容，情绪记忆以情感体验为内容，动作记忆以动作技能为内容。","hint":"公式定理类材料=逻辑记忆。","tags":["记忆","记忆分类"],"category":"教育心理"},{"id":"L4-S13","source":"local","sourceLabel":"（本地：第4卷第13题）","vol":4,"no":13,"section":"单选","sectionNo":13,"type":"single","score":3,"stem":"“一把钥匙开一把锁”体现的德育原则是（  ）。","options":["理论联系实际","长善救失","教育影响的一致性","因材施教"],"answer":["D"],"analysis":"“一把钥匙开一把锁”比喻针对不同学生采用不同教育方式，体现因材施教原则。理论联系实际强调学用结合，长善救失强调发扬优点克服缺点，教育影响一致性强调各方面要求一致。","hint":"不同锁配不同钥匙=因人而异=因材施教。","tags":["德育原则","因材施教"],"category":"教育学原理"},{"id":"L4-S14","source":"local","sourceLabel":"（本地：第4卷第14题）","vol":4,"no":14,"section":"单选","sectionNo":14,"type":"single","score":3,"stem":"方华情绪兴奋快而强，容易冲动，常常是爆发式的，并伴随有明显外部表现。她的气质类型属于（  ）。","options":["胆汁质","多血质","粘液质","抑郁质"],"answer":["A"],"analysis":"情绪兴奋快而强、易冲动、爆发式且外部表现明显，是胆汁质的典型特征。多血质活泼灵活，粘液质沉稳迟缓，抑郁质敏感内向。","hint":"急躁冲动、爆发式=胆汁质。","tags":["气质","胆汁质"],"category":"教育心理"},{"id":"L4-S15","source":"local","sourceLabel":"（本地：第4卷第15题）","vol":4,"no":15,"section":"单选","sectionNo":15,"type":"single","score":3,"stem":"张博近期经常失眠，食欲不振，不愿与同学和老师交往，对什么事情都不感兴趣，消极悲观；认为自己一无是处，未来没有希望，他存在的心理问题是（  ）。","options":["强迫症","焦虑症","抑郁症","恐怖症"],"answer":["C"],"analysis":"失眠、食欲不振、交往退缩、兴趣丧失、消极悲观、自我评价过低，是抑郁症的典型表现。强迫症表现为强迫观念或行为，焦虑症以过度担忧为主，恐怖症是对特定对象的强烈恐惧。","hint":"情绪低、兴趣低、自我评价低“三低”=抑郁。","tags":["心理健康","抑郁症"],"category":"教育心理"},{"id":"L4-S16","source":"local","sourceLabel":"（本地：第4卷第16题）","vol":4,"no":16,"section":"单选","sectionNo":16,"type":"single","score":3,"stem":"韩波进入中学后，经常独自思考“我是谁”，未来从事何种职业，在社会上处于什么样的地位等问题。根据埃里克森的人格发展阶段理论，韩涛的人格发展处于（  ）。","options":["主动对内疚阶段","同一性对角色混乱阶段","自我整合对绝望阶段","自主对羞耻和疑虑阶段"],"answer":["B"],"analysis":"中学生反复思考“我是谁”“未来做什么”，是青少年期自我同一性对角色混乱阶段的典型表现。主动对内疚属学前期，自主对羞怯属幼儿期，自我整合对绝望属老年期。","hint":"追问“我是谁”=自我同一性对角色混乱。","tags":["埃里克森","人格发展"],"category":"教育心理"},{"id":"L4-S17","source":"local","sourceLabel":"（本地：第4卷第17题）","vol":4,"no":17,"section":"单选","sectionNo":17,"type":"single","score":3,"stem":"在教学过程中，教师主导作用发挥的主要标志是（  ）。","options":["确保学生的独立地位","维持正常课程秩序","维护教师的中心地位","调动学生的积极性"],"answer":["D"],"analysis":"教师主导作用发挥得好不好，主要看学生学习的积极性、主动性是否被充分调动。确保学生独立地位、维持课堂秩序、维护教师中心地位都不是主导作用的主要标志。","hint":"主导作用体现在“调动学生”上。","tags":["教学过程","教师主导与学生主体"],"category":"教育学原理"},{"id":"L4-S18","source":"local","sourceLabel":"（本地：第4卷第18题）","vol":4,"no":18,"section":"单选","sectionNo":18,"type":"single","score":3,"stem":"为了更好地因材施教，新学期伊始，高一化学课李老师对所教班级学生的学习情况进行了摸底考试，初步了解学生已有的知识基础和有关能力。这种考试属于（  ）。","options":["形成性评价","诊断性评价","总结性评价","相对性评价"],"answer":["B"],"analysis":"新学期伊始为因材施教而进行的摸底考试，目的是了解学生已有基础，属诊断性评价。形成性评价在教学过程中进行，总结性评价在教学结束时作出结论，相对性评价以群体内相对位置为依据。","hint":"教学前摸底了解基础=诊断性评价。","tags":["教学评价","诊断性评价"],"category":"教学技能与实践"},{"id":"L4-S19","source":"local","sourceLabel":"（本地：第4卷第19题）","vol":4,"no":19,"section":"单选","sectionNo":19,"type":"single","score":3,"stem":"教师张某因恶意透支信用卡被人民法院判处有期徒刑一年。根据《中华人民共和国教师法》的规定，下列选项中正确的是（  ）。","options":["张某永远丧失教师资格","学校可依法撤销张某的教师资格","张某两年以后方可重新申请认定教师资格获得教师资格","张某必须再次通过教师资格考试才能获得教师资格"],"answer":["A"],"analysis":"《教师法》规定，受到剥夺政治权利或故意犯罪被判处有期徒刑以上刑罚的，不能取得教师资格；已取得的丧失教师资格且不能重新认定。恶意透支构成信用卡诈骗属故意犯罪并被判刑，故张某丧失资格。B、C、D均与法条不符。","hint":"故意犯罪判有期徒刑以上=丧失教师资格且不得重新取得。","tags":["教育法律法规","教师法"],"category":"教育法律法规"},{"id":"L4-S20","source":"local","sourceLabel":"（本地：第4卷第20题）","vol":4,"no":20,"section":"单选","sectionNo":20,"type":"single","score":3,"stem":"暑假来临，王老师找到主管校长说:“我教了几十年书，虽说已经有了比较丰富的经验，也获得过不少奖励，而且过几年就退休了，但学无止境，我还是希望和几位年轻老师一起外出参加培训。”这表明王老师（  ）。","options":["重视教师道德荣誉","善于核算教育行为利益","关注教师集体利益","注重公平分配教育资源"],"answer":["A"],"analysis":"王老师经验丰富、临近退休仍坚持外出培训，体现终身学习与重视教师职业荣誉。B核算利益、C关注集体利益、D公平分配教育资源都与题干“学无止境”的立意不符。","hint":"老教师主动充电=终身学习、看重职业荣誉。","tags":["教师职业道德","终身学习"],"category":"教师职业道德"},{"id":"L4-M01","source":"local","sourceLabel":"（本地：第4卷第21题）","vol":4,"no":21,"section":"多选","sectionNo":1,"type":"multi","score":4,"stem":"22岁的李某在家待业。根据我国宪法的规定，关于李某的权利义务，下列选项中正确的是（  ）。","options":["无接受义务教育的权利","无需承担纳税义务","有依法服兵役的义务","有科学研究的自由"],"answer":["A","C","D"],"analysis":"义务教育有年龄阶段限制，22岁的李某不再享有接受义务教育的权利，A正确；依法服兵役是公民义务，C正确；科学研究自由是宪法规定的公民自由，D正确。B错误：依法纳税是公民义务，不能说“无需承担”。","hint":"义务教育有年龄限制；纳税是义务而非可免。","tags":["教育法律法规","宪法"],"category":"教育法律法规"},{"id":"L4-M02","source":"local","sourceLabel":"（本地：第4卷第22题）","vol":4,"no":22,"section":"多选","sectionNo":2,"type":"multi","score":4,"stem":"子曰:“学而不思则罔①，思而不学则殆②。”(《论语·为政》)【注释】①罔:迷惑、糊涂。②殆:疑惑、危险。下列对孔子这段话的理解，正确的是（  ）。","options":["在孔子看来，学和思二者不能偏废，主张学与思相结合","孔子指出了学而不思的局限，也道出了思而不学的弊端","光学习不思考会越学越危险，光思考不学习会越来越糊涂","孔子学与思相结合的思想，在今天仍有其值得肯定的价值"],"answer":["A","B","D"],"analysis":"孔子主张学与思不可偏废、二者结合，A、D正确；同时指出学而不思与思而不学各有弊端，B正确。C错误：罔是迷惑糊涂（对应学而不思），殆是疑惑危险（对应思而不学），C把二者说反了。","hint":"注意注释：罔=迷惑糊涂，殆=疑惑危险，C把对应关系说反。","tags":["教育史","孔子","教学方法"],"category":"教育学原理"},{"id":"L4-M03","source":"local","sourceLabel":"（本地：第4卷第23题）","vol":4,"no":23,"section":"多选","sectionNo":3,"type":"multi","score":4,"stem":"“孟母三迁”是我国历史上著名的故事，它说明了环境对人的成长影响很大，关于学校优化育人环境，下列说法恰当的是（  ）。","options":["促进了人的认识的发展","促进了人的气质的发展","促进了人的精神的发展","促进了人的实践的发展"],"answer":["A","C","D"],"analysis":"学校优化育人环境主要促进人的认识发展、精神发展和实践发展。B错误：气质主要受遗传与神经系统类型影响，环境难以直接促进气质的发展。","hint":"气质先天成分大，环境主要影响认识、精神和实践。","tags":["影响人发展的因素","环境"],"category":"教育学原理"},{"id":"L4-M04","source":"local","sourceLabel":"（本地：第4卷第24题）","vol":4,"no":24,"section":"多选","sectionNo":4,"type":"multi","score":4,"stem":"下列教学用语中，有利于促进学生学习的是（  ）。","options":["“你读得很响亮，若再有感情一点就好了。你再试试。”","“刚才这位同学概括得不准确，还是我来吧。”","“这位同学的发言并没有重复前面同学说过的话，有自己的观点，非常好。”","“请大家想一想，刚才这两位同学报告的结论，有何不同？”"],"answer":["A","C","D"],"analysis":"A先肯定再提出改进建议、C肯定学生有自己的观点、D引导全体学生比较思考，都能促进学习。B直接否定学生并由教师包办，会打击学生积极性，不利于学习，故排除。","hint":"排除否定学生、由教师包办的教学用语。","tags":["教学技能","教学用语"],"category":"教学技能与实践"},{"id":"L4-M05","source":"local","sourceLabel":"（本地：第4卷第25题）","vol":4,"no":25,"section":"多选","sectionNo":5,"type":"multi","score":4,"stem":"教师在学生自主学习中的作用主要表现在（  ）。","options":["鼓舞和激励","指引方向","提供反馈","释疑解疑"],"answer":["A","B","C","D"],"analysis":"自主学习不等于教师退出，教师应发挥鼓舞激励、指引方向、提供反馈、释疑解疑的作用，四项均属教师应尽职责。","hint":"自主学习里教师是“支持者”而非“旁观者”。","tags":["学习方式","自主学习"],"category":"教学技能与实践"},{"id":"L4-M06","source":"local","sourceLabel":"（本地：第4卷第26题）","vol":4,"no":26,"section":"多选","sectionNo":6,"type":"multi","score":4,"stem":"某校实施了“师徒制”，经验丰富的吴老师对新入职的蒋老师进行帮助时，以下做法不恰当的是（  ）。","options":["保守原则，等蒋老师请教时才进行指导","主动指导，和蒋老师商讨并确定教学方案","推门听课，发现不妥之处，及时在课堂上纠正","充分信任，让蒋老师独自探索并积累教学经验"],"answer":["A","C","D"],"analysis":"题干问“不恰当”的做法：A保守等待、缺乏主动性，C推门听课当场纠正会伤害新教师自尊，D完全放手让新教师独自探索都是指导缺位或方式不当。B主动指导并共同商讨方案是恰当做法，故排除。","hint":"先确认哪项是“恰当”的并排除，剩下的都是不恰当。","tags":["教师专业发展","师徒制"],"category":"教学技能与实践"},{"id":"L4-M07","source":"local","sourceLabel":"（本地：第4卷第27题）","vol":4,"no":27,"section":"多选","sectionNo":7,"type":"multi","score":4,"stem":"牛老师在班级管理中采取了一系列措施，其中不正确的是（  ）。","options":["鼓励学习能力强的学生主动帮助学困生","编排座位时让学生按成绩排名自己选择","有学生丢失东西时马上检查全班学生的书包","私下告知无记名投票选的“最差生”并提出要求"],"answer":["B","C","D"],"analysis":"题干问“不正确”的做法：B按成绩排名选座位带有歧视性，C搜查全班书包侵犯学生隐私权，D公布无记名投票的“最差生”伤害学生人格尊严，均不正确。A鼓励优生帮助学困生是正确的，故排除。","hint":"歧视性、侵权性、伤害自尊的做法都不正确。","tags":["班级管理","班主任工作"],"category":"教学技能与实践"},{"id":"L4-M08","source":"local","sourceLabel":"（本地：第4卷第28题）","vol":4,"no":28,"section":"多选","sectionNo":8,"type":"multi","score":4,"stem":"下列关于教师与学生之间法律关系的说法，正确的是（  ）。","options":["教育与被教育的关系","管理与被管理的关系","保护与被保护的关系","控制与被控制的关系"],"answer":["A","B","C"],"analysis":"教师与学生之间的法律关系包括教育与被教育、管理与被管理、保护与被保护的关系。D“控制与被控制”不是法律规范的表述，师生法律地位平等，故排除。","hint":"排除“控制”这类不平等、不规范的表述。","tags":["教育法律法规","师生关系"],"category":"教育法律法规"},{"id":"L4-M09","source":"local","sourceLabel":"（本地：第4卷第29题）","vol":4,"no":29,"section":"多选","sectionNo":9,"type":"multi","score":4,"stem":"探究性学习的优势主要表现在（  ）。","options":["可以增强学生与他人一起解决现实生活中问题的意愿","可以使学生更为深入地理解所获得的知识和技能，增强思维能力、操作能力","可以学以致用","能够拓展学生的学科视野，便于学生掌握完全的知识"],"answer":["A","B","C","D"],"analysis":"探究性学习的优势包括增强协作解决现实问题的意愿、深化对知识技能的理解并提升思维与操作能力、促进学以致用、拓展学科视野，四项均属其优势。","hint":"探究的优势在于“深入理解+学以致用+协作”。","tags":["学习方式","探究性学习"],"category":"教学技能与实践"},{"id":"L4-M10","source":"local","sourceLabel":"（本地：第4卷第30题）","vol":4,"no":30,"section":"多选","sectionNo":10,"type":"multi","score":4,"stem":"下列关于素质教育的表述中，正确的是（  ）。","options":["素质教育适合家庭条件比较好的学生","素质教育主要适用于基础教育","素质教育应遵循教育规律","素质教育不要求学生平均发展"],"answer":["C","D"],"analysis":"素质教育面向全体学生、贯穿各级各类教育、遵循教育规律、不要求学生平均发展而是全面发展与个性发展统一，故C、D正确。A把素质教育限定于家庭条件好的学生、B限定于基础教育，均错误。","hint":"只保留符合“面向全体、全面发展与个性发展统一”的表述。","tags":["素质教育"],"category":"教育学原理"},{"id":"L5-S01","source":"local","sourceLabel":"（本地：第5卷第1题）","vol":5,"no":1,"section":"单选","sectionNo":1,"type":"single","score":3,"stem":"撰写于我国战国末期，被认为世界上最早专门论述教育问题的文献是（  ）。","options":["《学记》","《论语》","《大学》","《中庸》"],"answer":["A"],"analysis":"《学记》撰写于我国战国末期，是世界上最早专门论述教育问题的文献。《论语》《大学》《中庸》都是儒家经典，但不是专门的教育理论著作。","hint":"世界最早且专门论述教育=《学记》。","tags":["教育史","《学记》"],"category":"教育学原理"},{"id":"L5-S02","source":"local","sourceLabel":"（本地：第5卷第2题）","vol":5,"no":2,"section":"单选","sectionNo":2,"type":"single","score":3,"stem":"“近朱者赤，近墨者黑”反映了下列哪一因素对人的发展的影响？（  ）","options":["遗传","环境","教育","个体活动"],"answer":["B"],"analysis":"“近朱者赤，近墨者黑”比喻处在什么样的环境就会受到什么样的影响，强调环境对人的发展的作用。遗传是生理前提，教育起主导作用，个体活动是内在动力，均不合题意。","hint":"“朱”“墨”都是周围环境的比喻。","tags":["影响人发展的因素","环境"],"category":"教育学原理"},{"id":"L5-S03","source":"local","sourceLabel":"（本地：第5卷第3题）","vol":5,"no":3,"section":"单选","sectionNo":3,"type":"single","score":3,"stem":"近代教育史上曾出现过形式教育论和实质教育论的论争，其根本分歧是（  ）。","options":["以学习直接经验为主还是以学习间接经验为主","以理论教学为主还是以实践教学为主","以学科教学为主还是以活动教学为主","以传授知识为主还是以培养能力为主"],"answer":["D"],"analysis":"形式教育论主张训练能力（官能），实质教育论主张传授实用知识，二者论争的根本分歧是以传授知识为主还是以培养能力为主。A是直接经验与间接经验之争，B、C是另外两组关系。","hint":"形式=能力，实质=知识，抓住这对关键词。","tags":["教学理论","形式教育论"],"category":"教育学原理"},{"id":"L5-S04","source":"local","sourceLabel":"（本地：第5卷第4题）","vol":5,"no":4,"section":"单选","sectionNo":4,"type":"single","score":3,"stem":"“动之以情，晓之以理，导之以行，持之以恒”的做法主要反映了哪一德育过程规律？（  ）","options":["德育过程是具有多种开端的学生知、情、意、行的培养提高过程","德育过程是促进学生思想内部矛盾斗争的过程","德育过程是组织学生活动与交往，统一多方面教育影响的过程","德育过程是长期的、反复的、逐步提高的过程"],"answer":["A"],"analysis":"“动之以情、晓之以理、导之以行、持之以恒”分别对应情、知（理）、行、意，说明德育过程是知、情、意、行多方面培养提高的过程，且可以从不同方面开端。B强调内部矛盾，C强调活动交往，D强调长期反复。","hint":"情、理、行、恒四字分别对应情、知、行、意，即“多种开端”。","tags":["德育过程","知情意行"],"category":"教育学原理"},{"id":"L5-S05","source":"local","sourceLabel":"（本地：第5卷第5题）","vol":5,"no":5,"section":"单选","sectionNo":5,"type":"single","score":3,"stem":"对儿童青少年的成长发展起主导作用的因素是（  ）。","options":["遗传素质","环境","教育","个体的主观能动性"],"answer":["C"],"analysis":"在影响人发展的诸因素中，教育（特别是学校教育）起主导作用。遗传是生理前提，环境提供多种可能，个体主观能动性是决定性因素与内在动力。","hint":"起主导作用的是教育；主观能动性是决定性因素。","tags":["影响人发展的因素","教育主导作用"],"category":"教育学原理"},{"id":"L5-S06","source":"local","sourceLabel":"（本地：第5卷第6题）","vol":5,"no":6,"section":"单选","sectionNo":6,"type":"single","score":3,"stem":"《汉谟拉比法典》是世界迄今完整保存下来的最早的法典，其中包括了诉讼、财产、家庭以及买卖奴隶等内容。这部法典的呈现形式是（  ）。","options":["刻在岩石上","刻在甲骨上","写在羊皮上","写在绢绸上"],"answer":["A"],"analysis":"《汉谟拉比法典》原文刻在一根黑色玄武岩柱上，以石刻形式保存至今。甲骨、羊皮、绢绸都不是该法典的载体。","hint":"汉谟拉比法典=石柱上的石刻。","tags":["文化常识","历史"],"category":"文化素养"},{"id":"L5-S07","source":"local","sourceLabel":"（本地：第5卷第7题）","vol":5,"no":7,"section":"单选","sectionNo":7,"type":"single","score":3,"stem":"张老师在教学中经常用奖励来激发学生动机，培养学生良好的学习习惯。张老师的这种做法符合（  ）。","options":["人本主义学习观","行为主义学习观","认知主义学习观","建构主义学习观"],"answer":["B"],"analysis":"用奖励来激发学习动机、塑造学习习惯，依据的是行为主义的强化原理。人本主义强调自我实现，认知主义强调内部认知结构，建构主义强调主动建构意义。","hint":"奖励、惩罚、强化=行为主义。","tags":["学习理论","行为主义"],"category":"教育心理"},{"id":"L5-S08","source":"local","sourceLabel":"（本地：第5卷第8题）","vol":5,"no":8,"section":"单选","sectionNo":8,"type":"single","score":3,"stem":"晓旭认为服从、听话的孩子就是好孩子，于是她对老师和家长绝对遵从，期望得到他们的赞许。依据科尔伯格的道德发展理论，她的道德发展处于（  ）。","options":["社会契约取向阶段","相对功利取向阶段","寻求认可取向阶段","遵守法规取向阶段"],"answer":["C"],"analysis":"把“服从听话就是好孩子”作为标准、渴望得到赞许，属科尔伯格习俗水平的寻求认可取向（好孩子取向）。相对功利属前习俗，遵守法规强调维护秩序，社会契约属后习俗。","hint":"“好孩子”“渴望赞许”=寻求认可取向。","tags":["科尔伯格","道德发展阶段"],"category":"教育心理"},{"id":"L5-S09","source":"local","sourceLabel":"（本地：第5卷第9题）","vol":5,"no":9,"section":"单选","sectionNo":9,"type":"single","score":3,"stem":"王老师在教学工作中善于采用各种教学策略，取得了很好的教学效果，这反映了王老师的哪一方面能力突出？（  ）。","options":["教学操作","教学归因","教学迁移","教学反思"],"answer":["A"],"analysis":"善于采用各种教学策略并取得良好教学效果，是课堂组织实施层面的能力，即教学操作能力。教学归因是对成败原因的解释，教学迁移是经验迁移，教学反思是事后回溯改进。","hint":"课堂上实际“做”出来的能力=教学操作能力。","tags":["教师能力","教学操作能力"],"category":"教学技能与实践"},{"id":"L5-S10","source":"local","sourceLabel":"（本地：第5卷第10题）","vol":5,"no":10,"section":"单选","sectionNo":10,"type":"single","score":3,"stem":"教育具有自身发展的规律，在有些方面不一定会随着社会的改变而改变。这反映了教育的哪特征？（  ）","options":["阶级性","生产性","目的性","相对独立性"],"answer":["D"],"analysis":"教育有自身的发展规律，某些方面不随社会变化而同步变化，也可能滞后或超前，这体现教育的相对独立性。阶级性、生产性、目的性都不是该表述所指。","hint":"“有自己的规律、不随社会同步变”=相对独立性。","tags":["教育与社会","相对独立性"],"category":"教育学原理"},{"id":"L5-S11","source":"local","sourceLabel":"（本地：第5卷第11题）","vol":5,"no":11,"section":"单选","sectionNo":11,"type":"single","score":3,"stem":"有人认为，教育投资是有效地生产性投资。这种观点主要反映了教育的哪种功能？（  ）","options":["政治功能","经济功能","文化功能","生态功能"],"answer":["B"],"analysis":"把教育投资看成能带来回报的生产性投资，体现教育的经济功能。政治功能指向政权与民主，文化功能指向文化传承创新，生态功能指向人与自然。","hint":"“投资—回报”是经济视角。","tags":["教育功能","经济功能"],"category":"教育学原理"},{"id":"L5-S12","source":"local","sourceLabel":"（本地：第5卷第12题）","vol":5,"no":12,"section":"单选","sectionNo":12,"type":"single","score":3,"stem":"学生课前预习，带着不懂的问题去上课，以便更有针对性地注意听讲。这种注意方式属于（  ）。","options":["有意注意","无意注意","无意后注意","有意后注意"],"answer":["A"],"analysis":"带着问题有目的地听课、需要意志努力维持，属有意注意。无意注意无目的不需意志；有意后注意是有目的但已不需意志努力。","hint":"有目的+需意志努力=有意注意。","tags":["注意","有意注意"],"category":"教育心理"},{"id":"L5-S13","source":"local","sourceLabel":"（本地：第5卷第13题）","vol":5,"no":13,"section":"单选","sectionNo":13,"type":"single","score":3,"stem":"晓春上课时把老师的讲解内容用自己的语言写在课本上，以促进对知识的理解。他采取的学习策略是（  ）。","options":["复述策略","组织策略","计划策略","精加工策略"],"answer":["D"],"analysis":"把老师讲的内容用自己的语言重新整理并记录，属于对信息进行深层加工的精加工策略。复述策略是简单重复，组织策略是归类列提纲，计划策略属元认知的事前安排。","hint":"用自己的话重新加工整理=精加工策略。","tags":["学习策略","精加工策略"],"category":"教育心理"},{"id":"L5-S14","source":"local","sourceLabel":"（本地：第5卷第14题）","vol":5,"no":14,"section":"单选","sectionNo":14,"type":"single","score":3,"stem":"方华情绪兴奋快而强，容易冲动，常常是爆发式的，并伴随有明显外部表现。她的气质类型属于（  ）。","options":["胆汁质","多血质","粘液质","抑郁质"],"answer":["A"],"analysis":"情绪兴奋快而强、容易冲动、爆发式且外部表现明显，是胆汁质的典型特征。多血质活泼灵活，粘液质沉稳迟缓，抑郁质敏感内向。","hint":"急躁冲动、爆发式=胆汁质。","tags":["气质","胆汁质"],"category":"教育心理"},{"id":"L5-S15","source":"local","sourceLabel":"（本地：第5卷第15题）","vol":5,"no":15,"section":"单选","sectionNo":15,"type":"single","score":3,"stem":"张老师在设置教学目标时，既考虑学生的现有知识水平，也考虑他们在老师指导下可以达到的水平。维果斯基将这两种水平之间的差距称为（  ）。","options":["教学支架","最近发展区","先行组织者","自我差异性"],"answer":["B"],"analysis":"维果斯基把学生现有水平与在成人或同伴帮助下可能达到的水平之间的差距称为最近发展区。教学支架是帮助跨越该区域的手段，先行组织者是奥苏贝尔提出的概念。","hint":"“现有水平”与“可能达到的水平”之差=最近发展区。","tags":["维果斯基","最近发展区"],"category":"教育心理"},{"id":"L5-S16","source":"local","sourceLabel":"（本地：第5卷第16题）","vol":5,"no":16,"section":"单选","sectionNo":16,"type":"single","score":3,"stem":"下列关于素质教育的表述中，不正确的是（  ）。","options":["素质教育更要重视德育","素质教育主要适用于基础教育","素质教育应遵循教育规律","素质教育不要求学生平均发展"],"answer":["B"],"analysis":"素质教育是贯穿各级各类教育的指导思想，说它“主要适用于基础教育”是不正确的。素质教育要重视德育、要遵循教育规律、不要求学生平均发展，A、C、D均正确。","hint":"题干问“不正确”，把素质教育限定在某一学段即为错。","tags":["素质教育"],"category":"教育学原理"},{"id":"L5-S17","source":"local","sourceLabel":"（本地：第5卷第17题）","vol":5,"no":17,"section":"单选","sectionNo":17,"type":"single","score":3,"stem":"下列选项中的概念关系，与“教授”和“科学家”一致的是（  ）。","options":["夹克-衬衫","中文书-英文书","足球-篮球","大学生-运动员"],"answer":["D"],"analysis":"“教授”与“科学家”是交叉关系（有的教授是科学家，有的不是，反之亦然）。“大学生”与“运动员”同样是交叉关系；A夹克与衬衫、B中文书与英文书、C足球与篮球都是并列（全异）关系。","hint":"找“有重叠但互不包含”的交叉关系。","tags":["逻辑推理","概念关系"],"category":"文化素养"},{"id":"L5-S18","source":"local","sourceLabel":"（本地：第5卷第18题）","vol":5,"no":18,"section":"单选","sectionNo":18,"type":"single","score":3,"stem":"每次实施新的教学设计之后，彭老师都会问自己:“有没有必要？是不是最好？能不能改进？要不要调整？”这说明彭老师（  ）。","options":["善于自我反思","善于自我激励","缺乏教育自信","缺乏学习方法"],"answer":["A"],"analysis":"每次教学后追问“有没有必要、是不是最好、能不能改进、要不要调整”，是对自身教学实践的持续审视，说明彭老师善于自我反思。自我激励、缺乏自信、缺乏学习方法都不符合题意。","hint":"课后反复追问改进空间=教学反思。","tags":["教师专业发展","教学反思"],"category":"教学技能与实践"},{"id":"L5-S19","source":"local","sourceLabel":"（本地：第5卷第19题）","vol":5,"no":19,"section":"单选","sectionNo":19,"type":"single","score":3,"stem":"开学了，为把素质教育落到实处，某中学语文老师为同学们确定了学期素质教育目标:“每个月读一本名著，识两位名人，听三首名曲，品四幅名画，背五首古诗。”该教师的做法（  ）。","options":["干扰了学生学习的节奏","优化了学生学习的方法","窄化了素质教育的内涵","指明了素质教育的途径"],"answer":["C"],"analysis":"把素质教育简化为“读名著、识名人、听名曲、品名画、背古诗”这类指标，只抓了文化素养的局部，窄化了素质教育的内涵。素质教育强调德智体美劳全面发展和个性发展的统一。","hint":"把丰富内涵压缩成几条任务清单=窄化。","tags":["素质教育"],"category":"教育学原理"},{"id":"L5-S20","source":"local","sourceLabel":"（本地：第5卷第20题）","vol":5,"no":20,"section":"单选","sectionNo":20,"type":"single","score":3,"stem":"下列选项中，不属于我国宪法所规定的公民自由的是（  ）。","options":["出版自由","纳税自由","宗教信仰自由","科学研究自由"],"answer":["B"],"analysis":"我国宪法规定的公民自由包括言论出版自由、宗教信仰自由、科学研究与文艺创作自由等。纳税是公民的基本义务，不是“自由”，故B不属于。","hint":"纳税是义务，不是自由。","tags":["教育法律法规","宪法"],"category":"教育法律法规"},{"id":"L5-M01","source":"local","sourceLabel":"（本地：第5卷第21题）","vol":5,"no":21,"section":"多选","sectionNo":1,"type":"multi","score":4,"stem":"“北斗卫星导航系统”是中国自主研发、独立运行的卫星导航系统，已成功应用于测绘、电信、交通、减灾等诸多领域，产生了显著的经济效益和社会效益。下列关于“北斗卫星导航系统”的表述中，正确的是（  ）。","options":["尚未正式进入民用市场","具有定位和通信双重功能","定位精度正在不断地提高","已覆盖中国本土的全部区域"],"answer":["B","C","D"],"analysis":"北斗系统已广泛应用于测绘、通信、交通、减灾等民用领域，A“尚未进入民用市场”错误；其具备定位与短报文通信双重功能、定位精度不断提高、已覆盖中国本土全部区域，B、C、D正确。","hint":"排除与现实不符的“尚未民用”。","tags":["科技常识","文化常识"],"category":"文化素养"},{"id":"L5-M02","source":"local","sourceLabel":"（本地：第5卷第22题）","vol":5,"no":22,"section":"多选","sectionNo":2,"type":"multi","score":4,"stem":"有些世界性的学科竞赛，是该学科在国际上影响最大、水平最高的大赛，只在中学生里开展。下列选项中，属于国际性中学生学科竞赛的项目是（  ）。","options":["数学奥林匹克竞赛","物理奥林匹克竞赛","化学奥林匹克竞赛","信息学奥林匹克竞赛"],"answer":["A","B","C","D"],"analysis":"面向中学生开展的国际性学科奥林匹克竞赛包括数学、物理、化学、信息学（此外还有生物学）奥林匹克，四项均属于国际中学生学科竞赛项目。","hint":"中学五大学科竞赛：数、物、化、生、信息。","tags":["文化常识","学科竞赛"],"category":"文化素养"},{"id":"L5-M03","source":"local","sourceLabel":"（本地：第5卷第23题）","vol":5,"no":23,"section":"多选","sectionNo":3,"type":"multi","score":4,"stem":"刘老师尝试用学生耳熟能详的流行歌曲旋律对学生需要掌握的学科知识进行重组,形成一系列别具特色的”教学工具包”，取得了良好的效果,还主动与同事分享。关于刘老师的做法，下列说法正确的是（  ）","options":["体现了教学内容的关联性","实现了学生发展的多样性","注重了教学方法的艺术性","尊重了学生认知的规律性"],"answer":["A","C","D"],"analysis":"刘老师用学生熟悉的旋律重组学科知识，体现了教学内容与学生经验的关联性、教学方法的艺术性，也尊重了学生认知规律，A、C、D正确；B“实现了学生发展的多样性”题干未体现，故排除。","hint":"选择与“内容关联、方法艺术、尊重认知规律”相关的表述。","tags":["教学技能","课程资源开发"],"category":"教学技能与实践"},{"id":"L5-M04","source":"local","sourceLabel":"（本地：第5卷第24题）","vol":5,"no":24,"section":"多选","sectionNo":4,"type":"multi","score":4,"stem":"下列现象，是因地球公转而产生的是（  ）。","options":["昼夜的变化","四季的变化","日食","闰年平年"],"answer":["B","C","D"],"analysis":"四季变化、闰年平年的设置都与地球公转周期直接相关，日食的形成也与日月地的公转运行位置有关。A昼夜变化由地球自转产生，故排除。","hint":"昼夜交替来自自转，其余与公转有关。","tags":["科技常识","地理"],"category":"文化素养"},{"id":"L5-M05","source":"local","sourceLabel":"（本地：第5卷第25题）","vol":5,"no":25,"section":"多选","sectionNo":5,"type":"multi","score":4,"stem":"子曰:“学而不思则罔①，思而不学则殆②。”(《论语·为政》)【注释】①罔:迷惑、糊涂。②殆:疑惑、危险。下列对孔子这段话的理解，正确的一项是（  ）。","options":["在孔子看来，学和思二者不能偏废，主张学与思相结合","孔子指出了学而不思的局限，也道出了思而不学的弊端","光学习不思考会越学越危险，光思考不学习会越来越糊涂","孔子学与思相结合的思想，在今天仍有其值得肯定的价值"],"answer":["A","B","D"],"analysis":"孔子主张学与思不可偏废，A、D正确；并指出学而不思与思而不学各有弊端，B正确。C错误：按注释“罔”是迷惑糊涂（对应学而不思），“殆”是疑惑危险（对应思而不学），C把二者说反。","hint":"先看清注释：罔=迷惑，殆=危险，C把两者说反。","tags":["教育史","孔子"],"category":"教育学原理"},{"id":"L5-M06","source":"local","sourceLabel":"（本地：第5卷第26题）","vol":5,"no":26,"section":"多选","sectionNo":6,"type":"multi","score":4,"stem":"“五岳”是我国的五大名山，下列属于“五岳”的是（  ）。","options":["泰山","华山","黄山","衡山"],"answer":["A","B","D"],"analysis":"“五岳”指东岳泰山、西岳华山、南岳衡山、北岳恒山、中岳嵩山，A、B、D属于五岳；黄山以“奇松怪石”著称但不在五岳之列，故排除C。","hint":"五岳：泰山、华山、衡山、恒山、嵩山，黄山不在其中。","tags":["文化常识","地理"],"category":"文化素养"},{"id":"L5-M07","source":"local","sourceLabel":"（本地：第5卷第27题）","vol":5,"no":27,"section":"多选","sectionNo":7,"type":"multi","score":4,"stem":"“四书”是封建社会科举取士的初级标准书。下列属于“四书”的是?（  ）","options":["《中庸》","《大学》","《论语》","《三国演义》"],"answer":["A","B","C"],"analysis":"“四书”指《大学》《中庸》《论语》《孟子》，A、B、C属于四书；《三国演义》是明代小说，不属四书，故排除D。","hint":"四书：大学、中庸、论语、孟子。","tags":["文化常识","国学"],"category":"文化素养"},{"id":"L5-M08","source":"local","sourceLabel":"（本地：第5卷第28题）","vol":5,"no":28,"section":"多选","sectionNo":8,"type":"multi","score":4,"stem":"《中华人民共和国教师法》规定教师有下列情形之一的，由所在学校、其他教育机构或者教育行政部门给予行政处分或者解聘。下列说法哪一项属于“情形之一”的？（  ）","options":["故意不完成教育教学任务给教育教学工作造成损失的","体罚学生，经教育不改的","品行不良、侮辱学生，影响恶劣的","不关心集体的"],"answer":["A","B","C"],"analysis":"《教师法》规定可给予行政处分或解聘的情形包括：故意不完成教育教学任务造成损失、体罚学生经教育不改、品行不良侮辱学生影响恶劣。D“不关心集体”未列入法定情形，故排除。","hint":"法条列了三种情形：教学任务、体罚不改、品行恶劣。","tags":["教育法律法规","教师法"],"category":"教育法律法规"},{"id":"L5-M09","source":"local","sourceLabel":"（本地：第5卷第29题）","vol":5,"no":29,"section":"多选","sectionNo":9,"type":"multi","score":4,"stem":"根据皮亚杰的认识发展阶段理论，以下属于认知发展阶段的是（  ）。","options":["感知运动阶段","前运算阶段","具体运算阶段","形式运算阶段"],"answer":["A","B","C","D"],"analysis":"皮亚杰把认知发展划分为感知运动阶段、前运算阶段、具体运算阶段、形式运算阶段，四项均为其阶段划分。","hint":"皮亚杰四阶段：感知运动、前运算、具体运算、形式运算。","tags":["皮亚杰","认知发展阶段"],"category":"教育心理"},{"id":"L5-M10","source":"local","sourceLabel":"（本地：第5卷第30题）","vol":5,"no":30,"section":"多选","sectionNo":10,"type":"multi","score":4,"stem":"班主任田老师鼓励同学们开展兴趣小组活动，却招来了一些科任教师的反对，因他们觉得这样做会影响学生的考试成绩。面对这种情况，田老师不恰当的做法是（  ）。","options":["取得同事支持，继续指导学生活动","尊重同事意见，暂停兴趣小组活动","利用校长威信，平息同事反对意见","接收科任老师意见，重视考试成绩"],"answer":["B","C","D"],"analysis":"题干问“不恰当”：B一味迁就反对意见暂停活动、C借校长威压平息异议、D转而只重考试成绩，都放弃了素质教育的立场，均不恰当。A争取同事支持并继续指导是恰当做法，故排除。","hint":"放弃素质教育立场或简单压制的做法都不恰当。","tags":["素质教育","班主任工作"],"category":"教学技能与实践"},{"id":"L6-S01","source":"local","sourceLabel":"（本地：第6卷第1题）","vol":6,"no":1,"section":"单选","sectionNo":1,"type":"single","score":3,"stem":"新中国建立初期，我国师范院校教育学课程普遍采用的教材是（  ）","options":["夸美纽斯的《大教学论》","赫尔巴特的《普通教育学》","凯洛夫的《教育学》","马卡连柯的《论共产主义教育》"],"answer":["C"],"analysis":"新中国成立初期我国教育全面学习苏联经验，师范院校普遍采用凯洛夫主编的《教育学》作为教材。夸美纽斯《大教学论》标志教育学开始独立，赫尔巴特《普通教育学》标志规范教育学建立，马卡连柯以集体教育思想著称。","hint":"抓住“新中国建立初期”的时间限定，联想全面学苏联的背景。","tags":["教育史","教育学教材","凯洛夫"],"category":"教育学原理"},{"id":"L6-S02","source":"local","sourceLabel":"（本地：第6卷第2题）","vol":6,"no":2,"section":"单选","sectionNo":2,"type":"single","score":3,"stem":"英语老师孙老师刚从某师范学校毕业，工作上兢兢业业。但她非常追求时尚，经常穿一些比较另类的衣服，佩戴一些夸张的首饰。这主要违背了教师职业道德规范中的（  ）的要求。","options":["爱岗敬业","为人师表","关爱学生","教书育人"],"answer":["B"],"analysis":"教师衣着打扮与言行举止要得体，属为人师表的要求。爱岗敬业强调履职尽责，关爱学生强调尊重爱护，教书育人强调育人的方式与质量，均与着装不当无直接对应。","hint":"衣着举止得体属于“为人师表”。","tags":["教师职业道德","为人师表"],"category":"教师职业道德"},{"id":"L6-S03","source":"local","sourceLabel":"（本地：第6卷第3题）","vol":6,"no":3,"section":"单选","sectionNo":3,"type":"single","score":3,"stem":"“今天的教育就是明天的经济，教育已经成为经济发展的杠杆”。这说明教育具有（  ）。","options":["科学性","阶段性","生产性","独立性"],"answer":["C"],"analysis":"“今天的教育就是明天的经济”说明教育通过提高劳动者素质促进经济发展，具有生产性。科学性、阶段性、独立性都不是该表述强调的属性。","hint":"把教育与经济发展联系起来，选“生产性”。","tags":["教育功能","生产性"],"category":"教育学原理"},{"id":"L6-S04","source":"local","sourceLabel":"（本地：第6卷第4题）","vol":6,"no":4,"section":"单选","sectionNo":4,"type":"single","score":3,"stem":"美国学者孟禄根据原始社会没有学校、没有教师、没有教材的事实，断言教育起源于儿童对成人无意识的模仿。这种观点被称为（  ）。","options":["生物起源论","交往起源论","心理起源论","劳动起源论"],"answer":["C"],"analysis":"孟禄依据原始社会无学校、无教师、无教材的事实，断言教育起源于儿童对成人的无意识模仿，属心理起源论。生物起源论以利托尔诺为代表，劳动起源论是马克思主义的观点。","hint":"孟禄—无意识模仿—心理起源论。","tags":["教育起源","心理起源论"],"category":"教育学原理"},{"id":"L6-S05","source":"local","sourceLabel":"（本地：第6卷第5题）","vol":6,"no":5,"section":"单选","sectionNo":5,"type":"single","score":3,"stem":"于老师在讲台上把一张纸揉成团，把另一张纸烧成灰，由此让学生来理解物质的物理变化与化学变化的区别。于老师采用的教学方法是（  ）。","options":["练习法","演示法","实验法","参观法"],"answer":["B"],"analysis":"教师演示揉纸与烧纸，学生观察后理解物理变化与化学变化的区别，属演示法。练习法是学生反复操练，实验法是学生自己动手操作仪器，参观法是组织到实地观察。","hint":"老师做给学生看=演示法。","tags":["教学方法","演示法"],"category":"教育学原理"},{"id":"L6-S06","source":"local","sourceLabel":"（本地：第6卷第6题）","vol":6,"no":6,"section":"单选","sectionNo":6,"type":"single","score":3,"stem":"对儿童、青少年的成长发展起主导作用的因素是（  ）。","options":["遗传素质","环境","教育","个体的主观能动性"],"answer":["C"],"analysis":"在影响人发展的诸因素中，教育起主导作用。遗传素质是生理前提，环境提供多种可能，个体主观能动性是决定性因素。","hint":"主导作用=教育；决定性因素=主观能动性。","tags":["影响人发展的因素","教育主导作用"],"category":"教育学原理"},{"id":"L6-S07","source":"local","sourceLabel":"（本地：第6卷第7题）","vol":6,"no":7,"section":"单选","sectionNo":7,"type":"single","score":3,"stem":"“学生过度兴奋、各行其是、随便插嘴、故意捣乱”等词语，描述的是哪类课堂氛围表现？（  ）","options":["积极型","消极型","对抗型","顺从型"],"answer":["C"],"analysis":"“过度兴奋、各行其是、随便插嘴、故意捣乱”是失控、与教师对抗的表现，属对抗型课堂气氛。消极型表现为无精打采、被动应付，积极型是热烈而有序。","hint":"故意捣乱、与教师对立=对抗型。","tags":["课堂管理","课堂气氛"],"category":"教学技能与实践"},{"id":"L6-S08","source":"local","sourceLabel":"（本地：第6卷第8题）","vol":6,"no":8,"section":"单选","sectionNo":8,"type":"single","score":3,"stem":"晓军上中学后，自尊心越来越强，自我评价越来越客观、全面，自我控制能力明显提高。这反映的是晓军自我意识哪一方面的发展？（  ）","options":["生理自我","心理自我","社会自我","物质自我"],"answer":["B"],"analysis":"自尊心、自我评价、自我控制属于个体对自身心理特征的认识与调控，即心理自我的发展。生理自我是对身体外貌的意识，社会自我是对人际角色与社会地位的认识。","hint":"自尊、自我评价、自控=心理层面的自我。","tags":["自我意识","心理自我"],"category":"教育心理"},{"id":"L6-S09","source":"local","sourceLabel":"（本地：第6卷第9题）","vol":6,"no":9,"section":"单选","sectionNo":9,"type":"single","score":3,"stem":"阳慧在解决问题的过程中，常以老师、同学的建议作为参照做出决策。她的这种认知风格属于（  ）。","options":["场依存型","场独立型","继时型","同时型"],"answer":["A"],"analysis":"场依存型认知风格者以外部线索为参照，易受他人意见与环境暗示影响。场独立型依靠内部参照；继时型与同时型按信息加工方式划分，与参照依据无关。","hint":"依赖他人建议做决策=外部参照=场依存型。","tags":["认知风格","场依存"],"category":"教育心理"},{"id":"L6-S10","source":"local","sourceLabel":"（本地：第6卷第10题）","vol":6,"no":10,"section":"单选","sectionNo":10,"type":"single","score":3,"stem":"同学们正在教室里聚精会神地听老师讲课，突然从教室外飞进来一只小鸟，于是大家不约而同地把视线朝向小鸟。这种现象属于（  ）","options":["随意前注意","随意后注意","无意注意","有意注意"],"answer":["C"],"analysis":"小鸟突然飞入引起的注意无预定目的、不需意志努力，属无意注意。有意注意有目的且需意志努力；A“随意前注意”、B“随意后注意”都不是本题情境下的规范答案。","hint":"突发刺激自动吸引注意=无意注意。","tags":["注意","无意注意"],"category":"教育心理"},{"id":"L6-S11","source":"local","sourceLabel":"（本地：第6卷第11题）","vol":6,"no":11,"section":"单选","sectionNo":11,"type":"single","score":3,"stem":"卢梭从自然教育观出发，提出培养自然人的教育目的，这种教育目的观属于（  ）。","options":["社会本位论","宗教本位论","自然本位论","个人本位论"],"answer":["D"],"analysis":"卢梭主张按儿童天性培养“自然人”，强调个体自身的发展，属个人本位论。社会本位论强调为社会培养公民，宗教本位论以宗教目的为中心。","hint":"培养“自然人”、顺应天性=个人本位论。","tags":["教育目的","个人本位论"],"category":"教育学原理"},{"id":"L6-S12","source":"local","sourceLabel":"（本地：第6卷第12题）","vol":6,"no":12,"section":"单选","sectionNo":12,"type":"single","score":3,"stem":"晓旭认为服从、听话的孩子就是好孩子，于是她对老师和家长绝对遵从，期望得到他们的赞许。根据科尔伯格的道德发展理论，她的道德发展处于（  ）","options":["社会契约取向阶段","相对功利取向阶段","寻求认可取向阶段","遵守法规取向阶段"],"answer":["C"],"analysis":"“服从听话就是好孩子”、渴望得到赞许，属科尔伯格习俗水平的寻求认可取向。相对功利取向属前习俗水平，遵守法规取向强调维护秩序，社会契约取向属后习俗水平。","hint":"“好孩子”“渴望赞许”=寻求认可取向。","tags":["科尔伯格","道德发展阶段"],"category":"教育心理"},{"id":"L6-S13","source":"local","sourceLabel":"（本地：第6卷第13题）","vol":6,"no":13,"section":"单选","sectionNo":13,"type":"single","score":3,"stem":"王建在课堂上玩手机，老师没有直接提出批评，而是表扬了认真听讲的冯军。王建看了看冯军，也开始认真听讲了。该老师使用的课堂管理方法是（  ）","options":["直接干预","替代强化","团体警觉","处理转换"],"answer":["B"],"analysis":"班杜拉的替代强化指观察者看到榜样被强化而自身行为受到影响。老师表扬认真听讲的冯军，王建受其影响也开始认真听讲，属替代强化。直接干预是明示纠正，团体警觉面向全体提醒。","hint":"不批评本人、借表扬旁人来影响本人=替代强化。","tags":["课堂管理","班杜拉","替代强化"],"category":"教学技能与实践"},{"id":"L6-S14","source":"local","sourceLabel":"（本地：第6卷第14题）","vol":6,"no":14,"section":"单选","sectionNo":14,"type":"single","score":3,"stem":"“再生产科学所必要的劳动时间，同最初生产科学所需要的劳动时间是无法相比的，例如学生在一小时内就能学会二项式定理。”这表明教学活动具有（  ）。","options":["引导性","直接性","简捷性","实践性"],"answer":["C"],"analysis":"学生一小时学会二项式定理，说明教学能走人类认识的捷径、高效传递知识，体现简捷性。引导性强调教师引导，直接性与教学以间接经验为主相悖，实践性强调动手操作。","hint":"短时间内掌握长期积累的知识=简捷性。","tags":["教学过程","简捷性"],"category":"教育学原理"},{"id":"L6-S15","source":"local","sourceLabel":"（本地：第6卷第15题）","vol":6,"no":15,"section":"单选","sectionNo":15,"type":"single","score":3,"stem":"韩波进入中学后，经常独自思考“我是谁”，未来从事何种职业，在社会上处于什么样的地位等问题。根据埃里克森的人格发展阶段理论，韩波的人格发展处于（  ）。","options":["主动对内疚阶段","同一性对角色混乱阶段","自我整合对绝望阶段","自主对羞耻和疑虑阶段"],"answer":["B"],"analysis":"中学生反复思考“我是谁”“未来从事何种职业”，是青少年期自我同一性对角色混乱阶段的典型表现。主动对内疚属学前期，自主对羞怯属幼儿期，自我整合对绝望属老年期。","hint":"追问“我是谁”=自我同一性对角色混乱。","tags":["埃里克森","人格发展"],"category":"教育心理"},{"id":"L6-S16","source":"local","sourceLabel":"（本地：第6卷第16题）","vol":6,"no":16,"section":"单选","sectionNo":16,"type":"single","score":3,"stem":"晓东期中考试成绩不理想，其父母承诺如果期末考试成绩优异，就奖励他一部手机，于是他学习更加努力。晓东的这种学习动机属于（  ）","options":["近景、外部动机","近景、内部动机","远景、外部动机","远景、内部动机"],"answer":["A"],"analysis":"期末考试是近期目标，属近景动机；手机奖励是外部诱因，属外部动机。内部动机来自对学习本身的兴趣，远景动机指向长远理想。","hint":"按“时间远近”和“动力内外”两个维度判断。","tags":["学习动机","动机分类"],"category":"教育心理"},{"id":"L6-S17","source":"local","sourceLabel":"（本地：第6卷第17题）","vol":6,"no":17,"section":"单选","sectionNo":17,"type":"single","score":3,"stem":"教学过程是一种特殊的认识过程，其区别于人类一般认识的特点是（  ）","options":["主动性、间接性和引导性","探索性、间接性和引导性","间接性、引导性和简捷性","间接性、引导性和复杂性"],"answer":["C"],"analysis":"教学认识的特殊性表现为间接性（以书本间接经验为主）、引导性（在教师引导下认识）、简捷性（走认识的捷径）。主动性、探索性、复杂性都不是规范概括。","hint":"三性口诀：间接、引导、简捷。","tags":["教学过程","教学认识特殊性"],"category":"教育学原理"},{"id":"L6-S18","source":"local","sourceLabel":"（本地：第6卷第18题）","vol":6,"no":18,"section":"单选","sectionNo":18,"type":"single","score":3,"stem":"新课程改革以来，不少中学把“档案袋评价”作为评价学生的方式之一。这种评价属于（  ）","options":["诊断性评价","形成性评价","终结性评价","标准性评价"],"answer":["B"],"analysis":"档案袋评价收集学生学习过程中的作品与记录，用于改进学与教，属形成性评价。诊断性评价在教学前摸底，终结性评价在教学结束后作总结判断。","hint":"记录“过程”的评价=形成性评价。","tags":["教学评价","形成性评价"],"category":"教学技能与实践"},{"id":"L6-S19","source":"local","sourceLabel":"（本地：第6卷第19题）","vol":6,"no":19,"section":"单选","sectionNo":19,"type":"single","score":3,"stem":"李利今天新学习了20个英文单词，放学后，他就一遍一遍地背诵，直至背会全部单词，这种学习策略属于（  ）","options":["监控策略","组织策略","计划策略","复述策略"],"answer":["D"],"analysis":"一遍遍诵读直至背会属于复述策略（通过重复保持信息）。组织策略是归类列提纲，计划策略属元认知中的事前规划，监控策略是对学习过程的监视调节。","hint":"重复诵读以记住=复述策略。","tags":["学习策略","复述策略"],"category":"教育心理"},{"id":"L6-S20","source":"local","sourceLabel":"（本地：第6卷第20题）","vol":6,"no":20,"section":"单选","sectionNo":20,"type":"single","score":3,"stem":"有人认为，教育投资是有效的生产性投资。这种观点主要反映了教育的哪种功能？（  ）","options":["政治功能","经济功能","文化功能","生态功能"],"answer":["B"],"analysis":"把教育视为能带来回报的生产性投资，体现教育的经济功能。政治功能指向政权与民主，文化功能指向文化传承，生态功能指向人与自然。","hint":"“投资—回报”是经济视角。","tags":["教育功能","经济功能"],"category":"教育学原理"},{"id":"L6-M01","source":"local","sourceLabel":"（本地：第6卷第21题）","vol":6,"no":21,"section":"多选","sectionNo":1,"type":"multi","score":4,"stem":"讲授法是教师通过口头语言系统连贯的向学生传授知识的方法，主要有以下哪几种方式（  ）","options":["讲述","描述","讲解","讲演"],"answer":["A","C","D"],"analysis":"讲授法的具体方式包括讲述、讲解、讲读、讲演，A、C、D属于其中；B“描述”是文学表达方式，不是讲授法的规范类型，故排除。","hint":"讲授四方式：讲述、讲解、讲读、讲演。","tags":["教学方法","讲授法"],"category":"教育学原理"},{"id":"L6-M02","source":"local","sourceLabel":"（本地：第6卷第22题）","vol":6,"no":22,"section":"多选","sectionNo":2,"type":"multi","score":4,"stem":"对于探究性学习的组织与引导，以下说法恰当的是（  ）","options":["教师只帮助学生澄清问题，并不给出直接的答案","问题一般要由教师给出","鼓励学生通过试验或参考其它资料来检验其合理性","激发学生的问题意识是探究性学习的核心"],"answer":["A","C","D"],"analysis":"探究性学习强调学生自主发现与提出问题：教师只帮助澄清问题不直接给答案、鼓励自行检验合理性、激发问题意识是核心。B“问题一般由教师给出”违背自主探究，故排除。","hint":"探究学习的核心是学生自主，教师不包办。","tags":["学习方式","探究性学习"],"category":"教学技能与实践"},{"id":"L6-M03","source":"local","sourceLabel":"（本地：第6卷第23题）","vol":6,"no":23,"section":"多选","sectionNo":3,"type":"multi","score":4,"stem":"讲授法的主要缺点在于（  ）","options":["过分强调教师的主导作用，忽视学生的主体地位","不利于启发学生的思维和想象","面向全体学生，无法照顾学生的个别差异","不利于学生解决问题能力的提升"],"answer":["A","B","C","D"],"analysis":"讲授法的公认局限：教师主导过度忽视学生主体、不利于启发思维与想象、面向全体难以照顾个别差异、不利于解决问题能力培养，四项均成立。","hint":"缺点集中在“学生被动”和“难因材施教”。","tags":["教学方法","讲授法"],"category":"教育学原理"},{"id":"L6-M04","source":"local","sourceLabel":"（本地：第6卷第24题）","vol":6,"no":24,"section":"多选","sectionNo":4,"type":"multi","score":4,"stem":"以下关于问题导入的形式的说法，正确的是（  ）","options":["可以单刀直入，直接提出问题","可以从侧面提问设置","只能由教师提问","可以由“谜语”等形式来呈现"],"answer":["A","B","D"],"analysis":"问题导入可直接提问、可从侧面设悬疑、可借谜语等形式呈现，形式灵活。C“只能由教师提问”表述绝对化，学生也可质疑提问，故排除。","hint":"见到“只能”这种绝对表述，优先排除。","tags":["教学技能","课堂导入"],"category":"教学技能与实践"},{"id":"L6-M05","source":"local","sourceLabel":"（本地：第6卷第25题）","vol":6,"no":25,"section":"多选","sectionNo":5,"type":"multi","score":4,"stem":"下列教学用语中，有利于促进学生学习的是（  ）。","options":["“你读得很响亮，若再有感情一点就好了。你再试试。”","“刚才这位同学概括得不准确，还是我来吧。”","“这位同学的发言并没有重复前面同学说过的话，有自己的观点，非常好。”","“请大家想一想，刚才这两位同学报告的结论，有何不同？”"],"answer":["A","C","D"],"analysis":"A先肯定再提出改进建议、C肯定学生有自己的观点、D引导全体比较思考，都能促进学习。B直接否定学生并由教师包办，打击积极性，故排除。","hint":"排除否定学生、由教师包办的教学用语。","tags":["教学技能","教学用语"],"category":"教学技能与实践"},{"id":"L6-M06","source":"local","sourceLabel":"（本地：第6卷第26题）","vol":6,"no":26,"section":"多选","sectionNo":6,"type":"multi","score":4,"stem":"关于学生学习的特点，以下哪些说法是正确的？（  ）","options":["学生的学习是以掌握直接知识经验为主的","学生的学习是在教师有目的、有计划、有组织地指导下进行的","学生学习的主要任务是掌握系统的科学知识、技能，形成世界观、道德品质","学生的学习具有一定程度的被动性"],"answer":["B","C","D"],"analysis":"学生学习以掌握间接经验为主，故A错误；学生学习是在教师有目的、有计划、有组织指导下进行的，主要任务是掌握系统知识技能并形成世界观与道德品质，也具有一定程度的被动性，B、C、D正确。","hint":"学生学习以间接经验为主，A说“直接”故错。","tags":["学习理论","学生学习特点"],"category":"教育心理"},{"id":"L6-M07","source":"local","sourceLabel":"（本地：第6卷第27题）","vol":6,"no":27,"section":"多选","sectionNo":7,"type":"multi","score":4,"stem":"某校实施了“师徒制”，经验丰富的吴老师对新入职的蒋老师进行帮助时，以下做法不恰当的是（  ）。","options":["保守原则，等蒋老师请教时才进行指导","主动指导，和蒋老师商讨并确定教学方案","推门听课，发现不妥之处，及时在课堂上纠正","充分信任，让蒋老师独自探索并积累教学经验"],"answer":["A","C","D"],"analysis":"题干问“不恰当”：A保守等待缺乏主动、C推门听课当场纠正伤害新教师自尊、D完全放手让新教师独自探索都是指导缺位或方式不当。B主动指导并商讨方案是恰当做法，故排除。","hint":"先找出“恰当”的那一项并排除。","tags":["教师专业发展","师徒制"],"category":"教学技能与实践"},{"id":"L6-M08","source":"local","sourceLabel":"（本地：第6卷第28题）","vol":6,"no":28,"section":"多选","sectionNo":8,"type":"multi","score":4,"stem":"根据皮亚杰的认知发展理论，具体运算阶段具备哪些思维特点？（  ）","options":["“泛灵性”，认为外界的一切事物都是有生命的","拥有守恒的概念","思维能够前推也能后退，具备可逆性","能够进行简单的抽象思维，但需要具体事物的支持"],"answer":["B","C","D"],"analysis":"具体运算阶段的特点包括获得守恒概念、思维可逆、能进行需具体事物支持的简单抽象思维。A“泛灵性”是前运算阶段的特点，故排除。","hint":"泛灵论属前运算阶段，不在具体运算阶段。","tags":["皮亚杰","具体运算"],"category":"教育心理"},{"id":"L6-M09","source":"local","sourceLabel":"（本地：第6卷第29题）","vol":6,"no":29,"section":"多选","sectionNo":9,"type":"multi","score":4,"stem":"终身教育是贯穿于人的一生的教育，终身教育的特点包括什么?（  ）","options":["终身性","全民性","广泛性","灵活性和实用性"],"answer":["A","B","C","D"],"analysis":"终身教育的特点包括终身性（贯穿一生）、全民性（面向所有人）、广泛性（内容与形式多样）、灵活性和实用性，四项均正确。","hint":"四特点：终身、全民、广泛、灵活实用。","tags":["教育思潮","终身教育"],"category":"教育学原理"},{"id":"L6-M10","source":"local","sourceLabel":"（本地：第6卷第30题）","vol":6,"no":30,"section":"多选","sectionNo":10,"type":"multi","score":4,"stem":"探究性学习的优势主要表现在（  ）","options":["可以增强学生与他人一起解决现实生活中问题的意愿","可以使学生更为深入地理解所获得的知识和技能，增强思维能力、操作能力","可以学以致用","能够拓展学生的学科视野，便于学生掌握完全的知识"],"answer":["A","B","C","D"],"analysis":"探究性学习的优势包括增强协作解决现实问题的意愿、深化对知识技能的理解并提升思维与操作能力、促进学以致用、拓展学科视野，四项均属其优势。","hint":"探究优势：深入理解+学以致用+协作+视野。","tags":["学习方式","探究性学习"],"category":"教学技能与实践"},{"id":"L7-S01","source":"local","sourceLabel":"（本地：第7卷第1题）","vol":7,"no":1,"section":"单选","sectionNo":1,"type":"single","score":3,"stem":"李老师经常担心的问题是:\"这些内容是学生们需要的吗?\"我这样教，学生能接受吗?”这表明杨老师所处的教师专业发展阶段是（  ）。","options":["虚拟关注阶段","生存关注阶段","自我更新关注阶段","任务关注阶段"],"answer":["C"],"analysis":"教师持续追问“这些内容是学生需要的吗”“学生能接受吗”，说明其已超越生存适应，转而关注学生需求与教学本身的持续改进，属自我更新关注阶段。虚拟关注是职前阶段，生存关注担心能否站稳讲台，任务关注聚焦完成教学任务。","hint":"关键词是“学生需要、学生能否接受”——关注学生与教学改进。","tags":["教师专业发展","关注阶段"],"category":"教学技能与实践"},{"id":"L7-S02","source":"local","sourceLabel":"（本地：第7卷第2题）","vol":7,"no":2,"section":"单选","sectionNo":2,"type":"single","score":3,"stem":"于老师在讲台上把张一纸揉成团，把另一张纸烧成灰，由此让学生来理解物质的物理变化与化学变化的区别。于老师采用的教学方法是（  ）。","options":["练习法","演示法","实验法","参观法"],"answer":["B"],"analysis":"教师在讲台上演示揉纸与烧纸，学生观察后理解物理变化与化学变化的区别，属演示法。练习法是学生反复操练，实验法是学生自己动手操作，参观法是组织到实地观察。","hint":"老师做给学生看=演示法；学生自己动手=实验法。","tags":["教学方法","演示法"],"category":"教育学原理"},{"id":"L7-S03","source":"local","sourceLabel":"（本地：第7卷第3题）","vol":7,"no":3,"section":"单选","sectionNo":3,"type":"single","score":3,"stem":"“动之以情，晓之以理，导之以行，持之以恒”的做法主要反映了哪一德育过程规律？（  ）","options":["德育过程是具有多种开端的学生知、情、意、行的培养提高过程","德育过程是促进学生思想内部矛盾斗争的过程","德育过程是组织学生活动与交往，统一多方面教育影响的过程","德育过程是长期的、反复的、逐步提高的过程"],"answer":["A"],"analysis":"“动之以情、晓之以理、导之以行、持之以恒”分别对应情、知、行、意，说明德育过程是知、情、意、行多方面培养提高的过程，且可从不同方面开端。B强调内部矛盾斗争，C强调活动与交往，D强调长期反复。","hint":"情、理、行、恒四字分别对应情、知、行、意，即“多种开端”。","tags":["德育过程","知情意行"],"category":"教育学原理"},{"id":"L7-S04","source":"local","sourceLabel":"（本地：第7卷第4题）","vol":7,"no":4,"section":"单选","sectionNo":4,"type":"single","score":3,"stem":"近代教育史上曾出现过形式教育论和实质教育论的论争，其根本分歧是（  ）。","options":["以学习直接经验为主还是以学习间接经验为主","以理论教学为主还是以实践教学为主","以学科教学为主还是以活动教学为主","以传授知识为主还是以培养能力为主"],"answer":["D"],"analysis":"形式教育论主张训练能力（官能），实质教育论主张传授实用知识，二者论争的根本分歧是以传授知识为主还是以培养能力为主。A是直接经验与间接经验之争，B是理论与实践之争，C是课程类型之争。","hint":"形式=能力，实质=知识，抓住这对关键词。","tags":["教学理论","形式教育论"],"category":"教育学原理"},{"id":"L7-S05","source":"local","sourceLabel":"（本地：第7卷第5题）","vol":7,"no":5,"section":"单选","sectionNo":5,"type":"single","score":3,"stem":"教编程的高老师根据学生上学期期末成绩将学生分为A.B.C三类，并对三类学生制定了不同的教学计划。陈老师的做法体现的是（  ）","options":["学生发展的个体差异性","学生发展的不平衡性","学生发展的未完成性","学生发展的阶段性"],"answer":["A"],"analysis":"按成绩把学生分为三类并制定不同教学计划，是承认并针对学生之间差异的做法，体现个体差异性。不平衡性指发展速度不均，未完成性不是规范表述，阶段性强调不同年龄阶段的特征。","hint":"分层、分类、区别对待=个体差异性。","tags":["身心发展规律","个别差异性"],"category":"教育学原理"},{"id":"L7-S06","source":"local","sourceLabel":"（本地：第7卷第6题）","vol":7,"no":6,"section":"单选","sectionNo":6,"type":"single","score":3,"stem":"有人认为，教育投资是有效地生产性投资。这种观点主要反映了教育的哪种功能？（  ）","options":["政治功能","经济功能","文化功能","生态功能"],"answer":["B"],"analysis":"把教育投资看成能带来回报的生产性投资，体现教育的经济功能。政治功能指向政权与民主，文化功能指向文化传承创新，生态功能指向人与自然。","hint":"“投资—回报”是经济视角。","tags":["教育功能","经济功能"],"category":"教育学原理"},{"id":"L7-S07","source":"local","sourceLabel":"（本地：第7卷第7题）","vol":7,"no":7,"section":"单选","sectionNo":7,"type":"single","score":3,"stem":"晓春上课时把老师的讲解内容用自己的语言写在课本上，以促进对知识的理解。他采取的学习策略是（  ）。","options":["复述策略","组织策略","计划策略","精加工策略"],"answer":["D"],"analysis":"把老师讲的内容用自己的语言重新写在课本上以促进理解，是对信息进行深层加工的精加工策略。复述策略是简单重复，组织策略是归类列提纲，计划策略属元认知中的事前安排。","hint":"用自己的话重新加工=精加工策略。","tags":["学习策略","精加工策略"],"category":"教育心理"},{"id":"L7-S08","source":"local","sourceLabel":"（本地：第7卷第8题）","vol":7,"no":8,"section":"单选","sectionNo":8,"type":"single","score":3,"stem":"下列选项中，与\"侗服——服装”的逻辑关系相同的是（  ）","options":["“语文”和“文学”","“汽水”和“饮料”","“领带”和”\"围巾”","“皮鞋”和“皮包\""],"answer":["B"],"analysis":"“侗服——服装”是具体事物与其所属大类的种属关系（侗服是一种服装）；“汽水——饮料”同样是种属关系。A语文与文学是学科与内容的关系，C领带与围巾、D皮鞋与皮包都是并列关系。","hint":"找“某物是某大类中的一种”的种属关系。","tags":["逻辑推理","概念关系"],"category":"文化素养"},{"id":"L7-S09","source":"local","sourceLabel":"（本地：第7卷第9题）","vol":7,"no":9,"section":"单选","sectionNo":9,"type":"single","score":3,"stem":"张老师在设置教学目标时，既考虑学生的现有知识水平，也考虑他们在老师指导下可以达到的水平。维果斯基将这两种水平之间的差距称为（  ）。","options":["教学支架","最近发展区","先行组织者","自我差异性"],"answer":["B"],"analysis":"维果斯基把学生现有水平与在教师指导下可能达到的水平之间的差距称为最近发展区。教学支架是帮助跨越该区域的手段，先行组织者是奥苏贝尔提出的概念。","hint":"“现有水平”与“可能达到的水平”之差=最近发展区。","tags":["维果斯基","最近发展区"],"category":"教育心理"},{"id":"L7-S10","source":"local","sourceLabel":"（本地：第7卷第10题）","vol":7,"no":10,"section":"单选","sectionNo":10,"type":"single","score":3,"stem":"某校长在期末总结会上说:“我校学生成绩远超其他学校，成功的法宝就是把最好的资源集中在语文、数学、英语单科上，并缩减综合实践活动课时，将缩减的课时用在重点学科的学习上。”这种做法（  ）。","options":["有利于教育质量提升","不利于学生全面发展","有利于重点学科学习","不利于教师自我提升"],"answer":["B"],"analysis":"把资源集中在语数外并缩减综合实践活动课时，牺牲了学生的多方面发展，不利于学生全面发展。A、C肯定该做法，D谈教师自我提升，都不是对这种做法的正确评价。","hint":"缩减综合实践课时=牺牲全面发展。","tags":["素质教育","全面发展"],"category":"教育学原理"},{"id":"L7-S11","source":"local","sourceLabel":"（本地：第7卷第11题）","vol":7,"no":11,"section":"单选","sectionNo":11,"type":"single","score":3,"stem":"李伟同学在上课前会对本节课的内容进行判断，如果认为自己能听懂老师讲述的知识，他就会认真听课。根据班杜拉的理论，这种现象是（  ）","options":["结果期待","过程期待","社会期待","效能期待"],"answer":["D"],"analysis":"班杜拉区分结果期待（对行为会带来何种结果的估计）与效能期待（对自己能否完成该行为的判断）。“认为自己能听懂”是对自身能力的判断，属效能期待。","hint":"判断“我能不能做到”是效能期待。","tags":["班杜拉","自我效能感"],"category":"教育心理"},{"id":"L7-S12","source":"local","sourceLabel":"（本地：第7卷第12题）","vol":7,"no":12,"section":"单选","sectionNo":12,"type":"single","score":3,"stem":"近年来我国对农村中小学的布局结构进行了调整。这主要反映了下列哪一因素对教育的影响？（  ）","options":["政治制度","经济制度","人口变化","文化传统"],"answer":["C"],"analysis":"农村中小学布局调整的直接原因是学龄人口减少与人口流动，属人口因素对教育的影响。政治制度、经济制度、文化传统都是影响因素，但不是布局调整的主因。","hint":"学校“布局调整”主要由学生数量与分布变化引起。","tags":["教育与社会","人口"],"category":"教育学原理"},{"id":"L7-S13","source":"local","sourceLabel":"（本地：第7卷第13题）","vol":7,"no":13,"section":"单选","sectionNo":13,"type":"single","score":3,"stem":"同学们正在教室里聚精会神地听老师讲课，突然从教室外飞进来一只小鸟，于是大家不约而同地把视线朝向小鸟。这种现象属于（  ）","options":["随意前注意","随意后注意","无意注意","有意注意"],"answer":["C"],"analysis":"小鸟突然飞入引起的注意无预定目的、不需意志努力，属无意注意。有意注意有目的且需意志努力；A、B不是该情境下的规范答案。","hint":"突发刺激自动吸引注意=无意注意。","tags":["注意","无意注意"],"category":"教育心理"},{"id":"L7-S14","source":"local","sourceLabel":"（本地：第7卷第14题）","vol":7,"no":14,"section":"单选","sectionNo":14,"type":"single","score":3,"stem":"晓旭认为服从、听话的孩子就是好孩子，于是她对老师和家长绝对遵从，期望得到他们的赞许。根据科尔伯格的道德发展理论，她的道德发展处于（  ）","options":["社会契约取向阶段","相对功利取向阶段","寻求认可取向阶段","遵守法规取向阶段"],"answer":["C"],"analysis":"“服从听话就是好孩子”、期望得到赞许，属科尔伯格习俗水平的寻求认可取向。相对功利取向属前习俗水平，遵守法规取向强调维护秩序，社会契约取向属后习俗水平。","hint":"“好孩子”“期望赞许”=寻求认可取向。","tags":["科尔伯格","道德发展阶段"],"category":"教育心理"},{"id":"L7-S15","source":"local","sourceLabel":"（本地：第7卷第15题）","vol":7,"no":15,"section":"单选","sectionNo":15,"type":"single","score":3,"stem":"每次实施新的教学设计之后，彭老师都会问自己:“有没有必要？是不是最好？能不能改进？要不要调整？”这说明彭老师（  ）。","options":["善于自我反思","善于自我激励","缺乏教育自信","缺乏学习方法"],"answer":["A"],"analysis":"每次教学后追问“有没有必要、是不是最好、能不能改进、要不要调整”，是对自身教学实践的持续审视，说明彭老师善于自我反思。自我激励、缺乏自信、缺乏学习方法都不符合题意。","hint":"课后反复追问改进空间=教学反思。","tags":["教师专业发展","教学反思"],"category":"教学技能与实践"},{"id":"L7-S16","source":"local","sourceLabel":"（本地：第7卷第16题）","vol":7,"no":16,"section":"单选","sectionNo":16,"type":"single","score":3,"stem":"古希腊斯巴达教育的目的是培养（  ）。","options":["演说家","智者","军人和武士","全面和谐发展的人"],"answer":["C"],"analysis":"斯巴达教育以军事体育为主，目的是培养骁勇善战的军人和武士；雅典教育追求身心和谐发展，培养多方面发展的人；演说家是古罗马教育的目标。","hint":"斯巴达=军事；雅典=和谐发展。","tags":["教育史","古代教育"],"category":"教育学原理"},{"id":"L7-S17","source":"local","sourceLabel":"（本地：第7卷第17题）","vol":7,"no":17,"section":"单选","sectionNo":17,"type":"single","score":3,"stem":"我国第一位系统传播马克思主义教育理论，并出版《新教育大纲》的教育理论家是（  ）。","options":["杨贤江","陶行知","黄炎培","李大钊"],"answer":["A"],"analysis":"杨贤江的《新教育大纲》是我国第一部系统传播马克思主义教育理论的著作。陶行知倡导生活教育，黄炎培倡导职业教育，李大钊是马克思主义传播者但非该教育专著作者。","hint":"杨贤江《新教育大纲》=中国马克思主义教育学第一书。","tags":["教育史","杨贤江"],"category":"教育学原理"},{"id":"L7-S18","source":"local","sourceLabel":"（本地：第7卷第18题）","vol":7,"no":18,"section":"单选","sectionNo":18,"type":"single","score":3,"stem":"对儿童、青少年的成长发展起主导作用的因素是（  ）。","options":["遗传素质","环境","教育","个体的主观能动性"],"answer":["C"],"analysis":"在影响人发展的诸因素中，教育（特别是学校教育）起主导作用。遗传素质是生理前提，环境提供多种可能，个体主观能动性是决定性因素与内在动力。","hint":"起主导作用的是教育；主观能动性是决定性因素。","tags":["影响人发展的因素","教育主导作用"],"category":"教育学原理"},{"id":"L7-S19","source":"local","sourceLabel":"（本地：第7卷第19题）","vol":7,"no":19,"section":"单选","sectionNo":19,"type":"single","score":3,"stem":"在课程和教学理论的发展过程中，曾出现形式教育论和实质教育论之争。这是对哪一关系的争论?（  ）","options":["直接经验与间接经验","知识与能力","分科与综合","知识与思想"],"answer":["B"],"analysis":"形式教育论主张训练能力，实质教育论主张传授实用知识，二者之争的实质是知识与能力的关系。A是直接经验与间接经验之争，C是分科与综合之争，D是知识与思想的关系。","hint":"形式=能力，实质=知识。","tags":["教学理论","形式教育论"],"category":"教育学原理"},{"id":"L7-S20","source":"local","sourceLabel":"（本地：第7卷第20题）","vol":7,"no":20,"section":"单选","sectionNo":20,"type":"single","score":3,"stem":"“近朱者赤，近墨者黑”反映了下列哪一因素对人的发展的影响？（  ）","options":["遗传","环境","教育","个体活动"],"answer":["B"],"analysis":"“近朱者赤，近墨者黑”比喻处在什么样的环境就会受到什么样的影响，强调环境对人的发展的作用。遗传是生理前提，教育起主导作用，个体活动是内在动力。","hint":"“朱”“墨”都是周围环境的比喻。","tags":["影响人发展的因素","环境"],"category":"教育学原理"},{"id":"L7-M01","source":"local","sourceLabel":"（本地：第7卷第21题）","vol":7,"no":21,"section":"多选","sectionNo":1,"type":"multi","score":4,"stem":"以下关于问题导入形式的说法，正确的是（  ）","options":["可以单刀直入，直接提出问题","可以从侧面提问设置悬疑","只能由教师提问","可以由“谜语”等形式来呈现"],"answer":["A","B","D"],"analysis":"问题导入可直接提出问题、可从侧面设置悬疑、可借谜语等形式呈现，形式灵活。C“只能由教师提问”表述绝对化，学生也可提出疑问，故排除。","hint":"见到“只能”这类绝对表述，优先排除。","tags":["教学技能","课堂导入"],"category":"教学技能与实践"},{"id":"L7-M02","source":"local","sourceLabel":"（本地：第7卷第22题）","vol":7,"no":22,"section":"多选","sectionNo":2,"type":"multi","score":4,"stem":"新入职的杨老师为了上好课，积极研究学科教学知识，主动向教研员请教，还坚持写教学日志。对杨老师的做法，下列评价恰当的是（  ）。","options":["注重专家引领","注重自我研修","注重自我反思","注重校本研修"],"answer":["A","B","C"],"analysis":"主动向教研员请教体现专家引领，研究学科教学知识体现自我研修，坚持写教学日志体现自我反思，A、B、C正确。D“校本研修”是学校有组织地开展的研修活动，杨老师的个人自主行为不属于校本研修，故排除。","hint":"区分“个人自主研修”与“学校组织的校本研修”。","tags":["教师专业发展","教学反思"],"category":"教学技能与实践"},{"id":"L7-M03","source":"local","sourceLabel":"（本地：第7卷第23题）","vol":7,"no":23,"section":"多选","sectionNo":3,"type":"multi","score":4,"stem":"讲授法的主要缺点在于（  ）","options":["过分强调教师的主导作用，忽视学生的主体地位","启发了学生的思维和想象","面向全体学生，无法照顾学生的个别差异","不利于学生解决问题能力的提升"],"answer":["A","C","D"],"analysis":"讲授法的局限：过分强调教师主导忽视学生主体、面向全体难以照顾个别差异、不利于解决问题能力培养，A、C、D正确。B“启发学生的思维和想象”是优点而非缺点，与题干“缺点”不符，故排除。","hint":"题干问“缺点”，要排除描述优点的选项。","tags":["教学方法","讲授法"],"category":"教育学原理"},{"id":"L7-M04","source":"local","sourceLabel":"（本地：第7卷第24题）","vol":7,"no":24,"section":"多选","sectionNo":4,"type":"multi","score":4,"stem":"以下关于课堂导入的说法，恰当的（  ）","options":["课堂导入没有固定的格式和方法","要以学生为中心","要紧扣教学目标","课堂导入是课堂教学中的重要的一环"],"answer":["A","B","C","D"],"analysis":"课堂导入没有固定模式，应灵活处理；要以学生为中心；要紧扣教学目标；导入是课堂教学的重要环节，四项说法均恰当。","hint":"导入原则：形式灵活、学生中心、紧扣目标。","tags":["教学技能","课堂导入"],"category":"教学技能与实践"},{"id":"L7-M05","source":"local","sourceLabel":"（本地：第7卷第25题）","vol":7,"no":25,"section":"多选","sectionNo":5,"type":"multi","score":4,"stem":"子曰:“学而不思则罔①，思而不学则殆②。”(《论语·为政》)【注释】①罔:迷惑、糊涂。②殆:疑惑、危险。下列对孔子这段话的理解，正确的一项是（  ）。","options":["在孔子看来，学和思二者不能偏废，主张学与思相结合","孔子指出了学而不思的局限，也道出了思而不学的弊端","光学习不思考会越学越危险，光思考不学习会越来越糊涂","孔子学与思相结合的思想，在今天仍有其值得肯定的价值"],"answer":["A","B","D"],"analysis":"孔子主张学与思不可偏废，A、D正确；并指出学而不思与思而不学各有弊端，B正确。C错误：按注释“罔”是迷惑糊涂（对应学而不思），“殆”是疑惑危险（对应思而不学），C把二者说反。","hint":"罔=迷惑，殆=危险，C把对应关系说反了。","tags":["教育史","孔子"],"category":"教育学原理"},{"id":"L7-M06","source":"local","sourceLabel":"（本地：第7卷第26题）","vol":7,"no":26,"section":"多选","sectionNo":6,"type":"multi","score":4,"stem":"根据“以人为本”的学生观，下列哪些说法是正确的？（  ）","options":["学生的身心发展是有规律的","每个学生都有自身的独特性","学生是以老师的意志为转移的客观存在","学生是处于发展过程中的人"],"answer":["A","B","D"],"analysis":"“以人为本”的学生观认为：学生身心发展有规律、每个学生都有独特性、学生是处于发展过程中的人。C把学生当作以教师意志为转移的存在，违背学生观，故排除。","hint":"学生是独立意义的人，不是被动接受者。","tags":["学生观","以人为本"],"category":"教育学原理"},{"id":"L7-M07","source":"local","sourceLabel":"（本地：第7卷第27题）","vol":7,"no":27,"section":"多选","sectionNo":7,"type":"multi","score":4,"stem":"牛老师在班级管理中采取了一系列措施，其中不正确的是（  ）。","options":["鼓励学习能力强的学生主动帮助学困生","编排座位时让学生按成绩排名自己选择","有学生丢失东西时马上检查全班学生的书包","私下告知无记名投票选的“最差生”并提出要求"],"answer":["B","C","D"],"analysis":"题干问“不正确”：B按成绩排名自选座位带有歧视性，C搜查全班书包侵犯学生隐私权，D公布无记名投票的“最差生”伤害学生人格尊严，均不正确。A鼓励优生帮助学困生是正确的，故排除。","hint":"歧视性、侵权性、伤害自尊的做法都不正确。","tags":["班级管理","班主任工作"],"category":"教学技能与实践"},{"id":"L7-M08","source":"local","sourceLabel":"（本地：第7卷第28题）","vol":7,"no":28,"section":"多选","sectionNo":8,"type":"multi","score":4,"stem":"教师成长和发展的基本途径有哪些？（  ）","options":["开展微格教学","提高课后作业的数量","反思自己的教学经验","观摩和分析优秀教师的教学活动"],"answer":["A","C","D"],"analysis":"教师成长与发展的基本途径包括开展微格教学、反思自己的教学经验、观摩和分析优秀教师的教学活动。B提高课后作业数量与教师成长无直接关系，故排除。","hint":"成长三途径：微格教学、反思、观摩优秀教师。","tags":["教师专业发展","成长途径"],"category":"教学技能与实践"},{"id":"L7-M09","source":"local","sourceLabel":"（本地：第7卷第29题）","vol":7,"no":29,"section":"多选","sectionNo":9,"type":"multi","score":4,"stem":"探究性学习的优势主要表现在（  ）","options":["可以增强学生与他人一起解决现实生活中问题的意愿","可以使学生更为深入地理解所获得的知识和技能，增强思维能力、操作能力","耗时较短，教学效率相对较高","能够拓展学生的学科视野，便于学生掌握完全的知识"],"answer":["A","B","D"],"analysis":"探究性学习的优势包括增强协作解决现实问题的意愿、深化对知识技能的理解并提升思维与操作能力、拓展学科视野。C“耗时较短、教学效率相对较高”恰恰是探究学习的短板而非优势，故排除。","hint":"探究学习投入时间较长，说它“省时高效”的是错误项。","tags":["学习方式","探究性学习"],"category":"教学技能与实践"},{"id":"L7-M10","source":"local","sourceLabel":"（本地：第7卷第30题）","vol":7,"no":30,"section":"多选","sectionNo":10,"type":"multi","score":4,"stem":"终身教育是贯穿于人的一生的教育，终身教育的特点包括什么?（  ）","options":["终身性","全民性","广泛性","灵活性和实用性"],"answer":["A","B","C","D"],"analysis":"终身教育的特点包括终身性（贯穿一生）、全民性（面向所有人）、广泛性（内容与形式多样）、灵活性和实用性，四项均正确。","hint":"四特点：终身、全民、广泛、灵活实用。","tags":["教育思潮","终身教育"],"category":"教育学原理"},{"id":"L8-S01","source":"local","sourceLabel":"（本地：第8卷第1题）","vol":8,"no":1,"section":"单选","sectionNo":1,"type":"single","score":3,"stem":"以下哪个观点不属于教育内容的特点?（  ）","options":["教育内容具有科学性","教育内容具有系统性","教育内容具有针对性","教育内容具有娱乐性"],"answer":["D"],"analysis":"教育内容具有科学性（符合科学规律）、系统性（按学科逻辑编排）、针对性（针对培养目标与学生实际），思想性与发展性也是其特征；娱乐性不是教育内容的特点，故D不属于。","hint":"教育内容讲究科学、系统和有目标，不以娱乐为目的。","tags":["教育内容","教学理论"],"category":"教育学原理"},{"id":"L8-S02","source":"local","sourceLabel":"（本地：第8卷第2题）","vol":8,"no":2,"section":"单选","sectionNo":2,"type":"single","score":3,"stem":"学校教育制度一般是指一个国家的（  ）","options":["各级各类学校内部的各种制度","各级各类学校的领导管理体制","各级各类学校的总体系","各级各类学校的办学体制"],"answer":["C"],"analysis":"学校教育制度（学制）是一个国家各级各类学校的总体系，规定学校的性质、任务、入学条件、修业年限及其衔接关系。A、B、D只涉及学校内部某一方面的制度，范围过窄。","hint":"学制是国家层面学校系统的总框架，选范围最大的。","tags":["教育制度","学制"],"category":"教育学原理"},{"id":"L8-S03","source":"local","sourceLabel":"（本地：第8卷第3题）","vol":8,"no":3,"section":"单选","sectionNo":3,"type":"single","score":3,"stem":"新学期开始，王老师为了更好地因材施教，对学生的知识水平和能力进行测试，这种评价方式属于（  ）。","options":["诊断性评价","形成性评价","总结性评价","相对性评价"],"answer":["A"],"analysis":"新学期开始为因材施教而测试学生知识水平与能力，目的是摸清基础，属诊断性评价。形成性评价在教学过程中进行，总结性评价在教学结束后作结论，相对性评价依据群体内相对位置。","hint":"教学前摸底=诊断性评价。","tags":["教学评价","诊断性评价"],"category":"教学技能与实践"},{"id":"L8-S04","source":"local","sourceLabel":"（本地：第8卷第4题）","vol":8,"no":4,"section":"单选","sectionNo":4,"type":"single","score":3,"stem":"教师:“面粉可以做什么？”学生甲:“可以做面包、蛋糕、馒头、花卷、油条、面条。”学生乙:“可以做馒头、调磁针水、捏面人。”上述对话说明学生乙比学生甲的思维更具有（  ）。","options":["精细性","流畅性","变通性","反思性"],"answer":["C"],"analysis":"变通性指能突破类别限制、灵活转换思考方向。乙的答案跨越食品、物理小实验、手工造型等不同类别，体现变通性；甲的多个答案都属食品类，只体现流畅性。","hint":"跨类别、换方向=变通性；同类数量多=流畅性。","tags":["思维品质","创造性思维","变通性"],"category":"教育心理"},{"id":"L8-S05","source":"local","sourceLabel":"（本地：第8卷第5题）","vol":8,"no":5,"section":"单选","sectionNo":5,"type":"single","score":3,"stem":"美国心理学家布鲁姆提出了教育目标分类理论，把教育目标分为（  ）。","options":["总体目标、阶段目标、具体目标","德育目标、智育目标、体育目标","国家目标、学校目标、个人目标","认知目标、情感目标、动作技能目标"],"answer":["D"],"analysis":"布鲁姆把教育目标分为认知、情感、动作技能三大领域，每个领域再分层次。A是目标层次划分，B是按德智体的分类，C是按教育层级划分，都不是布鲁姆的分类。","hint":"布鲁姆三领域：认知、情感、动作技能。","tags":["布鲁姆","教育目标分类"],"category":"教育心理"},{"id":"L8-S06","source":"local","sourceLabel":"（本地：第8卷第6题）","vol":8,"no":6,"section":"单选","sectionNo":6,"type":"single","score":3,"stem":"小度认为服从、听话的孩子就是好孩子，于是她对老师和家长绝对遵从，期望得到他们的赞许。根据科尔伯格的道德发展理论，她的道德发展处于（  ）","options":["社会契约取向阶段","相对功利取向阶段","寻求认可取向阶段","遵守法规取向阶段"],"answer":["C"],"analysis":"“服从听话就是好孩子”、期望得到赞许，属科尔伯格习俗水平的寻求认可取向。相对功利取向属前习俗水平，遵守法规取向强调维护秩序，社会契约取向属后习俗水平。","hint":"“好孩子”“期望赞许”=寻求认可取向。","tags":["科尔伯格","道德发展阶段"],"category":"教育心理"},{"id":"L8-S07","source":"local","sourceLabel":"（本地：第8卷第7题）","vol":8,"no":7,"section":"单选","sectionNo":7,"type":"single","score":3,"stem":"方华情绪兴奋快而强，容易冲动，常常是爆发式的，并伴随有明显外部表现。她的气质类型属于（  ）。","options":["胆汁质","多血质","粘液质","抑郁质"],"answer":["A"],"analysis":"情绪兴奋快而强、容易冲动、爆发式且外部表现明显，是胆汁质的典型特征。多血质活泼灵活，粘液质沉稳迟缓，抑郁质敏感内向。","hint":"急躁冲动、爆发式=胆汁质。","tags":["气质","胆汁质"],"category":"教育心理"},{"id":"L8-S08","source":"local","sourceLabel":"（本地：第8卷第8题）","vol":8,"no":8,"section":"单选","sectionNo":8,"type":"single","score":3,"stem":"晓军上中学后，自尊心越来越强，自我评价越来越客观、全面，自我控制能力明显提高。这反映的是晓军自我意识哪一方面的发展？（  ）","options":["生理自我","心理自我","社会自我","物质自我"],"answer":["B"],"analysis":"自尊心、自我评价、自我控制属于个体对自身心理特征的认识与调控，即心理自我的发展。生理自我是对身体外貌的意识，社会自我是对人际角色与社会地位的认识。","hint":"自尊、自我评价、自控=心理层面的自我。","tags":["自我意识","心理自我"],"category":"教育心理"},{"id":"L8-S09","source":"local","sourceLabel":"（本地：第8卷第9题）","vol":8,"no":9,"section":"单选","sectionNo":9,"type":"single","score":3,"stem":"“学习过程就是尝试错误的过程”，这一观点属于哪种学习理论？（  ）","options":["行为主义","认知主义","人本主义","建构主义"],"answer":["A"],"analysis":"桑代克认为学习是“尝试—错误”的过程（试误说），属行为主义联结理论。认知主义强调内部认知结构，人本主义强调自我实现，建构主义强调主动建构意义。","hint":"“尝试错误”=桑代克试误说=行为主义。","tags":["学习理论","行为主义"],"category":"教育心理"},{"id":"L8-S10","source":"local","sourceLabel":"（本地：第8卷第10题）","vol":8,"no":10,"section":"单选","sectionNo":10,"type":"single","score":3,"stem":"以下哪个观点不属于教学评价的特点?（  ）","options":["客观性","科学性","全面性","主观性"],"answer":["D"],"analysis":"教学评价具有客观性（以事实为依据）、科学性（方法与标准科学）、全面性（多方面收集信息）。主观性与评价的基本要求相悖，故D不属于教学评价的特点。","hint":"评价要讲客观，排除“主观性”。","tags":["教学评价","评价特点"],"category":"教学技能与实践"},{"id":"L8-S11","source":"local","sourceLabel":"（本地：第8卷第11题）","vol":8,"no":11,"section":"单选","sectionNo":11,"type":"single","score":3,"stem":"刘老师在课余时间经常去学生家里进行家访，让家长更好地了解学生的在校学习情况，并且也会向家长询问学生的性格和兴趣爱好，以根据学生的性格和兴趣爱好因材施教。这体现了刘老师注重学生个体身心发展的（  ）。","options":["顺序性","阶段性","不平衡性","个体差异性"],"answer":["D"],"analysis":"家访了解学生性格与兴趣爱好并据此因材施教，体现对个体差异性的关注。顺序性强调发展次序，阶段性强调年龄特征，不平衡性强调速度不均。","hint":"因人而异、因材施教=个体差异性。","tags":["身心发展规律","个别差异性"],"category":"教育学原理"},{"id":"L8-S12","source":"local","sourceLabel":"（本地：第8卷第12题）","vol":8,"no":12,"section":"单选","sectionNo":12,"type":"single","score":3,"stem":"2015年修正的《中华人民共和国教育法》中明确规定，我国教育的性质和方向是（  ）","options":["教育必须为社会主义现代化建设服务，为社会生活服务","教育必须为社会主义现代化建设服务，为人民服务","教育必须为社会主义物质文明建设服务，为精神文明建设服务","教育必须为社会主义建设服务，为人的发展服务"],"answer":["B"],"analysis":"2015年修正的《教育法》规定：教育必须为社会主义现代化建设服务、为人民服务。A、C、D均不是现行法条的准确表述。","hint":"记住“两个服务”：为现代化建设服务、为人民服务。","tags":["教育法律法规","教育法"],"category":"教育法律法规"},{"id":"L8-S13","source":"local","sourceLabel":"（本地：第8卷第13题）","vol":8,"no":13,"section":"单选","sectionNo":13,"type":"single","score":3,"stem":"人的心理机能遵循从简单到复杂，从低级到高级的发展过程，如从无意注意到有意注意，从形象思维到抽象思维，这反映了人身心发展特征的（  ）。","options":["互补性","顺序性","差异性","不平衡性"],"answer":["B"],"analysis":"心理机能从简单到复杂、从低级到高级、从无意注意到有意注意，体现的是身心发展的顺序性。互补性强调身心机能相互补偿，差异性强调人与人不同，不平衡性强调速度不均。","hint":"“由低级到高级、由简到繁”=顺序性。","tags":["身心发展规律","顺序性"],"category":"教育学原理"},{"id":"L8-S14","source":"local","sourceLabel":"（本地：第8卷第14题）","vol":8,"no":14,"section":"单选","sectionNo":14,"type":"single","score":3,"stem":"某年疫情期间，某民办学校王老师没有报备批准就自行前往疫情严重的国家旅游，造成严重后果。学校决定解除王老师的聘任合同。依据《中小学教师违反职业道德行为处理办法》，下列说法不正确的是（  ）。","options":["学校在处理决定前应当听取王老师的申辩","学校在处理决定前应当听取家长委员会的意见","学校在处理决定前应当报请主管教育部门批准","学校在处理决定前应当准许王老师举行听证的请求"],"answer":["C"],"analysis":"依《中小学教师违反职业道德行为处理办法》，处理前应听取申辩、可听取家长委员会意见、符合条件的应准许听证；学校解除聘任合同无需事先报请主管教育部门批准，故C不正确。","hint":"程序公正靠申辩与听证，不要求事前审批。","tags":["教育法律法规","教师违反职业道德处理办法"],"category":"教育法律法规"},{"id":"L8-S15","source":"local","sourceLabel":"（本地：第8卷第15题）","vol":8,"no":15,"section":"单选","sectionNo":15,"type":"single","score":3,"stem":"开学了，为把素质教育落到实处，某中学语文老师为同学们确定了学期素质教育目标:“每个月读一本名著，识两位名人，听三首名曲，品四幅名画，背五首古诗。”该教师的做法（  ）。","options":["干扰了学生学习的节奏","优化了学生学习的方法","窄化了素质教育的内涵","指明了素质教育的途径"],"answer":["C"],"analysis":"把素质教育简化为“读名著、识名人、听名曲、品名画、背古诗”的量化指标，只抓了文化素养的局部，窄化了素质教育的内涵。素质教育强调德智体美劳全面发展与个性发展的统一。","hint":"把丰富内涵压缩成几条清单=窄化。","tags":["素质教育"],"category":"教育学原理"},{"id":"L8-S16","source":"local","sourceLabel":"（本地：第8卷第16题）","vol":8,"no":16,"section":"单选","sectionNo":16,"type":"single","score":3,"stem":"美国学者孟禄根据原始社会没有学校、没有教师、没有教材的事实，断言教育起源于儿童对成人无意识的模仿。这种观点被称为（  ）。","options":["生物起源论","交往起源论","心理起源论","劳动起源论"],"answer":["C"],"analysis":"孟禄认为教育起源于儿童对成人行为的无意识模仿，属心理起源论。生物起源论以利托尔诺、沛西能为代表，劳动起源论是马克思主义的观点，交往起源论不是主流提法。","hint":"孟禄—无意识模仿—心理起源论。","tags":["教育起源","心理起源论"],"category":"教育学原理"},{"id":"L8-S17","source":"local","sourceLabel":"（本地：第8卷第17题）","vol":8,"no":17,"section":"单选","sectionNo":17,"type":"single","score":3,"stem":"当前我国中学开设的数学、语文、英语等课程属于（  ）","options":["学科课程","活动课程","经验课程","社会课程"],"answer":["A"],"analysis":"数学、语文、英语按学科知识体系设置，属学科课程（分科课程）。活动课程与经验课程以儿童直接经验为中心，社会课程以社会问题为中心组织内容。","hint":"按学科门类设置=学科课程。","tags":["课程类型","学科课程"],"category":"教育学原理"},{"id":"L8-S18","source":"local","sourceLabel":"（本地：第8卷第18题）","vol":8,"no":18,"section":"单选","sectionNo":18,"type":"single","score":3,"stem":"皮格马利翁效应的主要启示是，教师对学生应该（  ）","options":["鼓励合作学习","给予积极期望","提出纪律要求","引导发现学习"],"answer":["B"],"analysis":"皮格马利翁效应即教师期望效应，指教师的积极期望会潜移默化地提高学生表现，启示教师对学生给予积极期望。鼓励合作、提出纪律要求、引导发现学习都不是该效应的核心。","hint":"皮格马利翁=期望效应=给学生积极期望。","tags":["教师心理","期望效应"],"category":"教育学原理"},{"id":"L8-S19","source":"local","sourceLabel":"（本地：第8卷第19题）","vol":8,"no":19,"section":"单选","sectionNo":19,"type":"single","score":3,"stem":"苏联教育家赞可夫倡导的是（  ）","options":["发现学习理论","教学过程最优化理论","教学与发展理论","范例教学理论"],"answer":["C"],"analysis":"赞可夫提出发展性教学理论（教学与发展）。发现学习理论由布鲁纳提出，教学过程最优化理论由巴班斯基提出，范例教学理论由瓦·根舍因提出。","hint":"赞可夫=发展性教学理论。","tags":["教育家","赞可夫"],"category":"教育学原理"},{"id":"L8-S20","source":"local","sourceLabel":"（本地：第8卷第20题）","vol":8,"no":20,"section":"单选","sectionNo":20,"type":"single","score":3,"stem":"王老师在教学工作中善于采用各种教学策略，取得了很好的教学效果。这反映了王老师的哪一方面能力突出？（  ）","options":["教学操作","教学归因","教学迁移","教学反思"],"answer":["A"],"analysis":"善于采用各种教学策略并取得良好效果，是课堂组织实施层面的能力，即教学操作能力。教学归因是对成败原因的解释，教学迁移是经验迁移，教学反思是事后回溯改进。","hint":"课堂上实际“做”出来的能力=教学操作能力。","tags":["教师能力","教学操作能力"],"category":"教学技能与实践"},{"id":"L8-M01","source":"local","sourceLabel":"（本地：第8卷第21题）","vol":8,"no":21,"section":"多选","sectionNo":1,"type":"multi","score":4,"stem":"以下哪个观点属于教育的基本功能?（  ）","options":["教育具有选择功能","教育具有传承功能","教育具有发展功能","教育具有消费功能"],"answer":["A","B","C"],"analysis":"教育的基本功能包括选择功能、传承功能、发展功能（促进个体与社会发展）。D“消费功能”不是教育的基本功能，故排除。","hint":"教育的基本功能围绕选择、传承、发展。","tags":["教育功能"],"category":"教育学原理"},{"id":"L8-M02","source":"local","sourceLabel":"（本地：第8卷第22题）","vol":8,"no":22,"section":"多选","sectionNo":2,"type":"multi","score":4,"stem":"以下哪个观点属于教育与学生发展的关系?（  ）","options":["教育具有促进个体发展功能","教育具有促进群体发展功能","教育具有促进社会发展功能","教育具有促进教师发展功能"],"answer":["A","B","C"],"analysis":"题干限定“教育与学生发展的关系”：教育具有促进个体发展、促进群体发展、促进社会发展的功能，A、B、C正确。D“促进教师发展”不属于教育与学生发展关系的范畴，故排除。","hint":"看清限定语“与学生发展的关系”，排除与教师有关的选项。","tags":["教育功能","个体发展"],"category":"教育学原理"},{"id":"L8-M03","source":"local","sourceLabel":"（本地：第8卷第23题）","vol":8,"no":23,"section":"多选","sectionNo":3,"type":"multi","score":4,"stem":"课堂教学反馈的特点表现为（  ）","options":["多样性","思辨性","评议性","差异性"],"answer":["A","B","C","D"],"analysis":"课堂教学反馈具有多样性、思辨性、评议性、差异性，四项均为其特征。","hint":"反馈四特点：多样、思辨、评议、差异。","tags":["教学技能","课堂反馈"],"category":"教学技能与实践"},{"id":"L8-M04","source":"local","sourceLabel":"（本地：第8卷第24题）","vol":8,"no":24,"section":"多选","sectionNo":4,"type":"multi","score":4,"stem":"教师在设计课堂导入时的“三宜”是指（  ）","options":["宜灵活多变","宜简洁明快","宜细致详尽","宜回归本真"],"answer":["A","B","D"],"analysis":"课堂导入的“三宜”为宜灵活多变、宜简洁明快、宜回归本真。C“宜细致详尽”与导入应简明扼要的要求相悖，故排除。","hint":"导入要简洁明快，排除“细致详尽”。","tags":["教学技能","课堂导入"],"category":"教学技能与实践"},{"id":"L8-M05","source":"local","sourceLabel":"（本地：第8卷第25题）","vol":8,"no":25,"section":"多选","sectionNo":5,"type":"multi","score":4,"stem":"“五岳”是我国的五大名山，下列属于“五岳”的是（  ）。","options":["泰山","华山","黄山","衡山"],"answer":["A","B","D"],"analysis":"“五岳”指东岳泰山、西岳华山、南岳衡山、北岳恒山、中岳嵩山，A、B、D属于五岳；黄山不在五岳之列，故排除C。","hint":"五岳：泰山、华山、衡山、恒山、嵩山。","tags":["文化常识","地理"],"category":"文化素养"},{"id":"L8-M06","source":"local","sourceLabel":"（本地：第8卷第26题）","vol":8,"no":26,"section":"多选","sectionNo":6,"type":"multi","score":4,"stem":"根据皮亚杰的认知发展理论，具体运算阶段具备哪些思维特点？（  ）","options":["“泛灵性”，认为外界的一切事物都是有生命的","拥有守恒的概念","思维能够前推也能后退，具备可逆性","能够进行简单的抽象思维，但需要具体事物的支持"],"answer":["B","C","D"],"analysis":"具体运算阶段的特点包括获得守恒概念、思维可逆、能进行需具体事物支持的简单抽象思维。A“泛灵性”属前运算阶段，故排除。","hint":"泛灵论属前运算阶段，不在具体运算阶段。","tags":["皮亚杰","具体运算"],"category":"教育心理"},{"id":"L8-M07","source":"local","sourceLabel":"（本地：第8卷第27题）","vol":8,"no":27,"section":"多选","sectionNo":7,"type":"multi","score":4,"stem":"下列关于教师与学生之间法律关系的说法，正确的是（  ）。","options":["教育与被教育的关系","管理与被管理的关系","保护与被保护的关系","控制与被控制的关系"],"answer":["A","B","C"],"analysis":"师生法律关系包括教育与被教育、管理与被管理、保护与被保护。D“控制与被控制”不是规范的法律关系表述，师生在法律上地位平等，故排除。","hint":"排除“控制”这类不规范表述。","tags":["教育法律法规","师生关系"],"category":"教育法律法规"},{"id":"L8-M08","source":"local","sourceLabel":"（本地：第8卷第28题）","vol":8,"no":28,"section":"多选","sectionNo":8,"type":"multi","score":4,"stem":"学习迁移指一种学习对另一种学习的影响，以下哪些教学行为可以促进学习迁移？（  ）","options":["精选教材","合理编排教学内容","教授学习策略，提高迁移意识性","合理安排教学程序"],"answer":["A","B","C","D"],"analysis":"促进学习迁移的教学策略包括精选教材、合理编排教学内容、教授学习策略提高迁移意识、合理安排教学程序，四项均有效。","hint":"促进迁移四招：精选教材、合理编排、教授策略、安排程序。","tags":["学习迁移"],"category":"教育心理"},{"id":"L8-M09","source":"local","sourceLabel":"（本地：第8卷第29题）","vol":8,"no":29,"section":"多选","sectionNo":9,"type":"multi","score":4,"stem":"以下哪些属于教学评价的特点?（  ）","options":["客观性","科学性","全面性","主观性"],"answer":["A","B","C"],"analysis":"教学评价具有客观性、科学性、全面性。D“主观性”与评价的基本要求相悖，故排除。","hint":"评价要客观，排除“主观性”。","tags":["教学评价","评价特点"],"category":"教学技能与实践"},{"id":"L8-M10","source":"local","sourceLabel":"（本地：第8卷第30题）","vol":8,"no":30,"section":"多选","sectionNo":10,"type":"multi","score":4,"stem":"以下关于问题导入形式的说法，正确的是（  ）","options":["可以单刀直入，直接提出问题","可以从侧面提问设置悬疑","只能由教师提问","可以由“谜语”等形式来呈现"],"answer":["A","B","D"],"analysis":"问题导入可直接提问、可从侧面设悬疑、可借谜语等形式，形式灵活。C“只能由教师提问”过于绝对，学生也可提出疑问，故排除。","hint":"见到“只能”这类绝对表述，优先排除。","tags":["教学技能","课堂导入"],"category":"教学技能与实践"},{"id":"L9-S01","source":"local","sourceLabel":"（本地：第9卷第1题）","vol":9,"no":1,"section":"单选","sectionNo":1,"type":"single","score":3,"stem":"李老师在教研活动中分享:“我常反思自己的教学内容是否贴近学生生活，教学方式是否易于学生理解。”这体现李老师处于教师专业发展的哪一阶段？（  ）","options":["任务关注阶段","自我更新关注阶段","虚拟关注阶段","生存关注阶段"],"answer":["B"],"analysis":"自我更新关注阶段的教师已超越生存适应，主动反思教学内容与方法、关注学生理解与自身持续改进。生存关注阶段担心能否站稳讲台，任务关注阶段聚焦完成教学任务，虚拟关注阶段是职前师范生的想象性关注。","hint":"反思教学、关注学生是否理解=自我更新关注阶段。","tags":["教师专业发展","关注阶段"],"category":"教学技能与实践"},{"id":"L9-S02","source":"local","sourceLabel":"（本地：第9卷第2题）","vol":9,"no":2,"section":"单选","sectionNo":2,"type":"single","score":3,"stem":"在科学课上，张老师通过展示“橡皮泥变形”与“纸张燃烧”两个现象，引导学生区分物理变化与化学变化。这种教学方法属于（  ）。","options":["演示法","实验法","练习法","参观法"],"answer":["A"],"analysis":"教师展示橡皮泥变形与纸张燃烧，学生观察后区分物理变化与化学变化，属演示法。实验法是学生自己动手操作，练习法是反复操练，参观法是组织实地观察。","hint":"老师做给学生看=演示法。","tags":["教学方法","演示法"],"category":"教育学原理"},{"id":"L9-S03","source":"local","sourceLabel":"（本地：第9卷第3题）","vol":9,"no":3,"section":"单选","sectionNo":3,"type":"single","score":3,"stem":"“以情动人、以理服人、以行导人、以恒育人”这种德育方式，主要体现了德育过程的哪一特点？（  ）","options":["德育过程是组织学生活动与交往的过程","德育过程是长期、反复、渐进的过程","德育过程是促进学生思想内部矛盾斗争的过程","德育过程是知、情、意、行多方面培养的过程，具有多种开端"],"answer":["D"],"analysis":"“以情动人、以理服人、以行导人、以恒育人”分别对应情、知、行、意，说明德育过程是知、情、意、行多方面培养提高的过程，且可以从不同方面开端。A强调活动交往，B强调长期反复，C强调内部矛盾斗争。","hint":"情、理、行、恒四字对应情、知、行、意，即“多种开端”。","tags":["德育过程","知情意行"],"category":"教育学原理"},{"id":"L9-S04","source":"local","sourceLabel":"（本地：第9卷第4题）","vol":9,"no":4,"section":"单选","sectionNo":4,"type":"single","score":3,"stem":"形式教育论与实质教育论之争，主要分歧在于（  ）。","options":["理论教学与实践教学孰轻孰重","直接经验与间接经验哪个更重要","教育应重知识传授还是能力培养","学科课程与活动课程如何选择"],"answer":["C"],"analysis":"形式教育论主张训练能力，实质教育论主张传授实用知识，二者之争的实质是重知识传授还是重能力培养。A是理论与实践之争，B是直接经验与间接经验之争，D是课程类型之争。","hint":"形式=能力，实质=知识。","tags":["教学理论","形式教育论"],"category":"教育学原理"},{"id":"L9-S05","source":"local","sourceLabel":"（本地：第9卷第5题）","vol":9,"no":5,"section":"单选","sectionNo":5,"type":"single","score":3,"stem":"刘老师根据学生数学期中成绩，将学生分为三个层次，并设计差异化的练习与辅导方案。这种做法主要体现对学生哪一发展特点的关注？（  ）","options":["个体差异性","未完成性","发展阶段论","发展不平衡性"],"answer":["A"],"analysis":"按成绩分层并设计差异化练习与辅导，体现对学生个体差异性的关注。未完成性、发展阶段论不是规范表述，不平衡性指同一方面或不同方面发展速度不均。","hint":"分层教学、差异化辅导=个体差异性。","tags":["身心发展规律","个别差异性"],"category":"教育学原理"},{"id":"L9-S06","source":"local","sourceLabel":"（本地：第9卷第6题）","vol":9,"no":6,"section":"单选","sectionNo":6,"type":"single","score":3,"stem":"有学者指出，教育投入不仅是消费，更是能带来回报的生产性投资。这主要体现教育的（  ）。","options":["政治功能","生态功能","文化功能","经济功能"],"answer":["D"],"analysis":"把教育投入看成能带来回报的生产性投资，体现教育的经济功能。政治功能指向政权与民主，文化功能指向文化传承，生态功能指向人与自然。","hint":"“投入—回报”是经济视角。","tags":["教育功能","经济功能"],"category":"教育学原理"},{"id":"L9-S07","source":"local","sourceLabel":"（本地：第9卷第7题）","vol":9,"no":7,"section":"单选","sectionNo":7,"type":"single","score":3,"stem":"小琳在听课过程中，将老师讲解的重点内容用自己的语言重新整理并记录笔记，以加深理解。她使用的学习策略是（  ）。","options":["复述策略","计划策略","精加工策略","组织策略"],"answer":["C"],"analysis":"把老师讲的内容用自己的语言重新整理并记录，属于对信息进行深层加工的精加工策略。复述策略是简单重复，计划策略属元认知的事前安排，组织策略是归类列提纲。","hint":"用自己的话重新加工=精加工策略。","tags":["学习策略","精加工策略"],"category":"教育心理"},{"id":"L9-S08","source":"local","sourceLabel":"（本地：第9卷第8题）","vol":9,"no":8,"section":"单选","sectionNo":8,"type":"single","score":3,"stem":"下列选项中，与“汉服——服饰”的逻辑关系一致的是（  ）。","options":["布鞋——布包","果汁——饮品","数学——理学","帽子——手套"],"answer":["B"],"analysis":"“汉服——服饰”是具体事物与其所属大类的种属关系；“果汁——饮品”同样是种属关系。A布鞋与布包、D帽子与手套是并列关系，C数学与理学是学科与其门类的层级关系，与题干关系不一致。","hint":"找“某物是某大类中的一种”的种属关系。","tags":["逻辑推理","概念关系"],"category":"文化素养"},{"id":"L9-S09","source":"local","sourceLabel":"（本地：第9卷第9题）","vol":9,"no":9,"section":"单选","sectionNo":9,"type":"single","score":3,"stem":"陈老师在设计教学目标时，既考虑学生现有水平，也预估其在教师引导下可能达到的水平。这两种水平之间的差异，维果斯基称之为（  ）。","options":["教学支架","先行组织者","最近发展区","自我差异性"],"answer":["C"],"analysis":"维果斯基把学生现有水平与在教师引导下可能达到的水平之间的差距称为最近发展区。教学支架是帮助学生跨越该区域的手段，先行组织者是奥苏贝尔提出的概念。","hint":"“现有水平”与“可能达到的水平”之差=最近发展区。","tags":["维果斯基","最近发展区"],"category":"教育心理"},{"id":"L9-S10","source":"local","sourceLabel":"（本地：第9卷第10题）","vol":9,"no":10,"section":"单选","sectionNo":10,"type":"single","score":3,"stem":"某校为提高理科成绩，将劳动技术等课程课时压缩，把更多时间用于数学、物理、化学的复习。对该做法的评价正确的是（  ）。","options":["不利于学生全面发展","有助于优化学科结构","不利于教师专业成长","有利于提升学业成绩"],"answer":["A"],"analysis":"压缩劳动技术等课程课时、把时间集中于考试学科复习，违背德智体美劳全面发展的要求，不利于学生全面发展，故A评价正确。B、D肯定该做法，C谈教师专业成长，均不正确。","hint":"挤占非考试科目=违背全面发展。","tags":["素质教育","全面发展"],"category":"教育学原理"},{"id":"L9-S11","source":"local","sourceLabel":"（本地：第9卷第11题）","vol":9,"no":11,"section":"单选","sectionNo":11,"type":"single","score":3,"stem":"我国战国末期出现的（  ），被广泛认为是世界上最早系统论述教育问题的专著。","options":["《中庸》","《大学》","《论语》","《学记》"],"answer":["D"],"analysis":"《学记》出现于我国战国末期，是世界上最早系统论述教育问题的专著。《中庸》《大学》是儒家经典，《论语》是语录体，均非专门的教育理论专著。","hint":"世界最早且专门论述教育=《学记》。","tags":["教育史","《学记》"],"category":"教育学原理"},{"id":"L9-S12","source":"local","sourceLabel":"（本地：第9卷第12题）","vol":9,"no":12,"section":"单选","sectionNo":12,"type":"single","score":3,"stem":"《汉谟拉比法典》是目前保存最完整的早期成文法典之一，其原文保存于（  ）。","options":["石刻","绢帛","羊皮卷","甲骨"],"answer":["A"],"analysis":"《汉谟拉比法典》原文刻于黑色玄武岩柱之上，以石刻形式保存。绢帛、羊皮卷、甲骨都不是该法典的载体。","hint":"汉谟拉比法典=石柱石刻。","tags":["文化常识","历史"],"category":"文化素养"},{"id":"L9-S13","source":"local","sourceLabel":"（本地：第9卷第13题）","vol":9,"no":13,"section":"单选","sectionNo":13,"type":"single","score":3,"stem":"李老师常用笔记本、书签等小奖品激励学生认真完成作业，以培养良好的学习习惯。这种做法最符合（  ）的学习理论。","options":["人本主义","认知主义","行为主义","建构主义"],"answer":["C"],"analysis":"用笔记本、书签等小奖品激励学生、塑造习惯，依据行为主义的强化原理。人本主义强调自我实现，认知主义强调内部认知结构，建构主义强调主动建构意义。","hint":"奖励强化=行为主义。","tags":["学习理论","行为主义"],"category":"教育心理"},{"id":"L9-S14","source":"local","sourceLabel":"（本地：第9卷第14题）","vol":9,"no":14,"section":"单选","sectionNo":14,"type":"single","score":3,"stem":"小敏在课前预习中标记出疑难问题，上课时带着问题听讲，以增强听课的针对性。这种注意属于（  ）。","options":["无意注意","有意注意","有意后注意","无意后注意"],"answer":["B"],"analysis":"课前标记疑难、上课带着问题听讲，是有预定目的且需意志努力的注意，属有意注意。无意注意无目的不需意志，有意后注意是有目的但已不需意志努力。","hint":"带着目的、需要意志努力=有意注意。","tags":["注意","有意注意"],"category":"教育心理"},{"id":"L9-S15","source":"local","sourceLabel":"（本地：第9卷第15题）","vol":9,"no":15,"section":"单选","sectionNo":15,"type":"single","score":3,"stem":"下列概念关系中，与“医生——研究员”属于同一类型的是（  ）。","options":["排球——网球","历史书——地理书","外套——衬衫","研究生——运动员"],"answer":["D"],"analysis":"“医生——研究员”是交叉关系（两者可以重叠但不互相包含）。“研究生——运动员”同样是交叉关系；A排球与网球、B历史书与地理书、C外套与衬衫都是并列（全异）关系。","hint":"找“有重叠但互不包含”的交叉关系。","tags":["逻辑推理","概念关系"],"category":"文化素养"},{"id":"L9-S16","source":"local","sourceLabel":"（本地：第9卷第16题）","vol":9,"no":16,"section":"单选","sectionNo":16,"type":"single","score":3,"stem":"孟禄认为，教育起源于儿童对成人行为的无意识模仿。这一观点被称为（  ）。","options":["交往起源论","心理起源论","生物起源论","劳动起源论"],"answer":["B"],"analysis":"孟禄认为教育起源于儿童对成人行为的无意识模仿，属心理起源论。生物起源论以利托尔诺、沛西能为代表，劳动起源论是马克思主义的观点，交往起源论不是主流提法。","hint":"孟禄—无意识模仿—心理起源论。","tags":["教育起源","心理起源论"],"category":"教育学原理"},{"id":"L9-S17","source":"local","sourceLabel":"（本地：第9卷第17题）","vol":9,"no":17,"section":"单选","sectionNo":17,"type":"single","score":3,"stem":"小浩进入初中后，自我意识增强，能更客观地评价自己，自控能力也显著提高。这反映其（  ）的发展。","options":["心理自我","生理自我","物质自我","社会自我"],"answer":["A"],"analysis":"自我意识增强、能更客观地评价自己、自控能力提高，属于心理自我的发展。生理自我是对身体外貌的意识，社会自我是对人际角色与社会地位的认识。","hint":"客观评价自己、自控增强=心理自我。","tags":["自我意识","心理自我"],"category":"教育心理"},{"id":"L9-S18","source":"local","sourceLabel":"（本地：第9卷第18题）","vol":9,"no":18,"section":"单选","sectionNo":18,"type":"single","score":3,"stem":"小轩因月考成绩不佳，父母承诺若期末进入班级前十名就奖励学习机。为此他学习更加努力。小轩的学习动机属于（  ）。","options":["远景、内部动机","近景、内部动机","近景、外部动机","远景、外部动机"],"answer":["C"],"analysis":"期末是近期目标，属近景动机；奖励学习机是外部诱因，属外部动机。内部动机来自对学习本身的兴趣，远景动机指向长远目标与理想。","hint":"按“时间远近”和“动力内外”两个维度判断。","tags":["学习动机","动机分类"],"category":"教育心理"},{"id":"L9-S19","source":"local","sourceLabel":"（本地：第9卷第19题）","vol":9,"no":19,"section":"单选","sectionNo":19,"type":"single","score":3,"stem":"新课改背景下，许多学校采用“成长记录袋”来记录学生发展过程。这种评价属于（  ）。","options":["形成性评价","标准参照评价","终结性评价","诊断性评价"],"answer":["A"],"analysis":"成长记录袋（档案袋）收集学生学习过程中的作品与记录，用于改进学与教，属形成性评价。标准参照评价看是否达到既定标准，终结性评价在教学结束时作结论，诊断性评价在教学前摸底。","hint":"记录“过程”的评价=形成性评价。","tags":["教学评价","形成性评价"],"category":"教学技能与实践"},{"id":"L9-S20","source":"local","sourceLabel":"（本地：第9卷第20题）","vol":9,"no":20,"section":"单选","sectionNo":20,"type":"single","score":3,"stem":"“与善人交，如入芝兰之室，久而不闻其香；与恶人交，如入鲍鱼之肆，久而不闻其臭。”这句话强调（  ）对人的发展具有重要影响。","options":["主观能动性","环境","遗传","教育"],"answer":["B"],"analysis":"与善人交如入芝兰之室、与恶人交如入鲍鱼之肆，比喻交往环境对人的熏陶与改变，强调环境对人的发展的重要影响。主观能动性是内在动力，遗传是生理前提，教育是有目的的影响。","hint":"“芝兰之室”“鲍鱼之肆”都是周围环境的比喻。","tags":["影响人发展的因素","环境"],"category":"教育学原理"},{"id":"L9-M01","source":"local","sourceLabel":"（本地：第9卷第21题）","vol":9,"no":21,"section":"多选","sectionNo":1,"type":"multi","score":4,"stem":"关于课堂问题导入的形式，下列说法正确的是（  ）。","options":["必须由教师主导发起提问","可借助谜语、歌谣等趣味形式导入","可直接提出核心问题，引发思考","可设置悬念，激发学生探究兴趣"],"answer":["B","C","D"],"analysis":"课堂问题导入形式灵活：可借谜语歌谣等趣味形式、可直接提出核心问题、可设置悬念激发探究。A“必须由教师主导发起提问”过于绝对，学生也可提出问题，故排除。","hint":"见到“必须”“只能”这类绝对表述，优先排除。","tags":["教学技能","课堂导入"],"category":"教学技能与实践"},{"id":"L9-M02","source":"local","sourceLabel":"（本地：第9卷第22题）","vol":9,"no":22,"section":"多选","sectionNo":2,"type":"multi","score":4,"stem":"新教师赵老师为提高教学能力，经常研读教材教法、向老教师请教，并坚持撰写教学反思。对他的做法，下列评价正确的是（  ）。","options":["注重教学反思","注重校本培训","注重经验借鉴","注重自主学习"],"answer":["A","C","D"],"analysis":"研读教材教法、向老教师请教属于经验借鉴，坚持撰写教学反思属于反思与自主学习。B“校本培训”指学校有组织地开展的培训，赵老师的行为是个人自主行为，不属于校本培训，故排除。","hint":"区分“学校组织的培训”和“教师自主学习”。","tags":["教师专业发展","教学反思"],"category":"教学技能与实践"},{"id":"L9-M03","source":"local","sourceLabel":"（本地：第9卷第23题）","vol":9,"no":23,"section":"多选","sectionNo":3,"type":"multi","score":4,"stem":"讲授法作为一种常用教学方法，其局限性主要包括（  ）。","options":["不利于培养学生独立解决问题能力","能有效激发学生的逻辑思维","容易忽视学生主体地位","难以照顾学生个体差异"],"answer":["A","C","D"],"analysis":"讲授法的局限：不利于培养独立解决问题的能力、容易忽视学生主体地位、难以照顾学生个体差异，A、C、D正确。B“能有效激发学生的逻辑思维”讲的是优点，不是局限，故排除。","hint":"题干问“局限性”，要排除描述优点的选项。","tags":["教学方法","讲授法"],"category":"教育学原理"},{"id":"L9-M04","source":"local","sourceLabel":"（本地：第9卷第24题）","vol":9,"no":24,"section":"多选","sectionNo":4,"type":"multi","score":4,"stem":"孔子说:“学而不思则罔，思而不学则殆。”下列理解正确的是（  ）。","options":["指出学而不思与思而不学均有弊端","学思结合的理念至今仍具重要价值","只学不思会导致危险，只思不学会导致迷茫","强调学与思相辅相成"],"answer":["A","B","D"],"analysis":"孔子主张学与思不可偏废、相辅相成，A、D正确；并指出学与思脱节的弊端，B正确。C错误：按原意“罔”是迷惑糊涂（对应学而不思），“殆”是疑惑危险（对应思而不学），C把二者说反。","hint":"罔=迷惑，殆=危险，C把对应关系弄反了。","tags":["教育史","孔子"],"category":"教育学原理"},{"id":"L9-M05","source":"local","sourceLabel":"（本地：第9卷第25题）","vol":9,"no":25,"section":"多选","sectionNo":5,"type":"multi","score":4,"stem":"“以人为本”的学生观强调（  ）。","options":["学生是发展中的人","每个学生都具有独特性","学生身心发展具有规律性","学生是教师意志的被动接受者"],"answer":["A","B","C"],"analysis":"“以人为本”的学生观认为学生是发展中的人、每个学生都具有独特性、学生身心发展具有规律性。D把学生视为教师意志的被动接受者，违背学生观，故排除。","hint":"学生是独立意义的人，不是被动接受者。","tags":["学生观","以人为本"],"category":"教育学原理"},{"id":"L9-M06","source":"local","sourceLabel":"（本地：第9卷第26题）","vol":9,"no":26,"section":"多选","sectionNo":6,"type":"multi","score":4,"stem":"根据《中华人民共和国教师法》，教师有下列哪种情形，可能受到行政处分或解聘？（  ）。","options":["体罚学生，经教育不改","不积极参加学校集体活动","故意不完成教学任务，造成损失","品行不良，侮辱学生，影响恶劣"],"answer":["A","C","D"],"analysis":"《教师法》规定可给予行政处分或解聘的情形包括：体罚学生经教育不改、故意不完成教学任务造成损失、品行不良侮辱学生影响恶劣。B“不积极参加学校集体活动”不在法定情形内，故排除。","hint":"法条列了三类情形：教学任务、体罚不改、品行恶劣。","tags":["教育法律法规","教师法"],"category":"教育法律法规"},{"id":"L9-M07","source":"local","sourceLabel":"（本地：第9卷第27题）","vol":9,"no":27,"section":"多选","sectionNo":7,"type":"multi","score":4,"stem":"皮亚杰提出的认知发展阶段包括（  ）。","options":["形式运算阶段","感知运动阶段","前运算阶段","具体运算阶段"],"answer":["A","B","C","D"],"analysis":"皮亚杰把认知发展划分为感知运动阶段、前运算阶段、具体运算阶段、形式运算阶段，四项均属其阶段划分。","hint":"皮亚杰四阶段：感知运动、前运算、具体运算、形式运算。","tags":["皮亚杰","认知发展阶段"],"category":"教育心理"},{"id":"L9-M08","source":"local","sourceLabel":"（本地：第9卷第28题）","vol":9,"no":28,"section":"多选","sectionNo":8,"type":"multi","score":4,"stem":"下列教学用语中，有助于促进学生积极学习的是（  ）。","options":["“大家不妨思考一下，刚才两位同学的结论有哪些不同之处呢？”","“刚才这位同学的概括不够准确，还是我来梳理一下吧。”","“你读得很有气势，若情感再饱满些就更出色了，再试一次吧。”","“这位同学的发言没有重复前面的观点，有自己的思考，非常好。”"],"answer":["A","C","D"],"analysis":"D引导全体比较思考、C先肯定再给改进建议、A请同学思考两位同学结论的差异，都能促进积极学习。B直接否定学生并由教师包办，打击学生积极性，故排除。","hint":"排除否定学生、由教师包办的教学用语。","tags":["教学技能","教学用语"],"category":"教学技能与实践"},{"id":"L9-M09","source":"local","sourceLabel":"（本地：第9卷第29题）","vol":9,"no":29,"section":"多选","sectionNo":9,"type":"multi","score":4,"stem":"终身教育作为一种现代教育理念，其特点包括（  ）。","options":["灵活实用性","终身性","广泛性","全民性"],"answer":["A","B","C","D"],"analysis":"终身教育的特点包括灵活实用性、终身性、广泛性、全民性，四项均正确。","hint":"四特点：终身、全民、广泛、灵活实用。","tags":["教育思潮","终身教育"],"category":"教育学原理"},{"id":"L9-M10","source":"local","sourceLabel":"（本地：第9卷第30题）","vol":9,"no":30,"section":"多选","sectionNo":10,"type":"multi","score":4,"stem":"探究性学习的主要优势包括（  ）。","options":["能够拓宽学生的学科视野，帮助学生构建完整的知识体系","耗时较短，教学效率相对较高","可以增强学生与他人协作解决现实问题的意愿","可以让学生更深入地理解知识技能，增强思维与实践能力"],"answer":["A","C","D"],"analysis":"探究性学习的优势包括拓宽学科视野帮助构建完整知识体系、增强协作解决现实问题的意愿、深化理解并提升思维与实践能力。B“耗时较短、效率相对较高”恰恰是探究学习的短板而非优势，故排除。","hint":"探究学习投入时间较长，说它“省时高效”的是错误项。","tags":["学习方式","探究性学习"],"category":"教学技能与实践"},{"id":"L10-S01","source":"local","sourceLabel":"（本地：第10卷第1题）","vol":10,"no":1,"section":"单选","sectionNo":1,"type":"single","score":3,"stem":"孔子说“知之者不如好之者，好之者不如乐之者”，这更强调学习中的（  ）。","options":["外部奖赏作用","兴趣和内部动机","意志控制水平","学习策略选择"],"answer":["B"],"analysis":"“知之者不如好之者，好之者不如乐之者”说明以学习为乐的人境界最高，强调兴趣与内在的学习动力，即内部动机。外部奖赏、意志控制、学习策略都不是这句话强调的重点。","hint":"“好之”“乐之”讲的是喜欢与乐趣，属内部动机。","tags":["学习动机","内部动机"],"category":"教育心理"},{"id":"L10-S02","source":"local","sourceLabel":"（本地：第10卷第2题）","vol":10,"no":2,"section":"单选","sectionNo":2,"type":"single","score":3,"stem":"提出“教学的教育性”思想，强调教学过程同时具有教育作用的教育家是（  ）。","options":["卢梭","赫尔巴特","杜威","夸美纽斯"],"answer":["B"],"analysis":"赫尔巴特提出“教育性教学”原则，强调教学永远具有教育性，不存在无教育的教学。卢梭主张自然教育，杜威主张从做中学，夸美纽斯系统阐述班级授课制。","hint":"“教学的教育性”是赫尔巴特的标志性观点。","tags":["教育家","赫尔巴特","教学原则"],"category":"教育学原理"},{"id":"L10-S03","source":"local","sourceLabel":"（本地：第10卷第3题）","vol":10,"no":3,"section":"单选","sectionNo":3,"type":"single","score":3,"stem":"刚开始做题时，学生需要刻意集中注意；随着思路逐渐清晰，他越做越投入，几乎不再需要意志努力。这种注意属于（  ）。","options":["无意注意","有意注意","有意后注意","分散注意"],"answer":["C"],"analysis":"开始需要意志努力维持的注意是有意注意，后来熟练投入、几乎不再需要意志努力，转化为有意后注意（随意后注意）。无意注意无目的不需意志，分散注意是注意离开任务。","hint":"有目的但已不需意志努力=有意后注意。","tags":["注意","有意后注意"],"category":"教育心理"},{"id":"L10-S04","source":"local","sourceLabel":"（本地：第10卷第4题）","vol":10,"no":4,"section":"单选","sectionNo":4,"type":"single","score":3,"stem":"教师根据学生理解程度的不同，设计了分层任务。这主要体现了对学生（  ）的重视。","options":["阶段性","不平衡性","互补性","个别差异性"],"answer":["D"],"analysis":"针对学生理解程度不同设计分层任务，体现对个别差异性的重视。阶段性强调年龄特征，不平衡性强调发展速度不均，互补性强调身心机能相互补偿。","hint":"分层设计、因人而异=个别差异性。","tags":["身心发展规律","个别差异性"],"category":"教育学原理"},{"id":"L10-S05","source":"local","sourceLabel":"（本地：第10卷第5题）","vol":10,"no":5,"section":"单选","sectionNo":5,"type":"single","score":3,"stem":"学校坚持不因考试压力随意挤占体育、艺术和劳动课程时间，这主要体现了（  ）。","options":["教育公平理念","因材施教原则","全面发展教育思想","课程整合理念"],"answer":["C"],"analysis":"不因考试压力随意挤占体育、艺术和劳动课程，是坚持德智体美劳全面发展的表现，体现全面发展教育思想。教育公平强调机会均等，因材施教强调个体差异，课程整合强调内容统整。","hint":"保住音体美劳课时=全面发展。","tags":["教育目的","全面发展"],"category":"教育学原理"},{"id":"L10-S06","source":"local","sourceLabel":"（本地：第10卷第6题）","vol":10,"no":6,"section":"单选","sectionNo":6,"type":"single","score":3,"stem":"在解决同一道编程问题时，学生能够尝试多种不同思路和算法路径。这主要体现了创造性思维的（  ）。","options":["流畅性","变通性","独创性","深刻性"],"answer":["B"],"analysis":"变通性指思维能灵活转换方向、跨越不同思路寻找解法。学生尝试多种不同思路和算法路径，体现变通性；流畅性是单位时间内产生方案的数量，独创性强调新颖独特。","hint":"换思路、换路径=变通性。","tags":["思维品质","创造性思维","变通性"],"category":"教育心理"},{"id":"L10-S07","source":"local","sourceLabel":"（本地：第10卷第7题）","vol":10,"no":7,"section":"单选","sectionNo":7,"type":"single","score":3,"stem":"某教师把学生的阶段性作业、课堂回应和修正记录纳入评价，并据此连续调整后续教学重点。该做法最能体现（  ）。","options":["评价主要用于等级划分","评价主要服务于过程改进","评价主要用于学段终结判断","评价主要强调学生间横向比较"],"answer":["B"],"analysis":"把作业、课堂回应、修正记录纳入评价并据此连续调整教学重点，说明评价被用于改进教学过程，属形成性、过程性评价取向。等级划分、学段终结判断、横向比较都不符合“连续调整”的描述。","hint":"评价结果用于“调整后续教学”=服务过程改进。","tags":["教学评价","形成性评价"],"category":"教学技能与实践"},{"id":"L10-S08","source":"local","sourceLabel":"（本地：第10卷第8题）","vol":10,"no":8,"section":"单选","sectionNo":8,"type":"single","score":3,"stem":"下列做法中，最不符合实现教育目的基本要求的是（  ）。","options":["在课程实施中兼顾德智体美劳发展","将社会实践与劳动体验纳入育人过程","以统一学业表现作为学生发展的核心判断依据","在共同要求基础上关注学生主体性和个性发展"],"answer":["C"],"analysis":"实现教育目的要求德智体美劳全面发展和因材施教、关注学生主体性。C“以统一学业表现作为学生发展的核心判断依据”陷入唯分数评价，最不符合要求。A、B、D都符合全面发展与实践育人的要求。","hint":"唯分数、单一标准的选项最不符合教育目的要求。","tags":["教育目的","素质教育"],"category":"教育学原理"},{"id":"L10-S09","source":"local","sourceLabel":"（本地：第10卷第9题）","vol":10,"no":9,"section":"单选","sectionNo":9,"type":"single","score":3,"stem":"一名学生观看同伴借助数字平台完成数据处理后，也学会了相应操作。这种学习属于（  ）。","options":["观察学习","顿悟学习","接受学习","机械学习"],"answer":["A"],"analysis":"通过观察同伴操作而习得相应行为，属班杜拉的观察学习（替代学习）。顿悟学习强调突然领悟关系，接受学习强调直接接受现成结论，机械学习强调死记硬背。","hint":"看别人做然后自己会了=观察学习。","tags":["学习理论","班杜拉","观察学习"],"category":"教育心理"},{"id":"L10-S10","source":"local","sourceLabel":"（本地：第10卷第10题）","vol":10,"no":10,"section":"单选","sectionNo":10,"type":"single","score":3,"stem":"某初中生已经能够进行“如果A成立，那么B也可能成立”的假设—演绎推理。按皮亚杰的理论，他最可能处于（  ）。","options":["感知运动阶段","前运算阶段","具体运算阶段","形式运算阶段"],"answer":["D"],"analysis":"能进行“如果A成立那么B也可能成立”的假设—演绎推理，是形式运算阶段的核心特征。感知运动靠感觉动作，前运算自我中心，具体运算需具体事物支持。","hint":"假设—演绎推理=形式运算阶段。","tags":["皮亚杰","认知发展阶段","形式运算"],"category":"教育心理"},{"id":"L10-S11","source":"local","sourceLabel":"（本地：第10卷第11题）","vol":10,"no":11,"section":"单选","sectionNo":11,"type":"single","score":3,"stem":"认为教育起源于人类生产劳动和社会生活需要的观点是（  ）。","options":["生物起源论","心理起源论","劳动起源论","神话起源论"],"answer":["C"],"analysis":"认为教育起源于人类生产劳动和社会生活需要，是马克思主义的劳动起源论。生物起源论认为教育源于动物本能，心理起源论认为源于无意识模仿，神话起源论认为源于神的意志。","hint":"“生产劳动”关键词=劳动起源论。","tags":["教育起源","劳动起源论"],"category":"教育学原理"},{"id":"L10-S12","source":"local","sourceLabel":"（本地：第10卷第12题）","vol":10,"no":12,"section":"单选","sectionNo":12,"type":"single","score":3,"stem":"一名学生因为希望将来从事智能制造相关工作而更加努力学习物理和数学，这种学习动机更偏向于（  ）。","options":["近景外部动机","近景内部动机","远景外部动机","远景内部动机"],"answer":["D"],"analysis":"“将来从事智能制造相关工作”指向长远目标，属远景动机；动力来自自身职业兴趣与志向而非外部奖励，属内部动机，故为远景、内部动机。","hint":"看时间指向“将来”，看动力来自“自己的志向”。","tags":["学习动机","动机分类"],"category":"教育心理"},{"id":"L10-S13","source":"local","sourceLabel":"（本地：第10卷第13题）","vol":10,"no":13,"section":"单选","sectionNo":13,"type":"single","score":3,"stem":"学生学会骑自行车后，再学习骑电动车会更容易上手。这种现象属于（  ）。","options":["正迁移","负迁移","零迁移","倒摄抑制"],"answer":["A"],"analysis":"会骑自行车后学骑电动车更容易，是已有技能对新技能学习的促进作用，属正迁移。负迁移是干扰阻碍，零迁移是无影响，倒摄抑制是后学材料干扰先学材料的记忆。","hint":"先前经验促进后续学习=正迁移。","tags":["学习迁移","正迁移"],"category":"教育心理"},{"id":"L10-S14","source":"local","sourceLabel":"（本地：第10卷第14题）","vol":10,"no":14,"section":"单选","sectionNo":14,"type":"single","score":3,"stem":"同样一幅流程图，有的学生看到“程序步骤”，有的学生先想到“问题解决思路”。这主要体现了知觉的（  ）。","options":["选择性","恒常性","整体性","理解性"],"answer":["D"],"analysis":"同样一幅图，不同学生因已有经验不同而看出不同意义，体现知觉的理解性（以已有知识经验去理解对象）。选择性是从背景中分出对象，恒常性是条件变化时印象保持稳定，整体性是把握整体而非局部。","hint":"经验不同导致理解不同=知觉的理解性。","tags":["知觉","理解性"],"category":"教育心理"},{"id":"L10-S15","source":"local","sourceLabel":"（本地：第10卷第15题）","vol":10,"no":15,"section":"单选","sectionNo":15,"type":"single","score":3,"stem":"教师在讲授新单元前，先呈现整体知识框架，帮助学生把新知识与已有知识联系起来。这种做法更符合（  ）的学习理论。","options":["行为主义","认知主义","人本主义","联结主义"],"answer":["B"],"analysis":"讲授新单元前先呈现整体知识框架、帮助新知识与已有知识建立联系，是奥苏贝尔“先行组织者”策略，属认知主义学习理论。行为主义强调刺激反应强化，人本主义强调自我实现，联结主义同属行为取向。","hint":"强调“知识结构、已有知识联系”=认知主义。","tags":["学习理论","认知主义","先行组织者"],"category":"教育心理"},{"id":"L10-S16","source":"local","sourceLabel":"（本地：第10卷第16题）","vol":10,"no":16,"section":"单选","sectionNo":16,"type":"single","score":3,"stem":"学生不能独立完成一道题，但在教师提示和同伴帮助下能够完成。维果斯基把这两种水平之间的差距称为（  ）。","options":["认知结构","最近发展区","学习定势","观察学习"],"answer":["B"],"analysis":"维果斯基把学生独立解决问题的实际水平与在成人或同伴帮助下可能达到的水平之间的差距称为最近发展区。认知结构是已有知识的组织，学习定势是习惯化的心理准备，观察学习是班杜拉的概念。","hint":"不能独立做但在帮助下能做，这一差距=最近发展区。","tags":["维果斯基","最近发展区"],"category":"教育心理"},{"id":"L10-S17","source":"local","sourceLabel":"（本地：第10卷第17题）","vol":10,"no":17,"section":"单选","sectionNo":17,"type":"single","score":3,"stem":"《论语》中的“学而时习之，不亦说乎”对学习最直接的启示是（  ）。","options":["学习后要及时复习巩固","复习应尽量集中在考试前进行","复习次数越多，效果一定越好","已经理解的内容无需再现和巩固"],"answer":["A"],"analysis":"“学而时习之”强调学习之后要按时温习巩固，最直接的启示是及时复习。集中突击复习、复习次数越多越好、理解后无需巩固都不符合记忆规律。","hint":"“时习”=按时复习巩固。","tags":["记忆","复习策略"],"category":"教育心理"},{"id":"L10-S18","source":"local","sourceLabel":"（本地：第10卷第18题）","vol":10,"no":18,"section":"单选","sectionNo":18,"type":"single","score":3,"stem":"学生在调试程序时，一边查看代码，一边观察运行结果，并根据报错信息及时调整思路。这主要体现了注意的（  ）。","options":["稳定性","转移","广度","分配"],"answer":["D"],"analysis":"调试程序时同时关注代码与运行结果并据报错调整思路，是把注意同时分配到多个对象上，属注意的分配。稳定性是注意持久保持，转移是主动切换对象，广度是同一时间把握对象的数量。","hint":"同一时间兼顾多件事=注意的分配。","tags":["注意","注意分配"],"category":"教育心理"},{"id":"L10-S19","source":"local","sourceLabel":"（本地：第10卷第19题）","vol":10,"no":19,"section":"单选","sectionNo":19,"type":"single","score":3,"stem":"下列对“教学做合一”的理解，最符合陶行知主张的是（  ）。","options":["先由教师系统讲清知识，再安排学生练习应用","在做中学，使知识获得、实际操作和生活经验相互贯通","以训练技能为中心，理论学习可适当弱化","通过统一操作流程提高课堂效率和结果一致性"],"answer":["B"],"analysis":"陶行知主张“教学做合一”，核心是“在做中学”，使知识获得、实际操作与生活经验相互贯通。A是先讲后练的传统模式，C弱化理论、D强调统一流程都不符合其主张。","hint":"“教学做合一”的落点是“做中学”。","tags":["教育家","陶行知","教学观"],"category":"教育学原理"},{"id":"L10-S20","source":"local","sourceLabel":"（本地：第10卷第20题）","vol":10,"no":20,"section":"单选","sectionNo":20,"type":"single","score":3,"stem":"教育在传递知识经验、保存社会文化成果方面所表现出来的作用，主要属于教育的（  ）。","options":["人口功能","经济功能","生态功能","文化功能"],"answer":["D"],"analysis":"教育传递知识经验、保存社会文化成果的作用，属于教育的文化功能（文化传承）。人口功能指向人口数量与质量，经济功能指向劳动力与生产力，生态功能指向人与自然。","hint":"“传递知识、保存文化”=文化功能。","tags":["教育功能","文化功能"],"category":"教育学原理"},{"id":"L10-M01","source":"local","sourceLabel":"（本地：第10卷第21题）","vol":10,"no":21,"section":"多选","sectionNo":1,"type":"multi","score":4,"stem":"下列关于著名教育家及其主张的表述，正确的有（  ）。","options":["夸美纽斯系统阐述了班级授课制","孔子强调“不愤不启，不悱不发”","杜威主张学校教育应以教师讲授和学科体系为中心","蔡元培主张“五育并举”"],"answer":["A","B","D"],"analysis":"夸美纽斯系统阐述班级授课制、孔子强调“不愤不启，不悱不发”、蔡元培主张“五育并举”，A、B、D正确。C错误：杜威主张以儿童经验和活动为中心，反对以教师讲授和学科体系为中心。","hint":"杜威是儿童中心，说他是“教师中心”必错。","tags":["教育家","教育史"],"category":"教育学原理"},{"id":"L10-M02","source":"local","sourceLabel":"（本地：第10卷第22题）","vol":10,"no":22,"section":"多选","sectionNo":2,"type":"multi","score":4,"stem":"关于影响人发展的因素及其作用，正确的有（  ）。","options":["遗传为人的发展提供生理前提","环境对人的发展有重要影响","教育在人的发展中起主导作用","主观能动性影响发展的方向和效果"],"answer":["A","B","C","D"],"analysis":"遗传为人的发展提供生理前提，环境对人的发展有重要影响，教育在人的发展中起主导作用，个体主观能动性影响发展的方向和效果，四项表述均正确。","hint":"四因素各司其职：前提、可能、主导、决定方向。","tags":["影响人发展的因素"],"category":"教育学原理"},{"id":"L10-M03","source":"local","sourceLabel":"（本地：第10卷第23题）","vol":10,"no":23,"section":"多选","sectionNo":3,"type":"multi","score":4,"stem":"关于当前国家教育方针及实现教育目的要求的表述，正确的有（  ）。","options":["教育必须为社会主义现代化建设服务、为人民服务","教育应与生产劳动和社会实践相结合","为保证教育质量，应以智育发展作为其他各育的中心","教育应培养德智体美劳全面发展的社会主义建设者和接班人"],"answer":["A","B","D"],"analysis":"教育方针要求教育为社会主义现代化建设服务、为人民服务，与生产劳动和社会实践相结合，培养德智体美劳全面发展的建设者和接班人，A、B、D正确。C“以智育为中心”违背全面发展的要求，故错误。","hint":"把智育凌驾于各育之上的表述必错。","tags":["教育目的","教育方针","全面发展"],"category":"教育学原理"},{"id":"L10-M04","source":"local","sourceLabel":"（本地：第10卷第24题）","vol":10,"no":24,"section":"多选","sectionNo":4,"type":"multi","score":4,"stem":"在“提高课堂参与度”研究中，记录学生课堂表现，向学生发放问卷了解学习感受，并由教师在教学实践中不断调整方案。该研究主要采用了（  ）。","options":["观察法","历史法","调查法","行动研究法"],"answer":["A","C","D"],"analysis":"记录课堂表现属观察法，发放问卷了解感受属调查法，在教学实践中不断调整方案属行动研究法，A、C、D正确。历史法是通过历史文献研究过去，本案不涉及，故排除B。","hint":"三种方法分别对应“看”“问”“改”。","tags":["教育研究方法"],"category":"教学技能与实践"},{"id":"L10-M05","source":"local","sourceLabel":"（本地：第10卷第25题）","vol":10,"no":25,"section":"多选","sectionNo":5,"type":"multi","score":4,"stem":"应用记忆规律促进有效学习的做法有（  ）。","options":["及时复习","分散复习","在理解基础上识记","适度过度学习"],"answer":["A","B","C","D"],"analysis":"依据记忆规律促进学习：及时复习（防止快速遗忘）、分散复习（避免集中疲劳）、在理解基础上识记（意义识记优于机械识记）、适度过度学习（巩固保持），四项均正确。","hint":"记忆四招：及时、分散、理解、适度过度。","tags":["记忆","学习策略"],"category":"教育心理"},{"id":"L10-M06","source":"local","sourceLabel":"（本地：第10卷第26题）","vol":10,"no":26,"section":"多选","sectionNo":6,"type":"multi","score":4,"stem":"关于学习策略的表述，正确的有（  ）。","options":["列提纲、归类整理属于认知策略","自我提问、自我检查属于元认知策略","时间安排、环境管理属于资源管理策略","单纯机械抄写一定属于元认知策略"],"answer":["A","B","C"],"analysis":"列提纲与归类整理属认知策略，自我提问与自我检查属元认知策略，时间安排与环境管理属资源管理策略，A、B、C正确。D错误：机械抄写不是元认知策略，且“一定”表述绝对化。","hint":"三类策略要分清：认知、元认知、资源管理。","tags":["学习策略","元认知策略"],"category":"教育心理"},{"id":"L10-M07","source":"local","sourceLabel":"（本地：第10卷第27题）","vol":10,"no":27,"section":"多选","sectionNo":7,"type":"multi","score":4,"stem":"学生在学习新知识时，常常不自觉套用旧方法，结果造成判断或操作错误。这种现象很可能受到（  ）的影响。","options":["定势","负迁移","原型启发","正迁移"],"answer":["A","B"],"analysis":"不自觉套用旧方法导致错误，一方面是心理定势（习惯化的思维倾向）的影响，另一方面是旧经验对新学习的干扰，即负迁移。原型启发是促进问题解决的因素，正迁移是促进作用，均不合题意。","hint":"套用旧方法出错=定势+负迁移。","tags":["问题解决","学习迁移","定势"],"category":"教育心理"},{"id":"L10-M08","source":"local","sourceLabel":"（本地：第10卷第28题）","vol":10,"no":28,"section":"多选","sectionNo":8,"type":"multi","score":4,"stem":"为了提高学生在学习任务中的有意注意，教师可采用的做法有（  ）。","options":["在任务开始前明确目标与要求","将讲解、操作与反馈安排成适当节奏","通过呈现方式的适度变化保持新颖性","通过持续加大学习负荷使学生保持紧张"],"answer":["A","B","C"],"analysis":"维持有意注意的做法：任务前明确目标与要求、把讲解操作与反馈安排成适当节奏、通过呈现方式的变化保持新颖性，A、B、C正确。D“持续加大学习负荷”会造成疲劳，反而削弱注意，故排除。","hint":"靠加压制造紧张不利于维持注意。","tags":["注意","有意注意"],"category":"教育心理"},{"id":"L10-M09","source":"local","sourceLabel":"（本地：第10卷第29题）","vol":10,"no":29,"section":"多选","sectionNo":9,"type":"multi","score":4,"stem":"以下哪些行为符合教育家精神？（  ）。","options":["因材施教","关爱学生","终身学习","教学相长"],"answer":["A","B","C","D"],"analysis":"因材施教、关爱学生、终身学习、教学相长都体现了教育家精神的内涵，四项均符合。","hint":"教育家精神涵盖育人、关爱、学习、共进。","tags":["教师职业道德","教育家精神"],"category":"教师职业道德"},{"id":"L10-M10","source":"local","sourceLabel":"（本地：第10卷第30题）","vol":10,"no":30,"section":"多选","sectionNo":10,"type":"multi","score":4,"stem":"在使用数字学习工具辅助学习时，较为恰当的做法有（  ）。","options":["对工具输出结果进行核对和判断","将工具结果与教材、课堂所学相互印证","直接照抄生成内容即可视为完成学习","把工具作为辅助而非完全替代独立思考"],"answer":["A","B","D"],"analysis":"使用数字学习工具的正确做法：对输出结果进行核对判断、与教材和课堂所学相互印证、把工具作为辅助而非替代独立思考，A、B、D正确。C“直接照抄生成内容”违背学习伦理与学术规范，故排除。","hint":"照抄生成内容当作自己完成学习，必错。","tags":["学习方式","数字素养"],"category":"教学技能与实践"}]};
